INSERT INTO `activity_details` VALUES ('00000000-0000-4000-8000-000000000302','10000000-0000-4000-8000-000000000022','school_only','Kỹ thuật','Kỹ thuật','Thực hành Python qua các bài toán ứng dụng gần gũi.','Phòng máy thực hành, hướng dẫn từng bước và phần trình bày sản phẩm cuối buổi.','[\"Lập trình theo nhóm\", \"Sửa lỗi chương trình\", \"Trình bày sản phẩm\"]','[\"Python\", \"Tư duy logic\", \"Làm việc nhóm\"]','[\"Đang theo học tại TalentHub Test School\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng máy A201','Khuôn viên TalentHub Test School','in_person',NULL,'TalentHub Test School','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/talenthub-python-workshop.webp','Minh họa cho hoạt động Workshop Lập trình Python Ứng dụng',0.00,'VND','Người học đang theo học tại TalentHub Test School','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('21000000-04ed-44b5-82fd-0db8f8fd3b05','20000000-0000-4000-8000-000000000050','school_only','Kỹ thuật','Kỹ thuật','Dự án robot cứu hộ đã hoàn thành của học sinh Nguyễn Trãi.','Hoạt động lịch sử lưu lại kết quả thiết kế, thử nghiệm và báo cáo của các đội tham gia.','[\"Thiết kế robot\", \"Thử nghiệm cứu hộ\", \"Báo cáo kết quả\"]','[\"Robotics\", \"Giải quyết vấn đề\", \"Làm việc nhóm\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng STEM B305','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-python-robot.webp','Minh họa cho hoạt động Dự án Robot cứu hộ',0.00,'VND','Người học đang theo học tại THPT Nguyễn Trãi','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('21000000-8e2d-4dae-8d47-ea4ac11c3dc3','20000000-0000-4000-8000-000000000052','school_only','Kinh doanh','Kinh doanh','Phát triển ý tưởng kinh doanh từ nhu cầu thực tế của học sinh.','Các đội xây dựng mô hình giá trị, dự toán cơ bản và thuyết trình trước hội đồng phản biện.','[\"Xác định vấn đề\", \"Lập mô hình kinh doanh\", \"Pitching ý tưởng\"]','[\"Khởi nghiệp\", \"Tài chính cơ bản\", \"Thuyết trình\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Hội trường B','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-young-business.webp','Minh họa cho hoạt động Thử thách Doanh nhân trẻ',0.00,'VND','Người học đang theo học tại THPT Nguyễn Trãi','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('22000000-b817-48d3-8ab2-6b7dc54cd16e','22000000-dc34-49ed-81d4-78446b313553','school_only','Sáng tạo','Sáng tạo','Trình diễn sản phẩm âm nhạc do sinh viên phối hợp thực hiện.','Người tham gia chuẩn bị tiết mục, hoàn thiện kỹ năng sân khấu và chia sẻ quy trình sáng tạo.','[\"Chuẩn bị tiết mục\", \"Biểu diễn nhóm\", \"Chia sẻ hậu trường\"]','[\"Âm nhạc\", \"Biểu diễn\", \"Hợp tác\"]','[\"Đang theo học tại Đại học FPT\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Studio âm nhạc FPT','Khuôn viên Đại học FPT','in_person',NULL,'Đại học FPT','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/fpt-music-showcase.webp','Minh họa cho hoạt động FPTU Music Studio Showcase',0.00,'VND','Người học đang theo học tại Đại học FPT','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('22000000-e945-49ac-857c-af53ffef54f0','22000000-0b50-4a89-89bc-52db15918c03','school_only','Kỹ thuật','Kỹ thuật','Hackathon cộng đồng đã hoàn thành của sinh viên Đại học FPT.','Hoạt động lịch sử ghi nhận quá trình phát triển giải pháp số và phần trình bày của các nhóm.','[\"Xác định bài toán\", \"Xây dựng nguyên mẫu\", \"Trình bày giải pháp\"]','[\"Phát triển phần mềm\", \"Đổi mới sáng tạo\", \"Làm việc nhóm\"]','[\"Đang theo học tại Đại học FPT\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Khu học tập sáng tạo FPT','Khuôn viên Đại học FPT','in_person',NULL,'Đại học FPT','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/fpt-ai-hacklab.webp','Minh họa cho hoạt động FPTU Hackathon vì cộng đồng',0.00,'VND','Người học đang theo học tại Đại học FPT','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000022','school_only','Kỹ thuật','Kỹ thuật','Khám phá cảm biến và lắp ráp robot tự hành theo đội.','Người học lắp ráp mô hình, lập trình điều khiển và thử nghiệm robot trên sa bàn.','[\"Lắp ráp mô hình\", \"Lập trình điều khiển\", \"Chạy thử trên sa bàn\"]','[\"Robotics\", \"Điện tử cơ bản\", \"Hợp tác\"]','[\"Đang theo học tại TalentHub Test School\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng STEM A305','Khuôn viên TalentHub Test School','in_person',NULL,'TalentHub Test School','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/talenthub-stem-robotics.webp','Minh họa cho hoạt động STEM Robotics: Chế tạo Robot Tự hành',0.00,'VND','Người học đang theo học tại TalentHub Test School','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000022','school_only','Kinh doanh','Kinh doanh','Lập kế hoạch truyền thông số cho một dự án học đường.','Các đội xác định đối tượng, xây dựng thông điệp và thử nghiệm lịch nội dung truyền thông.','[\"Phân tích người xem\", \"Viết thông điệp\", \"Lập lịch nội dung\"]','[\"Digital Marketing\", \"Giao tiếp\", \"Lập kế hoạch\"]','[\"Đang theo học tại TalentHub Test School\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng đa năng A102','Khuôn viên TalentHub Test School','in_person',NULL,'TalentHub Test School','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/talenthub-digital-marketing.webp','Minh họa cho hoạt động Digital Marketing cho Dự án Học đường',0.00,'VND','Người học đang theo học tại TalentHub Test School','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000022','school_only','Sáng tạo','Sáng tạo','Tạo bộ nhận diện cá nhân thể hiện sở thích và thế mạnh.','Người học thực hành chọn màu sắc, kiểu chữ và bố cục để tạo một hồ sơ thương hiệu cá nhân.','[\"Xây dựng moodboard\", \"Thiết kế nhận diện\", \"Nhận phản hồi\"]','[\"Thiết kế đồ họa\", \"Sáng tạo\", \"Tự thể hiện\"]','[\"Đang theo học tại TalentHub Test School\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Xưởng sáng tạo A103','Khuôn viên TalentHub Test School','in_person',NULL,'TalentHub Test School','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/talenthub-creative-studio.webp','Minh họa cho hoạt động Creative Studio: Thiết kế Thương hiệu Cá nhân',0.00,'VND','Người học đang theo học tại TalentHub Test School','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000022','school_only','Cộng đồng','Cộng đồng','Đề xuất một giải pháp xanh thiết thực cho khuôn viên trường.','Các nhóm khảo sát vấn đề, thiết kế giải pháp và trình bày kế hoạch triển khai có thể thực hiện.','[\"Khảo sát thực địa\", \"Thiết kế giải pháp\", \"Thuyết trình dự án\"]','[\"Phát triển bền vững\", \"Nghiên cứu\", \"Lãnh đạo\"]','[\"Đang theo học tại TalentHub Test School\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Sân sinh hoạt chung','Khuôn viên TalentHub Test School','in_person',NULL,'TalentHub Test School','Liên hệ đơn vị tổ chức',NULL,NULL,'/app/learner/assets/activities/covers/talenthub-green-school.webp','Minh họa cho hoạt động Dự án Cộng đồng Trường học Xanh',0.00,'VND','Người học đang theo học tại TalentHub Test School','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000052','school_only','Kỹ thuật','Kỹ thuật','Thực hành lập trình Python và điều khiển mô hình robot.','Người học làm quen với Python, lắp ráp mô hình và lập trình các chuyển động cơ bản theo nhóm.','[\"Lắp ráp mô hình\", \"Lập trình điều khiển\", \"Trình bày kết quả\"]','[\"Python\", \"Robotics\", \"Làm việc nhóm\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng STEM B305','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-python-robot.webp','Minh họa cho hoạt động Python & Robot Lab Nguyễn Trãi',0.00,'VND','Người học đang theo học tại THPT Nguyễn Trãi','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000006','20000000-0000-4000-8000-000000000052','school_only','Sáng tạo','Sáng tạo','Thiết kế poster rõ thông điệp cho một chiến dịch trong trường.','Hoạt động hướng dẫn bố cục, màu sắc và quy trình nhận phản hồi để hoàn thiện poster truyền thông.','[\"Phác thảo ý tưởng\", \"Thiết kế poster\", \"Phản biện sản phẩm\"]','[\"Thiết kế đồ họa\", \"Truyền thông\", \"Sáng tạo\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Phòng nghệ thuật B204','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-poster-design.webp','Minh họa cho hoạt động Thiết kế Poster Truyền thông Học đường',0.00,'VND','Người học đang theo học tại THPT Nguyễn Trãi','Minh chứng tham gia trên TalentHub','2026-08-25 10:32:44.731024','2026-08-25 10:32:44.731024'),('31000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000052','school_only','Cộng đồng','Cộng đồng','Cùng khảo sát và thực hiện một sáng kiến xanh cho sân trường.','Các đội chọn một điểm cần cải thiện, lập kế hoạch hành động và chia sẻ tác động dự kiến.','[\"Khảo sát sân trường\", \"Lập kế hoạch xanh\", \"Chia sẻ tác động\"]','[\"Môi trường\", \"Tổ chức dự án\", \"Trách nhiệm cộng đồng\"]','[\"Đang theo học tại THPT Nguyễn Trãi\", \"Đăng ký trước thời hạn của hoạt động\"]','[\"Xác nhận giờ trải nghiệm sau check-in\", \"Minh chứng tham gia trên TalentHub\"]','Sân trường Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','in_person',NULL,'THPT Nguyễn Trãi','Liên hệ THPT Nguyễn Trãi: c3-nguyentrai@hcm.edu.vn, 028-3863-1234','c3-nguyentrai@hcm.edu.vn','028-3863-1234','/app/learner/assets/activities/covers/nguyen-trai-green-campus.webp','Minh họa cho hoạ