CREATE TABLE `assessments` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `teacherId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `activityId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `overallScore` decimal(5,2) DEFAULT NULL,
  `comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `publishedAt` datetime(6) DEFAULT NULL,
  `version` int unsigned NOT NULL DEFAULT '1',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assessments_teacher_student_activity` (`teacherId`,`studentId`,`activityId`),
  KEY `idx_assessments_teacher_status_updated` (`teacherId`,`status`,`updatedAt`),
  KEY `idx_assessments_student_status` (`studentId`,`status`),
  KEY `idx_assessments_registration` (`activityId`,`studentId`),
  CONSTRAINT `fk_assessments_registration` FOREIGN KEY (`activityId`, `studentId`) REFERENCES `activity_registrations` (`activityId`, `studentId`) ON UPDATE CASCADE,
  CONSTRAINT `fk_assessments_teacher` FOREIGN KEY (`teacherId`) REFERENCES `teacher_profiles` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_assessments_overall_score` CHECK (((`overallScore` is null) or ((`overallScore` >= 0) and (`overallScore` <= 100)))),
  CONSTRAINT `chk_assessments_publish_data` CHECK (((`status` = _utf8mb4'draft') or ((`overallScore` is not null) and (`publishedAt` is not null)))),
  CONSTRAINT `chk_assessments_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
