--
-- Table structure for table `career_role_assessment_signals`
--

DROP TABLE IF EXISTS `career_role_assessment_signals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `career_role_assessment_signals` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `roleId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `assessmentFamily` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dimensionCode` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `targetScore` decimal(5,2) NOT NULL,
  `weight` decimal(5,2) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_career_role_assessment_signals_role_family_dimension` (`roleId`,`assessmentFamily`,`dimensionCode`),
  KEY `idx_career_role_assessment_signals_family` (`assessmentFamily`,`dimensionCode`),
  CONSTRAINT `fk_career_role_assessment_signals_role` FOREIGN KEY (`roleId`) REFERENCES `career_role_benchmarks` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_career_role_assessment_signals_dimension` CHECK ((((`assessmentFamily` = _utf8mb4'holland') and (`dimensionCode` in (_utf8mb4'R',_utf8mb4'I',_utf8mb4'A',_utf8mb4'S',_utf8mb4'E',_utf8mb4'C'))) or ((`assessmentFamily` = _utf8mb4'mbti') and (`dimensionCode` in (_utf8mb4'E',_utf8mb4'I',_utf8mb4'S',_utf8mb4'N',_utf8mb4'T',_utf8mb4'F',_utf8mb4'J',_utf8mb4'P'))) or ((`assessmentFamily` = _utf8mb4'disc') and (`dimensionCode` in (_utf8mb4'D',_utf8mb4'I',_utf8mb4'S',_utf8mb4'C'))) or ((`assessmentFamily` = _utf8mb4'multiple_intelligence') and (`dimensionCode` in (_utf8mb4'LOGI',_utf8mb4'LING',_utf8mb4'SPAT',_utf8mb4'MUSIC',_utf8mb4'BODY',_utf8mb4'INTER',_utf8mb4'INTRA',_utf8mb4'NAT'))))),
  CONSTRAINT `chk_career_role_assessment_signals_family` CHECK ((`assessmentFamily` in (_utf8mb4'holland',_utf8mb4'mbti',_utf8mb4'disc',_utf8mb4'multiple_intelligence'))),
  CONSTRAINT `chk_career_role_assessment_signals_target` CHECK (((`targetScore` >= 0) and (`targetScore` <= 100))),
  CONSTRAINT `chk_career_role_assessment_signals_weight` CHECK (((`weight` > 0) and (`weight` <= 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

