INSERT INTO `enterprises` VALUES ('10000000-0000-4000-8000-000000000003','FPT Software','active','/assets/images/fpt-software-logo.svg','Công nghệ thông tin & Dịch vụ phần mềm','10,000+ nhân viên',1999,'FPT Software là công ty công nghệ và dịch vụ CNTT hàng đầu thế giới có trụ sở chính tại Việt Nam, tiên phong trong chuyển đổi số, AI và đào tạo phát triển tài năng trẻ.','business@test.talenthub.local','024 7300 7575','https://fptsoftware.com','0101234567','Tòa nhà FPT, Phố Duy Tân, Phường Dịch Vọng Hậu, Quận Cầu Giấy, Hà Nội','verified',NULL,NULL,NULL,'2026-08-16 02:32:12.640493','2026-08-31 09:44:09.903024'),('32000000-0000-4000-8000-000000000002','VNG Corporation','active','/assets/images/vng-logo.svg','Công nghệ, Game & Giải trí số','3,000+ nhân viên',2004,'VNG là kỳ lân công nghệ đầu tiên của Việt Nam, dẫn đầu trong lĩnh vực phát triển Game số, nền tảng giao tiếp Zalo, giải pháp đám mây và thanh toán điện tử.','vng.careers@talenthub.local','028 3962 3888','https://vng.com.vn','0303815871','VNG Campus, Đường số 13, Khu chế xuất Tân Thuận, Quận 7, TP. Hồ Chí Minh','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-31 09:44:09.903024'),('32000000-0000-4000-8000-000000000003','Công ty Cổ phần Sữa Việt Nam (Vinamilk)','active','/assets/images/vinamilk-logo.svg','Hàng tiêu dùng nhanh (FMCG), Kinh tế & Quản trị Chuỗi cung ứng','10,000+ nhân viên',2015,'Công ty Cổ phần Sữa Việt Nam (Vinamilk) là doanh nghiệp dinh dưỡng hàng đầu Việt Nam và thuộc Top 40 công ty sữa lớn nhất thế giới, tiên phong đổi mới sáng tạo, phát triển bền vững và đào tạo thế hệ tài năng kinh tế, marketing và chuỗi cung ứng.','vinamilk@talenthub.local','028 5415 5555','https://www.vinamilk.com.vn','0300588569','Số 10 Tân Trào, Phường Tân Phú, Quận 7, TP. Hồ Chí Minh','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-31 09:44:09.903024'),('32000000-0000-4000-8000-000000000004','Ngân hàng TMCP Kỹ thương Việt Nam (Techcombank)','active','/assets/images/techcombank-logo.svg','Tài chính, Ngân hàng & Công nghệ tài chính (Fintech)','12,000+ nhân viên',1993,'Techcombank là một trong những ngân hàng cổ phần lớn nhất Việt Nam, tiên phong trong hành trình chuyển đổi số toàn diện với ngân hàng số Techcombank Mobile và giải pháp tài chính vượt trội.','techcombank.careers@talenthub.local','024 3944 6368','https://techcombank.com','0100230800','Số 6 Quang Trung, Phường Trần Hưng Đạo, Quận Hoàn Kiếm, Hà Nội','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-26 07:10:33.081182'),('32000000-0000-4000-8000-000000000005','Công ty TNHH Phần mềm FPT','active','/assets/images/fpt-software-logo.svg','Công nghệ thông tin & Trí tuệ nhân tạo (IT & AI)','10,000+ nhân viên',2014,'FPT Software là công ty công nghệ và dịch vụ phần mềm hàng đầu thế giới có trụ sở chính tại Việt Nam, tiên phong trong chuyển đổi số, AI và đào tạo phát triển tài năng trẻ.','fpt@talenthub.local','024 7300 7575','https://fptsoftware.com','0101234567','Tòa nhà FPT, Phố Duy Tân, Phường Dịch Vọng Hậu, Quận Cầu Giấy, Hà Nội','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-31 09:44:09.903024'),('32000000-0000-4000-8000-000000000006','Tập đoàn Truyền thông & Quảng cáo Dentsu Vietnam','active','/assets/images/dentsu-logo.svg','Truyền thông, Quảng cáo & Sáng tạo nội dung','600+ nhân viên',2003,'Dentsu Vietnam trực thuộc mạng lưới Dentsu Quốc tế, cung cấp các giải pháp marketing số tích hợp, sáng tạo nội dung truyền thông, thiết kế thương hiệu và chiến lược tăng trưởng khách hàng.','dentsu.careers@talenthub.local','028 3821 9000','https://dentsu.com','0302821415','Tầng 16, Tòa nhà Vincom Center, 72 Lê Thánh Tôn, Bến Nghé, Quận 1, TP. Hồ Chí Minh','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-31 09:44:09.903024'),('32000000-0000-4000-8000-000000000020','Ngân hàng TMCP Quân đội (MB Bank)','active','/assets/images/mbbank-logo.svg','Tài chính, Ngân hàng số & Fintech','15,000+ nhân viên',1994,'Ngân hàng TMCP Quân đội (MB Bank) là một trong những định chế tài chính - ngân hàng số hàng đầu Việt Nam, tiên phong trong ứng dụng công nghệ Fintech, phục vụ hơn 25 triệu khách hàng và thúc đẩy phát triển kinh tế số.','mbbank@talenthub.local','1900 545426','https://mbbank.com.vn','0100283873','Tòa nhà MB Grand Tower, Hà Nội & Chi nhánh Cần Thơ / TP.HCM','verified',NULL,NULL,NULL,'2026-08-30 13:56:30.770094','2026-08-31 09:44:09.903024');
