  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `field` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `audience` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'public',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `workType` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'full_time',
  `duration` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `educationLevel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `benefits` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `skillsJson` json NOT NULL,
  `requirementsJson` json DEFAULT NULL,
  `slots` int unsigned NOT NULL DEFAULT '1',
  `deadline` datetime(6) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_internship_posts_enterprise` (`enterpriseId`),
  KEY `idx_internship_posts_status_deadline` (`status`,`deadline`),
  KEY `idx_internship_post_audience_status` (`audience`,`status`,`enterpriseId`),
  CONSTRAINT `fk_internship_posts_enterprise` FOREIGN KEY (`enterpriseId`) REFERENCES `enterprises` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_internship_post_audience` CHECK ((`audience` in (_utf8mb4'public',_utf8mb4'partner_schools'))),
  CONSTRAINT `chk_internship_posts_requirements_json` CHECK (((`requirementsJson` is null) or json_valid(`requirementsJson`))),
  CONSTRAINT `chk_internship_posts_skills_json` CHECK (json_valid(`skillsJson`)),
  CONSTRAINT `chk_internship_posts_slots` CHECK ((`slots` > 0)),
  CONSTRAINT `chk_internship_posts_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'active',_utf8mb4'closed',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

