--
-- Table structure for table `learner_ai_roadmap_refinements`
--

DROP TABLE IF EXISTS `learner_ai_roadmap_refinements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_roadmap_refinements` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `roadmapId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `baseVersion` int unsigned NOT NULL,
  `learnerDraftHash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `learnerDraftJson` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `aiDraftHash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `aiDraftJson` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `modelVersion` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `promptVersion` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerRequestId` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `responseHash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expiresAt` datetime(6) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_learner_ai_roadmap_refinements_owner_expiry` (`studentId`,`expiresAt`),
  KEY `idx_learner_ai_roadmap_refinements_base` (`roadmapId`,`studentId`,`baseVersion`),
  CONSTRAINT `fk_learner_ai_roadmap_refinements_roadmap_owner` FOREIGN KEY (`roadmapId`, `studentId`) REFERENCES `learner_ai_roadmaps` (`id`, `studentId`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_roadmap_refinements_ai_hash` CHECK (regexp_like(`aiDraftHash`,_utf8mb4'^[a-f0-9]{64}$')),
  CONSTRAINT `chk_learner_ai_roadmap_refinements_ai_json` CHECK (json_valid(`aiDraftJson`)),
  CONSTRAINT `chk_learner_ai_roadmap_refinements_base_version` CHECK ((`baseVersion` >= 1)),
  CONSTRAINT `chk_learner_ai_roadmap_refinements_learner_hash` CHECK (regexp_like(`learnerDraftHash`,_utf8mb4'^[a-f0-9]{64}$')),
  CONSTRAINT `chk_learner_ai_roadmap_refinements_learner_json` CHECK (json_valid(`learnerDraftJson`)),
  CONSTRAINT `chk_learner_ai_roadmap_refinements_response_hash` CHECK (regexp_like(`responseHash`,_utf8mb4'^[a-f0-9]{64}$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

