INSERT INTO `learner_ai_roadmap_refinements` VALUES ('37f2886e-9b82-4242-bfb1-f914ff7c7b8c','22000000-53d8-4897-8d68-ab3f78db0ce9','a9daac63-46f1-4720-9ca0-b9e3e84bf7ba',13,'3296d84c04f1efe265ffee1277e72788adaa68fb10adf3815b4ed7334dd9af45','{\"phases\":[{\"phase_id\":\"99c36e53-3fc3-4e64-b086-7d08834836a8\",\"position\":1,\"start_day\":0,\"end_day\":30,\"code\":\"discover\",\"title\":\"Khám phá nền tảng và định hình ý tưởng\",\"goal\":\"Thiết lập nền tảng kỹ năng phân tích, định vị các công cụ số và hoàn thành đề cương giải pháp sản phẩm đầu tiên, ưu tiên xây dựng nền tảng phù hợp với Ưu tiên xác định một kết quả học tập có thể kiểm chứng ở cuối chặng đầu.mục tiêu cá nhân.\",\"skill_focus\":\"Nghiên cứu yêu cầu người dùng, xây dựng sơ đồ tư duy logic và thiết kế wireframe cơ bản\",\"deliverable\":\"Tài liệu mô tả yêu cầu sản phẩm (PRD) và bản phác thảo giao diện cơ bản (wireframe)\",\"effort_label\":\"3–4 giờ/tuần\",\"metric_label\":\"Hoàn thành 100% tài liệu phác thảo ý tưởng trước mốc ngày thứ 30\",\"tasks\":[{\"task_id\":\"5968eff3-21b1-4b11-8c61-bde36a1b6b8c\",\"position\":1,\"title\":\"Phân tích 3 sản phẩm số tiêu biểu và lập bảng so sánh tính năng\",\"description\":\"Lựa chọn 3 ứng dụng phổ biến trên thị trường, phân tích luồng trải nghiệm người dùng và tổng hợp ưu, nhược điểm vào bảng so sánh chi tiết.\",\"milestone_day\":7,\"estimated_minutes\":60},{\"task_id\":\"18b4d7fc-7954-4ebd-9721-1689cdb4ac26\",\"position\":2,\"title\":\"Phác thảo sơ đồ cấu trúc thông tin cho ý tưởng dự án cá nhân\",\"description\":\"Sử dụng công cụ sơ đồ tư duy để vẽ cấu trúc luồng người dùng và xác định các chức năng chính của sản phẩm học tập dự kiến triển khai.\",\"milestone_day\":14,\"estimated_minutes\":90},{\"task_id\":\"49fd38e8-70fb-42a9-8357-df11f77575f5\",\"position\":3,\"title\":\"Đăng ký tham gia hoạt động AI Hacklab để mở rộng góc nhìn công nghệ\",\"description\":\"Ghi danh tham gia hoạt động AI Hacklab tại Innovation Lab nhằm cọ xát kiến thức thực tế và kết nối cùng cộng đồng học thuật.\",\"milestone_day\":30,\"estimated_minutes\":120}]},{\"phase_id\":\"a1f141bf-108c-44d2-abc5-23b0ac7de6e7\",\"position\":2,\"start_day\":31,\"end_day\":60,\"code\":\"practice\",\"title\":\"Thực hành chuyên sâu và tạo mẫu thử nghiệm\",\"goal\":\"Chuyển hóa ý tưởng thành bản mẫu tương tác thực tế, đồng thời nâng cao kỹ năng phối hợp nhóm trong môi trường dự án nhỏ và kiểm chứng kết quả qua Bổ sung một lần nhận phản hồi thực tế để điều chỉnh cách thực hiện.phản hồi thực tế.\",\"skill_focus\":\"Thiết kế giao diện tương tác (UI/UX), xử lý dữ liệu và kỹ năng cộng tác nhóm\",\"deliverable\":\"Bộ nguyên mẫu tương tác (interactive prototype) kèm báo cáo kiểm thử người dùng\",\"effort_label\":\"4–5 giờ/tuần\",\"metric_label\":\"Thực hiện ít nhất 3 phiên thử nghiệm phản hồi người dùng trước mốc ngày thứ 60\",\"tasks\":[{\"task_id\":\"74a6ceb7-1f85-4955-a8b5-856371ee9e83\",\"position\":1,\"title\":\"Xây dựng bộ giao diện tương tác hoàn chỉnh có thể thao tác\",\"description\":\"Thiết kế tối thiểu 5 màn hình chính của giải pháp số trên công cụ thiết kế chuyên dụng với hệ thống màu sắc và bố cục nhất quán.\",\"milestone_day\":45,\"estimated_minutes\":120},{\"task_id\":\"7ecf641b-3f7f-4343-9142-9322a43bb697\",\"position\":2,\"title\":\"Đăng ký tham gia hoạt động Product Sprint để hoàn thiện quy trình sản phẩm\",\"description\":\"Ghi danh tham gia chương trình Product Sprint tại Product Lab FPT để trải nghiệm phương pháp phát triển sản phẩm theo chu trình lặp nhanh.\",\"milestone_day\":50,\"estimated_minutes\":120},{\"task_id\":\"7c6959f1-2120-4174-a042-7e70f0d622a8\",\"position\":3,\"title\":\"Tổ chức phiên phản biện chéo và ghi nhận đóng góp cải tiến\",\"description\":\"Thu thập ý kiến đóng góp từ 3 bạn học hoặc giảng viên hướng dẫn về nguyên mẫu đã hoàn thành, sau đó tổng hợp thành danh sách các điểm cần cải tiến.\",\"milestone_day\":60,\"estimated_minutes\":90}]},{\"phase_id\":\"eadaca9b-f2d1-43bd-8850-628621cc2b3f\",\"position\":3,\"start_day\":61,\"end_day\":90,\"code\":\"breakthrough\",\"title\":\"Đột phá sản phẩm và hoàn thiện hồ sơ năng lực\",\"goal\":\"Đóng gói sản phẩm hoàn chỉnh, tổng kết kết quả học tập và định hình hồ sơ Hoàn thiện minh chứng và ghi lại bài học để sử dụng trong hồ sơ năng lực.năng lực cá nhân sẵn sàng cho các cơ hội nghề nghiệp tiếp theo.\",\"skill_focus\":\"Thuyết trình giải pháp kỹ thuật, phân tích dữ liệu kết quả và đóng gói portfolio\",\"deliverable\":\"Hồ sơ dự án chi tiết (case study) và slide thuyết trình sản phẩm hoàn chỉnh\",\"effort_label\":\"3–4 giờ/tuần\",\"metric_label\":\"Hoàn tất 1 bài trình bày dự án đạt chuẩn đánh giá chuyên môn trước mốc ngày thứ 90\",\"tasks\":[{\"task_id\":\"7bbc78e7-32d7-4cc4-994a-56712e53869b\",\"position\":1,\"title\":\"Tổng hợp số liệu và phân tích kết quả thử nghiệm dự án\",\"description\":\"Thống kê mức độ hài lòng, thời gian hoàn thành tác vụ của người dùng trên bản mẫu và lập biểu đồ trực quan hóa dữ liệu thu được.\",\"milestone_day\":75,\"estimated_minutes\":90},{\"task_id\":\"6ea73e41-e2f0-4ff1-81ee-00584932f224\",\"position\":2,\"title\":\"Biên soạn tài liệu Case Study chi tiết cho đồ án\",\"description\":\"Trình bày toàn bộ hành trình giải quyết vấn đề từ bối cảnh, giải pháp thiết kế, mã nguồn đến kiến trúc hệ thống thành một bài viết hoàn chỉnh.\",\"milestone_day\":85,\"estimated_minutes\":120},{\"task_id\":\"dcdbbf14-8959-40c2-a011-2eacce721ec6\",\"position\":3,\"title\":\"Tập dượt bài thuyết trình giới thiệu sản phẩm trong 10 phút\",\"description\":\"Chuẩn bị slide súc tích và tự ghi hình bài thuyết trình giới thiệu dự án để hoàn thiện kỹ năng diễn đạt tự tin, thuyết phục.\",\"milestone_day\":90,\"estimated_minutes\":60}]}]}','999f376010f07feaa1aac3be74cef21299036054d74edea2ecee140130f56fd0','{\"phases\":[{\"phase_id\":\"99c36e53-3fc3-4e64-b086-7d08834836a8\",\"position\":1,\"start_day\":0,\"end_day\":30,\"code\":\"discover\",\"title\":\"Khám phá nền tảng và định hình ý tưởng\",\"goal\":\"Thiết lập nền tảng kỹ năng phân tích, định vị các công cụ