DROP TABLE IF EXISTS `learner_ai_roadmap_task_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_roadmap_task_events` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `taskId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `requestId` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `occurredAt` datetime(6) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_roadmap_task_events_request` (`taskId`,`requestId`),
  KEY `idx_learner_ai_roadmap_task_events_task_occurred` (`taskId`,`occurredAt`),
  KEY `idx_learner_ai_roadmap_task_events_student_created` (`studentId`,`createdAt`),
  CONSTRAINT `fk_learner_ai_roadmap_task_events_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_ai_roadmap_task_events_task` FOREIGN KEY (`taskId`) REFERENCES `learner_ai_roadmap_tasks` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_roadmap_task_events_status` CHECK ((`status` in (_utf8mb4'in_progress',_utf8mb4'completed',_utf8mb4'skipped')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
