DROP TABLE IF EXISTS `learner_ai_roadmap_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_roadmap_tasks` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `phaseId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` tinyint unsigned NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(1500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `estimatedMinutes` smallint unsigned NOT NULL,
  `actionType` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `targetType` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `targetId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evidenceJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_roadmap_tasks_position` (`phaseId`,`position`),
  KEY `idx_learner_ai_roadmap_tasks_phase` (`phaseId`),
  CONSTRAINT `fk_learner_ai_roadmap_tasks_phase` FOREIGN KEY (`phaseId`) REFERENCES `learner_ai_roadmap_phases` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_roadmap_tasks_action` CHECK ((((`actionType` = _utf8mb4'self_task') and (`targetType` is null) and (`targetId` is null)) or ((`actionType` = _utf8mb4'register_activity') and (`targetType` = _utf8mb4'activity') and (`targetId` is not null)))),
  CONSTRAINT `chk_learner_ai_roadmap_tasks_evidence_json` CHECK (json_valid(`evidenceJson`)),
  CONSTRAINT `chk_learner_ai_roadmap_tasks_minutes` CHECK ((`estimatedMinutes` between 5 and 1440)),
  CONSTRAINT `chk_learner_ai_roadmap_tasks_position` CHECK ((`position` between 1 and 10))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `learner_ai_roadmap_tasks`
--

LOCK TABLES `learner_ai_roadmap_tasks` WRITE;
/*!40000 ALTER TABLE `learner_ai_roadmap_tasks` DISABLE KEYS */;
INSERT INTO `learner_ai_roadmap_tasks` VALUES ('005edd80-c2c1-4f65-b7b7-71b085d0852f','2c4c6679-2259-4015-8ce7-38e8937d7023',2,'Thiết kế khung sơ đồ trực quan cho giải pháp (Mốc 50 ngày)','Sử dụng công cụ thiết kế sơ đồ (Miro hoặc Figma) để trực quan hóa quy trình hoạt động của đề tài nhóm đang thực hiện.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-09-03 14:30:25.000000'),('00660af9-597b-4419-8e20-b221ab1b7f42','8a1de756-43cd-45d5-8aac-5a270a7d748a',2,'Chuẩn bị câu chuyện','Trình bày vấn đề, cách thử nghiệm, kết quả và bài học.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 05:08:36.000000'),('00a4d4ff-9bb7-4dc8-9458-065b42695d54','4584f55b-f360-4602-88f2-81d5dfafdd32',3,'Tổng kết kết quả 90 ngày và lập kế hoạch tiếp theo','Đánh giá lại sự tiến bộ về thói quen học tập, tư duy logic và kỹ năng cộng tác để hoàn thiện bản định hướng chặng tiếp theo.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-003\",\"evidence-004\"]','2026-08-27 09:09:29.000000'),('01d7a78f-597f-4f44-95e8-402e5dc81057','4886d51a-3099-4264-9a54-bbb54b0012eb',3,'Đánh giá và định hình mục tiêu cho giai đoạn tiếp theo','Nhìn nhận lại kết quả đạt được sau 90 ngày, đúc kết các bài học về làm việc nhóm và xác định kỹ năng trọng tâm cần bồi dưỡng thêm.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:09:11.000000'),('02b2e708-b788-454b-8835-3fa9a3745739','5f7e1713-4d7b-4846-8cf4-c8974d0f77fe',2,'Tham gia không gian phát triển sản phẩm số thực tế','Đăng ký tham gia hoạt động Product Sprint để cọ xát quy trình xây dựng sản phẩm số cùng các nhóm sinh viên khác.',180,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-038\"]','2026-09-03 14:02:44.000000'),('02c3a129-07ee-45e9-8861-898a2731fb04','c107ac33-6dcf-4833-b0c3-a61690887d9a',2,'Tham gia hoạt động trải nghiệm ứng dụng công nghệ tại Innovation Lab (Mốc 14 ngày)','Đăng ký và tham dự buổi trải nghiệm công nghệ tại trường để quan sát cách triển khai mô hình ứng dụng thông minh trong học đường.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-018\"]','2026-09-05 03:54:06.000000'),('03060aaa-bf3c-4783-b42a-3d35a6e16981','02fc279c-4625-41bd-ba0f-db58ade237af',2,'Đăng ký tham gia sự kiện trải nghiệm công nghệ ứng dụng (Mốc 14 ngày)','Ghi danh tham dự AI Hacklab để quan sát cách các đội nhóm hình thành giải pháp và tiếp cận công nghệ thông minh trong thực tế.',90,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-018\"]','2026-09-05 03:54:44.000000'),('035655cb-f2e2-4608-aa9a-03b76fb12cb5','9cba4dc2-dd9a-4453-baae-1f5db58d4515',2,'Xây dựng sơ đồ chức năng và cơ sở dữ liệu mẫu cho bài tập lớn','Phác thảo sơ đồ thực thể mối quan hệ và luồng dữ liệu cho dự án môn học nhóm trong 60 phút.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 02:49:36.000000'),('0371941c-b1c6-4e19-9d0e-5433d76599b9','2ffb28d4-2d61-493f-bbaa-32df1887cdef',2,'Xây dựng sơ đồ tư duy giải bài toán phức hợp (Mốc ngày 50)','Chọn một chủ đề khó trong chương trình lớp 12 và trực quan hóa toàn bộ quy trình giải theo dạng lưu đồ hoặc sơ đồ khối logic, kiểm tra tính ứng dụng qua 3 bài tập mẫu.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-04 14:38:51.000000'),('03b1572d-48c4-4544-883b-91cb8862f64e','2502f190-cee9-4228-af89-f0db77efc252',3,'Thực hiện phân tích dữ liệu cơ bản','Thu thập và xử lý các thông tin cần thiết phục vụ cho việc đánh giá kết quả thực hiện đề tài.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-24 15:21:04.000000'),('03cb050d-38b5-4e2f-89b5-25d495ff8ffd','f7a369a7-7220-43df-86ad-b32b56bc986b',3,'Thu thập phản hồi','Xin phản hồi từ ít nhất hai người và ghi lại điều học được.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 05:08:36.000000'),('03e92ddc-05f3-4694-9c63-1f51e4298a83','cf9ad7f5-62ae-4468-902c-757beeceacf5',3,'Ghi danh hoạt động Product Sprint: Xây dựng Sản phẩm Số','Đăng ký tham gia workshop Product Sprint nhằm nắm bắt quy trình tạo mẫu ý tưởng sản phẩm tinh gọn (Lean MVP) trong môi trường học thuật.',60,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-020\"]','2026-09-05 08:20:23.000000'),('046674c1-2493-475c-85ea-0fd0c20dd545','d931ff41-05f7-403b-bf98-8bc5ce4eaffe',2,'Phát thảo mô hình giải pháp dạng trực quan (Mốc 50 ngày)','Sử dụng công cụ thiết kế cơ bản để vẽ wireframe hoặc sơ đồ quy trình giải quyết vấn đề đã khảo sát.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:59:48.000000'),('050bc379-2465-45ab-8068-6798c71cb0b5','54876e78-8ebe-4543-bbcd-8f04d07a1ebe',1,'Chọn phản hồi ưu tiên','Phân loại phản hồi và chọn một thay đổi quan trọng.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 05:08:36.000000'),('054da976-f3ba-413a-b8ff-cc93a7b9a825','77528e34-67c6-4271-bb5c-e7a4a9e48834',3,'Thiết lập quy trình họp nhóm và phân bổ công việc tuần (Mốc 30 ngày)','Xây dựng bảng kế hoạch phối hợp nhóm gồm danh sách đầu việc, thời hạn và phân công vai trò rõ ràng để cải thiện hiệu suất làm việc chung.',45,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-006\",\"evidence-017\"]','2026-09-02 08:08:52.000000'),('058f560c-939b-4cce-8969-7ebc00869252','12fe5a17-d2b7-4345-91c7-c66ce886329b',1,'Xây dựng bản mẫu ứng dụng mini hỗ trợ lớp học (Mốc 75 ngày)','Lập trình hoàn chỉnh một mô-đun phần mềm nhỏ (ví dụ: công cụ quản lý thời gian học tập hoặc phân tích điểm số) bằng Python và kiểm thử tự động.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-017\",\"evidence-018\"]','2026-08-31 08:22:34.000000'),('05a2e563-1b81-49ec-9dbb-374a9e294899','ed6b069b-cd3a-4d0f-abbc-f014b1a9538f',1,'Xây dựng bảng phân chia công việc cho bài tập nhóm (Mốc 37 ngày)','Tạo bảng ma trận phân công trách nhiệm (RACI đơn giản) cho đồ án nhóm môn học, thống nhất hạn chót với các bạn; tiêu chí hoàn thành là bảng phân công được tất cả thành viên đồng thuận.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 08:10:24.000000'),('06a28e1c-fdad-58f4-a16c-425d01f60a07','edfca528-8316-5713-bb88-4c3af41a5371',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Chuyên viên vận hành chuỗi cung ứng và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"63a115ff-6acc-5bdb-aaf8-e6e2654ff041\"]','2026-08-25 18:49:00.000000'),('06c4099f-7d1e-4993-a77f-14fcfbe823af','018f20f9-8264-4763-90c9-a7cd6cd2ca68',3,'Xây dựng ứng dụng quản lý tác vụ học tập qua dòng lệnh','Lập trình ứng dụng console cho phép thêm, sửa, xóa và lọc bài tập theo thời hạn; áp dụng tư duy lập trình hàm rõ ràng và kiểm thử thủ công với 5 kịch bản biên.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\",\"evidence-005\"]','2026-09-05 05:46:35.000000'),('06c525ca-30db-433f-a3e5-baaf0ddfe578','2c4ffe0e-12a0-48ff-9883-bff13b099c79',3,'Xây dựng bảng kế hoạch học tập và tự đánh giá tuần (Mốc 30 ngày)','Lập thời khóa biểu biểu diễn theo màu sắc cho các tuần học tiếp theo, phân bổ rõ thời gian tự học và hoạt động ngoại khóa. Tiêu chí hoàn thành: Lịch biểu được duy trì liên tục trong 2 tuần kèm nhật ký tự đánh giá hiệu suất.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:09:49.000000'),('06cefd0b-c888-425c-b9c9-92ffc3ef1862','0c7f33e4-a21c-4947-b6ab-0dbd25544788',3,'Thiết kế bộ khung Wireframe trên công cụ thiết kế (Mốc 30 ngày)','Phác thảo cấu trúc giao diện gồm 5 màn hình chính cho ứng dụng học tập, chú trọng tính trực quan và luồng trải nghiệm người dùng.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-013\",\"evidence-014\"]','2026-08-31 04:21:44.000000'),('0751a61e-8b9d-452c-82e3-8b83dd2e5eff','4584f55b-f360-4602-88f2-81d5dfafdd32',1,'Mô phỏng bài thi thử trong điều kiện chuẩn','Tự thực hiện bài thi kiểm tra năng lực với thời gian và điều kiện nghiêm túc để đánh giá tốc độ và độ chính xác.',150,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 09:09:29.000000'),('0754f32a-4889-44b3-8ca9-c818178aed65','f36bc857-81ac-4b59-afb1-813495179c8c',2,'Tiến hành thực nghiệm và chế tạo mẫu thử','Thực hiện các bước tạo sản phẩm thử nghiệm hoặc tổng hợp số liệu thực tế dựa trên đề cương đã chuẩn bị.',120,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-27 08:08:53.000000'),('076ce55e-9ba0-4cfc-af92-d807c8e2dcfd','0c66f2a1-7332-4834-8dec-244768ebde76',3,'Viết bộ kiểm thử tự động Unit Test cho các hàm xử lý cốt lõi','Triển khai ít nhất 8 ca kiểm thử đơn vị tự động kiểm tra tính chính xác của các luồng logic nghiệp vụ và xử lý ngoại lệ (Mốc 60 ngày).',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-025\"]','2026-09-05 05:50:04.000000'),('0811bf6e-5405-4563-8bcf-87d5ffcaddfc','479428f9-204e-4750-9c78-8fb3162e811d',3,'Tổ chức buổi phản hồi thiết kế và lắng nghe ý kiến đóng góp','Trình bày bản mẫu trước 2-3 người bạn, ghi chép ít nhất 3 điểm cần tinh chỉnh và điều chỉnh lại thiết kế dựa trên góp ý.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\"]','2026-09-05 10:14:56.000000'),('0824149d-5566-46ce-a790-d013fbd42979','cbe6c769-32ba-45b4-a961-bce09427bc07',2,'Tập dượt chia sẻ và tiếp nhận phản hồi','Thực hành thuyết trình thử trước gương hoặc ghi âm để tự điều chỉnh ngôn ngữ diễn đạt gãy gọn, mạch lạc.',60,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-28 02:38:47.000000'),('08714a02-e56f-5c46-935e-ff0f9876bae6','62a1d2cd-97e8-51d8-a485-164040409753',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Kỹ sư nền tảng đám mây.',75,'self_task',NULL,NULL,'[\"d2563021-c020-5018-9bbb-b90f4627b617\"]','2026-08-25 19:03:00.000000'),('08911e7a-c539-4405-8024-67cc17b62509','954ac626-eae0-461d-9fe3-eb330a7ab030',3,'Xây dựng trang web giới thiệu bản thân bằng HTML/CSS','Viết mã nguồn cho một trang web đơn trang hiển thị mục tiêu học tập và đẩy mã lên kho lưu trữ cá nhân.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:46:02.000000'),('08998ff1-b4e5-4d72-a54a-405bd11358cf','1757e5a6-980e-4021-9f0e-b30398aed17f',1,'Xác định và mô hình hóa một vấn đề cần cải tiến','Lựa chọn một chủ đề học tập hoặc hoạt động ngoại khóa lớp 12 cần tối ưu quy trình và sử dụng sơ đồ tư duy để phân tích nguyên nhân.',75,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-27 10:39:35.000000'),('08a9b132-1737-4be3-aaf9-4e6c382aed63','0528be3b-2412-436f-a8ae-4981d9c68ed4',3,'Thực hiện buổi thuyết trình thử nghiệm và tự đánh giá năng lực (Mốc 90 ngày)','Ghi hình hoặc trình bày thử trong 10 phút trước bạn học, sau đó điền bảng tự đánh giá để đúc kết sự tiến bộ sau hành trình 90 ngày.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:59:22.000000'),('092f0ca9-8ffd-407c-8aaa-1bf5ec0bce3b','be691e0d-403d-43f0-98af-fdc971d08990',1,'Xác định chủ đề nghiên cứu và lập khung phân tích người dùng','Lựa chọn một vấn đề thực tế trong sinh hoạt học đường tại trường, xác định mục tiêu nghiên cứu và soạn bảng câu hỏi khảo sát gồm 10 câu hỏi định lượng và định tính. Đầu ra là bản phác thảo kế hoạch khảo sát được lưu trữ trên tài liệu trực tuyến.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-010\"]','2026-08-30 06:51:26.000000'),('093963d1-5ee7-5f8c-931d-77c2ba51e2c7','a4049fe8-f128-5ae8-ac64-311db2d2fd42',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Chuyên viên trải nghiệm khách hàng và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"bcb6d9fe-4413-57fb-959c-211a2e17777a\"]','2026-08-25 19:10:00.000000'),('0995f3e7-6c92-49b3-b4de-3d24fbbc80fa','ba52d42a-9e58-4087-b5c4-8f1b289f0f14',2,'Vẽ phác thảo luồng trải nghiệm người dùng (User Flow)','Sử dụng công cụ trực quan để vẽ sơ đồ 5 bước giải quyết bài toán đã xác định, tập trung vào tính mạch lạc và tiện lợi.',75,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-08-31 15:54:21.000000'),('0a2cb33f-f0dc-5325-91b1-f358cb221170','bb6a448f-787b-5b06-b94a-94683bc00d60',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Chuyên viên phân tích dữ liệu.',75,'self_task',NULL,NULL,'[\"8c169adf-2353-58f0-8b77-21719f7ce057\"]','2026-08-25 18:21:00.000000'),('0a9bfb9c-0ae0-48f1-bf67-2c65072ac9c9','de3171b5-a32d-455a-8cae-91c00760e503',3,'Đăng ký tham gia hoạt động AI Hacklab để mở rộng góc nhìn công nghệ (Mốc 30 ngày)','Ghi danh tham gia hoạt động AI Hacklab tại Innovation Lab nhằm cọ xát kiến thức thực tế và kết nối cùng cộng đồng học thuật.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-037\"]','2026-09-02 08:03:06.000000'),('0ab794cc-9baf-4f16-bda5-001d53e8e552','cb65ccec-9541-45c8-97a6-0cf68ac7f9ea',2,'Xây dựng bảng tương tác trực quan nguyên mẫu hoàn chỉnh (Mốc 45 ngày)','Hoàn thiện bộ UI Kit bao gồm bảng màu, kiểu chữ, nút bấm và liên kết hiệu ứng chuyển động mượt mà giữa các màn hình ứng dụng.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\",\"evidence-027\"]','2026-08-30 17:02:18.000000'),('0b39b71c-6c26-4d8e-a12c-35b477d75bfc','40210f19-3f63-4950-8da4-32559576b443',3,'Xây dựng slide báo cáo giải pháp có cấu trúc logic','Thiết kế bộ slide 7-10 trang trình bày rõ ràng vấn đề, phương án giải quyết và kết quả dự kiến để chuẩn bị cho buổi báo cáo trên lớp.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 07:43:33.000000'),('0b9f3bd2-2d0a-41a8-b947-6e3be4dfef18','c3c6e1aa-7d81-4496-8218-102f60fd1afa',3,'Tổng kết 90 ngày và lập kế hoạch kỳ tiếp theo (Mốc 90 ngày)','Tự đánh giá theo các chỉ số tiến bộ, viết 3 bài học kinh nghiệm và đặt mục tiêu rèn luyện cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:59:48.000000'),('0c39dc8d-e9e1-478d-a746-c0acb79e73a1','9f58267d-1f4f-4e21-befc-976ab90b52f0',2,'Xây dựng Sơ đồ Không gian Tri thức tại Mốc 14 Ngày','Hệ thống hóa kiến thức 2 chương trọng tâm môn Tự nhiên bằng sơ đồ tư duy dạng khối hình học trực quan, ghi chú các mắt xích cốt lõi.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-31 15:26:24.000000'),('0ca80f9d-a146-47f3-9bc8-5b68b7c5eba9','a327fb28-29e7-4302-8ef2-f8422c64c8f0',3,'Điều phối buổi phản biện nội bộ và hoàn thiện báo cáo (Mốc 60 ngày)','Chủ trì buổi họp nhóm thử nghiệm thuyết trình, ghi nhận đóng góp và hiệu chỉnh tài liệu báo cáo dự án lần cuối.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:23:47.000000'),('0cb9e5bb-17b5-4978-b90b-17c5a8fb997b','a8bfbfd4-92b2-49c6-a365-8a95b1a2eb67',3,'Khảo sát và phân loại các câu lạc bộ học thuật','Tìm hiểu và lập danh sách so sánh 3 câu lạc bộ công nghệ hoặc dự án tại trường phù hợp với định hướng thiết kế giải pháp.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-26 05:15:08.000000'),('0ce64ffe-e5d2-4261-9909-776d5bea41fb','32804826-c2fc-458f-8a53-f2fb1c8fab9a',3,'Đánh giá đúc kết 90 ngày và lập mục tiêu cho học kỳ kế tiếp','Tự chấm điểm mức độ hoàn thành các mục tiêu đề ra, viết bài phản tư 500 chữ và đề ra 3 ưu tiên phát triển học thuật cho kỳ học mới.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-30 07:17:58.000000'),('0cf18185-d279-44f8-a0a0-3d5743721123','584a8151-2de8-46ad-bb69-866bcc7c3eea',3,'Tổng hợp hồ sơ năng lực và định hướng cơ hội thực tập (Mốc 90 ngày)','Tổng hợp liên kết mã nguồn, hình ảnh demo vào portfolio cá nhân và chuẩn bị danh sách tiêu chí phù hợp cho các đợt ứng tuyển thực tập.',60,'self_task',NULL,NULL,'[\"evidence-012\",\"evidence-022\",\"evidence-025\"]','2026-09-04 15:03:37.000000'),('0d26e765-7809-4ed4-ab74-a5651ae815f6','4367aee4-74d0-40b0-a948-36ad425cf7df',3,'Tổng hợp bản đề cương dự án mini và lập kế hoạch rèn luyện (Mốc 30 ngày)','Viết tài liệu đề cương 2 trang mô tả mục tiêu, phương pháp thực hiện và lịch trình tự học cho 60 ngày tiếp theo để sẵn sàng bước vào giai đoạn thực hành.',75,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-30 07:59:22.000000'),('0da167a6-d4f9-4bbd-ace8-516c83e981b5','fa09eeb0-a584-46e9-9223-78b92d6e99df',2,'Thực hành thiết kế khung xương (wireframe) và phác thảo giải pháp giao diện','Sử dụng công cụ thiết kế cơ bản để vẽ lại luồng tương tác của 5 màn hình chính và viết tài liệu mô tả ngắn giải thích lý do lựa chọn bố cục cho từng tính năng.',120,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-014\"]','2026-08-29 06:39:46.000000'),('0dac9d68-7907-40ca-8a5d-db88b7e9d116','5e7268bd-3c85-453c-978a-d695a79daafb',1,'Lập bản đồ chủ đề nghiên cứu và sở thích chuyên môn','Tìm hiểu và ghi lại danh sách 5 chủ đề thuộc lĩnh vực công nghệ, thiết kế sáng tạo và phương pháp thực nghiệm để lựa chọn hướng trọng tâm.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 08:08:53.000000'),('0dad6890-78c9-4d99-8de4-a4d2e4c0e456','f96f949b-aa13-4c41-9342-a5d505219893',1,'Thiết lập bảng kế hoạch học tập và quản lý thời gian 30 ngày (Mốc 7 ngày)','Lập thời khóa biểu chi tiết kết hợp lịch học và tự học trên công cụ số, phân bổ ít nhất 6 khung giờ học tập cố định trong tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:59:48.000000'),('0e0b117f-109c-4920-ac40-4fe27391c2e7','1bd1f1c9-33c6-4d7b-99bc-8d0b0ac3ba13',1,'Thiết lập thời gian biểu và hệ thống theo dõi môn học (Mốc 7 ngày)','Lập bảng biểu phân chia khung giờ tự học, lịch học chính khóa và hạn nộp đồ án bằng công cụ bảng tính hoặc ứng dụng cá nhân; kiểm tra tiêu chí hoàn thành bằng thời khóa biểu hoàn chỉnh cho 4 tuần đầu.',60,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-28 08:10:24.000000'),('0e298bf5-cecb-40b6-9908-8c72ecfbff76','e5d72e6a-4c4a-4b0a-a459-a36b68913927',1,'Thiết lập bảng kế hoạch học tập và quản lý thời gian 30 ngày (Mốc 7 ngày)','Lập thời khóa biểu chi tiết kết hợp lịch học và tự học trên công cụ số, phân bổ ít nhất 6 khung giờ học tập cố định trong tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:23:47.000000'),('0ed5703b-b941-59a3-ab9c-7ffbc84ec60b','2ecf4e0b-fece-5678-b5ba-a22384cd5633',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"4afd7d1f-b372-543f-aa9e-bc00e34193d7\"]','2026-08-25 18:07:00.000000'),('0ef6f642-d526-43f8-89e5-8f1005171cb1','b538408d-9381-4851-bcf1-02999402d515',1,'Hoàn thiện báo cáo đề án học phần','Tổng hợp kết quả nghiên cứu và thực nghiệm thành báo cáo chuyên môn chỉn chu.',150,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 06:08:16.000000'),('0f45cfec-e8ee-4088-948b-ae83cbbb1e6c','7b030543-80a7-4176-8cbb-8ea2fb2ed9b9',2,'Viết bộ kiểm thử tự động và rà soát chất lượng mã nguồn (Mốc 50 ngày)','Xây dựng các ca kiểm thử đơn vị (Unit Test) cho các hàm xử lý trọng yếu nhằm phát hiện lỗi tiềm ẩn sớm.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 14:26:53.000000'),('0f517cdf-6c41-4ef6-93fb-06556ba6ac66','d450b365-399d-4641-8033-1a3f4a0257b3',3,'Tổng kết mốc 90 ngày và thiết lập mục tiêu học kỳ tiếp theo','Đóng gói toàn bộ sản phẩm thiết kế vào hồ sơ năng lực cá nhân và lập danh sách 3 mục tiêu kỹ năng cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-025\",\"evidence-027\"]','2026-09-03 14:02:44.000000'),('0fa869d8-e8df-4a3a-9fbf-dd4ea18a811b','24b17946-5242-47c0-8827-063fdead4de3',4,'Đối chiếu tiêu chí tuyển dụng vị trí UI/UX Trainee để định hình bước tiếp theo','Rà soát yêu cầu kỹ năng từ danh mục cơ hội thực tập nghề nghiệp, lập danh sách 3 điểm cần tiếp tục trau dồi cho học kỳ tới.',45,'self_task',NULL,NULL,'[\"evidence-043\"]','2026-08-30 18:07:57.000000'),('0ff50d09-62f5-4153-abfd-072c37cb930a','b01cf096-a8f5-4e6d-8519-04d9aca7c9e5',1,'Lập danh sách các lĩnh vực quan tâm và kỹ năng cốt lõi','Ghi chép lại các chủ đề bạn hứng thú về quản lý, công nghệ hoặc sáng tạo, đồng thời tự đánh giá mức độ thuần thục hiện tại.',60,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-24 15:40:29.000000'),('102a246b-9a8e-498a-a7bb-848f8b503b68','f9009ae4-5eee-44bb-b53a-ced9c5b7d2bd',3,'Đánh giá chất lượng mã nguồn và tối ưu hóa hiệu năng truy vấn (Mốc 60 ngày)','Thực hiện rà soát mã nguồn (code refactoring), loại bỏ các đoạn mã trùng lặp và tối ưu hóa câu truy vấn cơ sở dữ liệu dựa trên nhật ký chạy thử.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-006\"]','2026-09-05 05:53:02.000000'),('10c6b4c1-17be-459f-b21f-e70618ec9a19','8b6154bd-6c05-42ac-9919-5e05acbb1f8f',1,'Xây dựng hệ thống phong cách thị giác và linh kiện giao diện','Quy chuẩn bảng màu, kiểu chữ và bộ thư viện 12 linh kiện UI cơ bản (nút bấm, ô nhập liệu, thẻ nội dung) theo tiêu chuẩn thiết kế hiện đại. Đầu ra là trang tài liệu Design System thu nhỏ.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\"]','2026-08-30 06:51:26.000000'),('10e6dab1-d5a5-43bf-bf06-a7e2f413066d','6c120050-75da-4589-9a23-695ba8c2c87a',2,'Tham gia Product Sprint xây dựng sản phẩm số (Mốc 50 ngày)','Đăng ký tham gia chuỗi hoạt động tại Product Lab để cùng nhóm sinh viên phát triển nguyên mẫu sản phẩm dưới sự hướng dẫn chuyên môn.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-031\"]','2026-08-29 06:44:00.000000'),('1111bd21-ec77-46c6-9216-6b5d26c0b312','c2cc7c54-7026-4c2d-b1a4-150f36f869b1',2,'Phác thảo sơ đồ cấu trúc thông tin cho ý tưởng dự án cá nhân (Mốc 14 ngày)','Sử dụng công cụ sơ đồ tư duy để vẽ cấu trúc luồng người dùng và các chức năng chính của sản phẩm học tập dự kiến triển khai.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-08-31 15:59:36.000000'),('11662e41-6216-44d2-94ac-be40d4e1ea9a','53e265cc-4a04-4c30-b942-4a8f4e80c1ce',2,'Mốc 45 ngày: Lập trình dịch vụ CRUD và kiểm thử API độc lập','Hiện thực hóa các tính năng thêm, xem, sửa, xóa dữ liệu trên hệ thống; kiểm thử các yêu cầu phản hồi thông qua công cụ kiểm thử API.',105,'self_task',NULL,NULL,'[\"evidence-005\",\"evidence-024\"]','2026-09-02 15:44:07.000000'),('1216563c-c4b1-4fa0-b4a8-34c1f8f5a06f','f197fa76-4527-44b6-8af4-595a5bae2332',3,'Tổng kết 90 ngày và lập kế hoạch kỳ tiếp theo (Mốc 90 ngày)','Tự đánh giá theo các chỉ số tiến bộ, viết 3 bài học kinh nghiệm và đặt mục tiêu rèn luyện cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:34:53.000000'),('12621149-0665-4c17-ba33-3a5965010b9c','b3597d75-1bde-47ca-878d-831172016ff7',1,'Thiết kế hệ thống thành phần giao diện (Design System mini)','Xây dựng bảng màu, bộ kiểu chữ và các nút bấm cơ bản chuẩn hóa theo tỉ lệ hiển thị trên màn hình ứng dụng di động.',90,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-014\"]','2026-08-30 06:57:48.000000'),('1294685b-8982-4125-80e2-27d98bcc4372','4794a5a0-1bb0-4a7f-901b-660a955c2d93',2,'Chuẩn hóa môi trường làm việc và quản lý mã nguồn Git (Mốc 14 ngày)','Thực hiện cấu hình môi trường phát triển (IDE, linter, Git branching) và đẩy ít nhất 3 bài tập lập trình có cấu trúc commit chuẩn lên kho lưu trữ cá nhân.',90,'self_task',NULL,NULL,'[\"evidence-005\",\"evidence-008\"]','2026-09-04 15:03:37.000000'),('1313d8ea-ee65-5328-905f-a296933ed888','a4049fe8-f128-5ae8-ac64-311db2d2fd42',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"b727f954-c3ae-5ff4-81fc-a58424fe319c\"]','2026-08-25 19:10:00.000000'),('1318a580-f54b-4db8-a0ff-47e262e9aed2','5ea93051-aac9-4cb5-ba36-f43c59f63328',2,'Lập kế hoạch tự học và rèn luyện tư duy thực hành','Xây dựng thời gian biểu cân đối giữa các môn chính khóa và thời gian tự nghiên cứu dự án nhỏ tại nhà.',60,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-28 02:38:47.000000'),('1320e566-f61f-406e-af7f-b3fba2ec2de6','8b6154bd-6c05-42ac-9919-5e05acbb1f8f',2,'Đăng ký tham gia sân chơi Product Sprint','Ghi danh tham gia hoạt động Product Sprint để cọ xát kỹ năng phát triển sản phẩm theo chu trình sprint và nhận góp ý chuyên sâu. Tiêu chí hoàn thành là hoàn tất thủ tục đăng ký trên cổng hoạt động.',45,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-031\"]','2026-08-30 06:51:26.000000'),('13356cb0-a0fd-51ad-954f-daba8afa12b3','00eeab3f-6b43-5c95-82eb-e4db1aed3acb',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Phân tích dữ liệu và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"8c169adf-2353-58f0-8b77-21719f7ce057\"]','2026-08-25 18:21:00.000000'),('13c6f97d-a16a-4b61-a168-6d4a087ad423','664a65f9-c2a7-4fff-9ef8-d76ba8e02ed2',3,'Hoàn thiện bản đồ định hướng cá nhân (Mốc ngày 30)','Tổng hợp kết quả học tập kỳ trước cùng bảng so sánh ngành nghề để viết bản tóm tắt mục tiêu điểm số và các cột mốc ôn luyện quan trọng trong 90 ngày tới.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-04 14:38:51.000000'),('13ef5c4d-c89c-4501-853d-c62c5b7030e8','6562ee9c-ff9f-435c-a1b9-8437a6855dee',2,'Vẽ sơ đồ luồng người dùng (User Flow) và phác thảo Wireframe giấy','Vẽ chi tiết luồng điều hướng 5 màn hình chính cho ứng dụng học tập và phác thảo bố cục giao diện trực quan trên giấy hoặc công cụ vẽ.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-08-30 06:57:48.000000'),('146be2c1-1177-4822-b90a-a2839db3f85e','86895e14-c7fc-4ed8-8042-12f9c1f60fc2',1,'Đăng ký tham gia Product Sprint xây dựng sản phẩm','Tham gia hoạt động Product Sprint tại Product Lab để cùng đội nhóm lên ý tưởng sản phẩm số.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-020\"]','2026-09-05 03:46:02.000000'),('14db9b42-5630-4af3-8e4a-e00d634a7df7','953ac3ad-b090-4610-8f9b-78ffc14300e8',2,'Xây dựng bảng kế hoạch phân bổ thời gian lớp 12','Thiết lập lịch trình học tập cân bằng giữa các môn thi tốt nghiệp và thời gian tự nghiên cứu định hướng nghề nghiệp.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:51:04.000000'),('155a97d3-7af9-4443-bdb1-995233234e90','5dbd4c3b-5abc-4d23-aeed-e04282ba54c9',2,'Xây dựng hồ sơ sản phẩm học tập cá nhân','Tổng hợp các sản phẩm, sơ đồ nghiên cứu và bài tập lớn tiêu biểu trong học kỳ vào một trang lưu trữ trực tuyến.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:15:08.000000'),('15cf8aae-d3dc-52a8-9802-b2dcdf9ca8bb','a69872f4-8f11-5831-99d5-8db3ddfb7808',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"2a44b91b-8bd6-5be1-a1ee-9cc0deec342c\"]','2026-08-25 18:42:00.000000'),('1629be77-3912-4719-8bf1-38f2b8a0e202','eabdb9ad-4f30-44bc-aaf5-e068038392d2',3,'Tổng hợp hồ sơ năng lực kỹ thuật và video demo sản phẩm','Cập nhật CV chuẩn sinh viên ngành phần mềm, đính kèm link GitHub, demo trực tuyến và quay video thuyết minh sản phẩm 3 phút (Mốc 90 ngày).',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-012\",\"evidence-022\",\"evidence-024\"]','2026-09-05 05:50:04.000000'),('163eb865-2e6c-5098-be9f-b6ffc214895f','7558473a-3bdb-5bf9-aab9-92bfab325f8a',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Quản trị dịch vụ và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"90c5ee93-441c-583d-bd55-6407459bde29\"]','2026-08-25 19:10:00.000000'),('1685539c-5074-4297-844a-545a353d8eda','12fe5a17-d2b7-4345-91c7-c66ce886329b',2,'Tổ chức buổi chia sẻ kỹ thuật và phản biện cùng bạn bè (Mốc 85 ngày)','Chuẩn bị bài thuyết trình 15 phút về giải pháp công nghệ đã xây dựng, điều phối phiên hỏi đáp và ghi nhận góp ý phản biện từ các thành viên.',60,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-015\",\"evidence-029\"]','2026-08-31 08:22:34.000000'),('16aa2ae9-8a0d-440e-a87d-edd319bad2ed','605c3b41-f3ff-4d33-879b-e50158b99991',1,'Tổng hợp tài liệu dự án và số liệu đo lường trải nghiệm','Viết báo cáo tóm tắt giải bài toán thiết kế, phân tích các chỉ số cải thiện luồng sử dụng và kết quả kiểm thử giao diện.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-006\",\"evidence-018\"]','2026-08-31 04:21:44.000000'),('16c38d86-973a-4bb9-a31e-3d1a0db770a8','d66cb80f-725a-4d6a-884a-43f733cf108b',4,'Đúc kết nhật ký học tập tháng thứ nhất','Viết báo cáo tự phản hồi dài 1 trang về những kiến thức kỹ thuật đã tích lũy và điều chỉnh mục tiêu cho chặng thực hành tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-013\"]','2026-09-05 02:49:36.000000'),('16db36c1-309a-4267-9af1-22d312d05a33','2ffb28d4-2d61-493f-bbaa-32df1887cdef',3,'Tổng kết dự án môn học và thu nhận ý kiến phản hồi (Mốc ngày 60)','Hoàn thiện bài thuyết trình hoặc sản phẩm mô phỏng môn học, trình bày trước nhóm và thu thập phiếu nhận xét về khả năng dẫn dắt cũng như tính mạch lạc của nội dung.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-09-04 14:38:51.000000'),('171e0dbb-cf66-4f45-a267-620060f5ffd8','5db13e78-18a0-44a5-bd6e-5db3bc88c29d',1,'Thiết lập kế hoạch học tập và bảng mục tiêu kỹ năng 30 ngày','Lập bảng biểu phân bổ thời gian tự học 45 phút/ngày, xác định 3 kỹ năng công nghệ cần củng cố và lưu trữ vào sổ tay học tập.',45,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-026\"]','2026-08-29 06:55:48.000000'),('1753b1dd-66c6-47fd-8637-b00a26e32dd7','41be4372-cfae-483a-8f17-29186718e7d0',1,'Tổng hợp và đóng gói hồ sơ dự án ứng dụng','Chuẩn hóa toàn bộ tài liệu mô tả, sơ đồ luồng dữ liệu và thiết kế giao diện thành một báo cáo dự án hoàn chỉnh.',180,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-004\"]','2026-08-26 03:35:52.000000'),('183d41dd-08eb-46a3-a571-53f9bbf842e4','b62d2179-ef23-426d-8d99-6df2eddbf493',1,'Tổng hợp hồ sơ trải nghiệm và thành tích học tập','Hệ thống hóa các sản phẩm học tập, bài tập nghiên cứu và kỹ năng đã rèn luyện trong năm học thành hồ sơ năng lực.',120,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-27 09:46:18.000000'),('1849b227-6d80-4243-aa57-932d147a8f25','a2502720-8ba6-42c2-8892-e53acf0b12f2',3,'Nhận đánh giá cuối kỳ','Xin nhận xét có cấu trúc và chọn mục tiêu tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 03:26:09.000000'),('189a8709-8196-47cb-816e-d55f46061be2','460cc8a6-9bb5-4089-9a18-b6424883b704',2,'Phát thảo mô hình giải pháp dạng trực quan (Mốc 50 ngày)','Sử dụng công cụ thiết kế cơ bản để vẽ wireframe hoặc sơ đồ quy trình giải quyết vấn đề đã khảo sát.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:20:33.000000'),('18b4d7fc-7954-4ebd-9721-1689cdb4ac26','99c36e53-3fc3-4e64-b086-7d08834836a8',2,'Phác thảo sơ đồ cấu trúc thông tin cho ý tưởng dự án cá nhân (Mốc 14 ngày)','Sử dụng công cụ sơ đồ tư duy để vẽ cấu trúc luồng người dùng và xác định các chức năng chính của sản phẩm học tập dự kiến triển khai.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-09-02 07:52:47.000000'),('18ba0303-c68c-4978-a096-cc2b4d00be7c','d4b808e3-3588-4171-b253-95ab353918e0',1,'Tổng hợp chân dung người dùng và khảo sát thực tế (Mốc 7 ngày)','Lập biểu mẫu khảo sát ngắn từ 5-7 câu hỏi và phỏng vấn 3 bạn học để thu thập nhu cầu sử dụng sàn số học đường, ghi nhận kết quả vào tài liệu tổng quan.',60,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\",\"evidence-015\"]','2026-08-30 17:02:18.000000'),('18dc16e3-682b-5260-be8a-0eae7b66ab5f','d8983f7c-e675-5420-8f55-ff354743b56c',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Kỹ sư an toàn thông tin.',75,'self_task',NULL,NULL,'[\"643bf908-b554-5abd-847c-4d323e93c99c\"]','2026-08-25 18:35:00.000000'),('18fdfb3d-03d7-4d16-9e36-8c450b7b57ab','2754996d-6ebf-4d60-a666-68532bfe1791',2,'Tham gia hoạt động thử nghiệm công nghệ tại Innovation Lab','Đăng ký và tham gia sự kiện AI Hacklab để tìm hiểu cách tích hợp công nghệ mới vào giải quyết bài toán người dùng.',180,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-037\"]','2026-09-03 14:02:44.000000'),('1958ec2b-ed5f-4b51-b3f8-2bdf74ef809b','86895e14-c7fc-4ed8-8042-12f9c1f60fc2',2,'Phân tích yêu cầu và vẽ sơ đồ luồng người dùng','Lập sơ đồ luồng chức năng cho ứng dụng nhóm nhằm tối ưu hóa trải nghiệm tương tác.',75,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\"]','2026-09-05 03:46:02.000000'),('195944d9-32ff-4653-9238-79c71ee938fc','5d6dc234-faa0-43ec-a8f3-b9a020140d86',2,'Giải quyết chuỗi 15 bài toán cấu trúc dữ liệu và giải thuật cơ bản','Luyện tập các bài toán về mảng, chuỗi ký tự, thuật toán tìm kiếm và sắp xếp trên nền tảng trực tuyến; ghi chép lại cách tối ưu độ phức tạp thuật toán (hoàn thành trước mốc 14 ngày).',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-05 09:58:29.000000'),('19d361b0-16ad-50f3-a048-d6f168d1971c','0cd7474b-0a25-5568-91fe-5def493e832e',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Quản trị dịch vụ và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"700cc2f3-0e83-5ae0-a59e-91cdd50cea83\"]','2026-08-25 19:10:00.000000'),('19e02fc3-435b-46c7-9420-0b4ecbd25ab2','2754996d-6ebf-4d60-a666-68532bfe1791',4,'Tổng kết mốc 30 ngày và đối soát tiến độ nhóm','Họp trao đổi cùng nhóm dự án để thống nhất quy chuẩn thiết kế và tài liệu hóa phản hồi từ các thành viên.',45,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-017\"]','2026-09-03 14:02:44.000000'),('1a4887db-f1a5-4ac7-a554-322e181aba9c','caa938bc-5b48-4fa9-868e-1d1de3083a06',1,'Mốc ngày 70: Chuẩn bị kịch bản thuyết trình và slide trực quan','Soạn thảo kịch bản chia sẻ 10 phút, thiết kế 10-12 slide hình ảnh sinh động làm nổi bật giải pháp và quá trình thực hiện.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-30 07:10:06.000000'),('1b70cc09-6057-428f-885c-deb77895ad9d','45ef38ea-ce8f-4de3-a167-8dcd66cd20ed',4,'Lập báo cáo đánh giá và cải tiến giao diện','Tổng hợp kết quả thử nghiệm thành bảng tóm tắt 1 trang gồm 3 điểm tốt và 3 điểm cần tinh chỉnh cho phiên bản tiếp theo.',60,'self_task',NULL,NULL,'[\"evidence-018\",\"evidence-027\"]','2026-08-31 15:54:21.000000'),('1bef258a-3eda-4aef-a5cd-56cf3eacd7e2','ca952e6f-76f6-4bbe-b11c-9b5157a1251f',3,'Đánh giá tổng kết và lập mục tiêu kỹ năng cho năm học tiếp theo','Thực hiện tự đánh giá mức độ tiến bộ về kỹ năng tổ chức, tư duy logic và đề ra 3 mục tiêu học thuật cho kỳ tiếp theo.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-016\",\"evidence-017\"]','2026-09-05 03:19:52.000000'),('1bf48e19-1d4e-4641-8ad3-ac33b7420f46','82033c1c-644d-470a-ab99-b926bc6fe41e',2,'Thực hiện Buổi Lắng nghe Phản hồi và Thảo luận Mở','Chủ động tổ chức 30 phút trao đổi sau giờ học để lắng nghe đóng góp từ các thành viên trong nhóm và ghi chép lại các điểm cần tối ưu hóa.',45,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-31 15:26:24.000000'),('1c1fb074-6bab-4983-a4fb-98f94dba21b3','e5764c15-5829-4e07-9280-98c2ccf457a0',1,'Phác thảo đề cương sản phẩm sáng tạo','Chọn một đề tài liên quan đến công nghệ đời sống, phác thảo mục tiêu, cấu trúc và các bước triển khai chi tiết.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 02:38:47.000000'),('1c4c4c9e-27c5-5023-94aa-e30d5b789fc9','bb6a448f-787b-5b06-b94a-94683bc00d60',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Phân tích dữ liệu và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"ac6912c8-4e65-5e98-b67d-e3f76f3ff3ed\"]','2026-08-25 18:21:00.000000'),('1ca03f7c-7b76-5e90-b631-c169955c4ab3','d8983f7c-e675-5420-8f55-ff354743b56c',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"4501e0b0-acc0-529a-ab14-e82d54ee3550\"]','2026-08-25 18:35:00.000000'),('1d8c812f-cd6d-4c74-bc82-48ec28078c29','1947498b-9d81-4bc7-ab62-2866fdb5e519',1,'Thiết kế kiến trúc và mô hình dữ liệu cho ứng dụng thực hành (Mốc 40 ngày)','Bắt đầu bằng việc vẽ sơ đồ thực thể liên kết (ERD) và sơ đồ luồng dữ liệu cho một ứng dụng mini; xuất ra tài liệu định dạng Markdown hoàn chỉnh.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\"]','2026-09-04 15:03:37.000000'),('1d91951a-8f61-4f03-b129-6e56afa165ca','8afe7a57-4e83-4ecf-a593-b814f0eec2c3',1,'Khảo sát và lập danh mục ngành học triển vọng','Thu thập thông tin về chương trình đào tạo, chuẩn đầu ra và cơ hội thực tập của 3 ngành học liên quan đến phân tích dữ liệu và quản trị thông tin.',120,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-27 09:46:18.000000'),('1dd41be9-a0de-5ad3-b13e-fdd23aeca6d5','c9d27261-64f8-53df-a65b-171aa5928726',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"cdeac990-f872-5d28-921d-6904910ed8ed\"]','2026-08-25 18:14:00.000000'),('1e60b0aa-cda3-451a-a381-c4619339485d','605c3b41-f3ff-4d33-879b-e50158b99991',3,'Thuyết trình báo cáo dự án và tiếp nhận nhận xét chuyên môn (Mốc 90 ngày)','Trình bày bài case study trước nhóm bạn học hoặc cố vấn bộ môn để nhận phản hồi đánh giá hoàn thiện hồ sơ dự án số.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-015\",\"evidence-016\",\"evidence-043\"]','2026-08-31 04:21:44.000000'),('1e87d26f-01ba-4657-91bd-7d43db7b6ce5','cf9ad7f5-62ae-4468-902c-757beeceacf5',1,'Đăng ký tham gia sự kiện AI Hacklab tại Innovation Lab','Nộp đơn đăng ký tham dự chương trình AI Hacklab để quan sát các ý tưởng ứng dụng trí tuệ nhân tạo từ cộng đồng sinh viên; ghi chú lại 3 mô hình triển khai ấn tượng.',60,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-018\"]','2026-09-05 08:20:23.000000'),('1ed495bc-a10a-4a70-ab58-37403555391c','8203f8c5-9654-440b-aa8d-838fc366bf25',1,'Đóng gói tài liệu kỹ thuật và thiết kế dự án (Mốc 70 ngày)','Soạn thảo tài liệu tóm tắt dự án gồm: bài toán, giải pháp thiết kế, kiến trúc luồng dữ liệu và kết quả đo lường thực nghiệm.',80,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-009\",\"evidence-027\"]','2026-08-30 17:02:18.000000'),('20735473-dcbd-4b8b-b769-1c722310a931','4794a5a0-1bb0-4a7f-901b-660a955c2d93',1,'Rà soát kỹ năng và lập danh mục chủ đề học tập cá nhân (Mốc 7 ngày)','Bắt đầu bằng việc đối chiếu kiến thức môn học hiện tại với yêu cầu kỹ thuật nền tảng; liệt kê 5 chủ đề lập trình trọng tâm cần củng cố trong sổ tay học tập.',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-04 15:03:37.000000'),('207959a3-2ed5-4cac-b779-f2ed9a66ff64','d4b808e3-3588-4171-b253-95ab353918e0',3,'Thiết kế luồng trải nghiệm người dùng và sơ đồ khung dây Wireframe (Mốc 30 ngày)','Sử dụng công cụ thiết kế để tạo sơ đồ luồng thông tin gồm 4 màn hình chính (Trang chủ, Chi tiết, Giỏ hàng, Báo cáo) đáp ứng tiêu chuẩn trải nghiệm trực quan.',90,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-013\",\"evidence-014\"]','2026-08-30 17:02:18.000000'),('208c9b53-c810-4da7-beda-d77f3474732c','50a05c54-d738-474b-a949-d4306d4212a8',2,'Phác thảo sơ đồ tính năng và luồng người dùng cho bài tập nhỏ','Vẽ sơ đồ luồng thao tác người dùng trên giấy hoặc công cụ trực quan cho một ứng dụng hỗ trợ sinh viên tại trường.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:54:06.000000'),('20ae0a0d-1241-46a9-aaa8-5ed6274a881b','0acbe34f-147d-450a-a19c-dca06e910791',2,'Tạo phương án thử nghiệm','Phác thảo một giải pháp nhỏ có thể hoàn thành trong tuần.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-25 14:17:14.000000'),('2156926a-4138-441a-9194-115cf72f67bb','460cc8a6-9bb5-4089-9a18-b6424883b704',1,'Khảo sát thực trạng và định hình bài toán nhóm (Mốc 40 ngày)','Cùng nhóm học tập thảo luận, phỏng vấn nhanh 5 sinh viên khác để xác định một vấn đề thực tế trong môi trường học đường cần cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:20:33.000000'),('21bdfc7d-8197-41ac-bd97-33c61bcc4146','414a28d3-ac68-49c2-a015-015beaac2c76',2,'Tạo phương án thử nghiệm','Phác thảo một giải pháp nhỏ có thể hoàn thành trong tuần.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 03:26:09.000000'),('21f0b70e-e639-43c8-93af-4217ee34e36d','0528be3b-2412-436f-a8ae-4981d9c68ed4',1,'Soạn thảo bài viết Case Study phân tích hành trình dự án từ đầu đến cuối','Viết bài tổng kết khoảng 800-1000 từ trình bày rõ: Vấn đề nghiên cứu, quy trình giải quyết, hình ảnh minh chứng và bài học kinh nghiệm.',105,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:59:22.000000'),('2222d70c-c084-50c1-bfc5-0b294e46b1bf','b21064de-557b-5d6d-91ba-c268dccb415b',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"ac6912c8-4e65-5e98-b67d-e3f76f3ff3ed\"]','2026-08-25 18:21:00.000000'),('227cdd60-5842-4a06-9c6e-6145dfac2b6c','c5ac9ad1-1356-44d7-b5e7-27fe90b70e2d',3,'Hoàn thiện hồ sơ đồ án kỹ thuật và video demo sản phẩm','Soạn thảo bài giới thiệu dự án gồm bối cảnh, giải pháp công nghệ, kiến trúc hệ thống và quay 1 video ngắn 3 phút trình bày tính năng nổi bật của sản phẩm.',105,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-012\"]','2026-09-05 05:46:35.000000'),('22ca1ef4-e3fd-4d03-b975-27e2ea42a187','699286a4-e746-445e-a882-57cb48a429b7',3,'Hoàn thiện bản đề xuất giải pháp sản phẩm đầu tay (Mốc 30 ngày)','Viết tài liệu Product Brief ngắn gọn (khoảng 2-3 trang) giải quyết một vấn đề thực tế trong khuôn viên trường đại học.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-018\"]','2026-08-29 06:44:00.000000'),('232ce029-a5cf-4d38-8dd4-088563f3fb0b','2502f190-cee9-4228-af89-f0db77efc252',1,'Xây dựng đề cương dự án thực hành','Soạn thảo tài liệu mô tả mục tiêu, phạm vi và các mốc thời gian của dự án cá nhân.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-24 15:21:04.000000'),('24bbf4f6-7044-4af7-9bff-c5ea0b119e1b','584a8151-2de8-46ad-bb69-866bcc7c3eea',2,'Xây dựng slide và thực hành thuyết trình demo sản phẩm (Mốc 80 ngày)','Soạn bản trình chiếu 10 trang tóm tắt kiến trúc, điểm nổi bật và bài học kinh nghiệm; thực hành trình bày thử trong 10 phút trước gương hoặc nhóm bạn.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-04 15:03:37.000000'),('259d207d-4a76-570a-a0b3-90c8c27f784c','7999cee7-84c2-5883-b9ab-f9594ca7ab97',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"c6c194fc-96f3-5783-8c4a-b8a927485a3e\"]','2026-08-25 18:35:00.000000'),('26a8553a-f13e-4861-b6b3-968870b6960e','1757e5a6-980e-4021-9f0e-b30398aed17f',2,'Thiết kế kế hoạch triển khai và phân bổ tiến độ chi tiết','Thiết lập danh sách các bước thực hiện, phân công trách nhiệm giả định và xây dựng cột mốc theo dõi cụ thể.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 10:39:35.000000'),('274000a0-3904-4cc3-bba9-11e0523d478a','c107ac33-6dcf-4833-b0c3-a61690887d9a',1,'Xây dựng thời khóa biểu và bản mục tiêu cá nhân kỳ học (Mốc 7 ngày)','Lập bảng kế hoạch chi tiết phân bổ thời gian học trên lớp, tự học và nghỉ ngơi; xác định 3 mục tiêu cụ thể cần đạt trong 30 ngày đầu tiên.',60,'self_task',NULL,NULL,'[\"evidence-011\"]','2026-09-05 03:54:06.000000'),('29223b12-6858-4f97-9118-9350296b886b','6b38b27e-c73c-4c3e-85e2-2a72f6427923',1,'Xây dựng bộ giao diện tương tác có thể click hoàn chỉnh (Mốc 45 ngày)','Thiết kế tối thiểu 5 màn hình chính của giải pháp số trên phần mềm đồ họa với hệ thống màu sắc và bố cục nhất quán.',120,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-018\"]','2026-08-31 15:59:36.000000'),('295a7dd1-420c-4b02-963d-9da2383ecb1b','19d56d0d-7d77-4c1a-8916-2fd379860ff6',2,'Đánh giá mức độ hoàn thành mục tiêu','Đối chiếu kết quả thực tế với kế hoạch ban đầu, phân tích nguyên nhân thành công và điểm cần cải thiện.',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-24 15:21:04.000000'),('29a9f6ff-e4dc-4fc7-96b0-4417667d961e','a6c50441-9d9f-4757-a7a9-91af98b27b02',1,'Tối ưu hóa hiệu năng và rà soát bảo mật mã nguồn','Thực hiện tái cấu trúc các đoạn mã phức tạp, kiểm tra lỗi logic tiềm ẩn và tinh chỉnh tốc độ xử lý của ứng dụng để đạt chuẩn hoạt động mượt mà.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-012\"]','2026-09-04 15:00:27.000000'),('29c3d007-6ba1-5057-8d9f-9a11cced4890','edfca528-8316-5713-bb88-4c3af41a5371',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"1e417d13-8dee-5201-bce3-9dec171db9cb\"]','2026-08-25 18:49:00.000000'),('2a539afc-e05f-4cef-927b-61b5edefc3ce','414a28d3-ac68-49c2-a015-015beaac2c76',3,'Thu thập phản hồi','Xin phản hồi từ ít nhất hai người và ghi lại điều học được.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 03:26:09.000000'),('2a5e5d4f-1a2d-4e4b-9ec7-e3e9e9f82085','f9b3d0ce-b031-4d26-b8f3-6f13ba9eb20f',3,'Cải tiến mẫu thiết kế dựa trên góp ý và đóng gói phiên bản thử nghiệm (Mốc 60 ngày)','Rà soát lại toàn bộ phản hồi, chỉnh sửa các liên kết trong bản mẫu và xuất liên kết chia sẻ trực tuyến kèm tài liệu ghi chú cải tiến.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-30 07:59:22.000000'),('2a86a891-9db6-4675-b3cd-cfaa50f48ab6','690c02ca-beb6-4eb4-9ff1-ec81189c47f6',3,'Soạn thảo hồ sơ năng lực và video thuyết trình demo sản phẩm (Mốc 90 ngày)','Cập nhật hồ sơ năng lực cá nhân với đường dẫn kho mã nguồn, demo trực tuyến và quay video ngắn 3 phút giải thích giải pháp kỹ thuật đã làm.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-012\",\"evidence-024\"]','2026-09-05 05:53:02.000000'),('2aa2cd3a-35d1-4dc0-a7fa-09f4c00156cd','08d47b5b-cae9-4fe5-ab2e-6aaa706e73ef',1,'Triển khai thử nghiệm và thu thập phản hồi','Thực hiện giải pháp trong phạm vi nhỏ, ghi nhận ý kiến đóng góp từ người xung quanh để điều chỉnh.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-24 15:40:29.000000'),('2afed0df-0583-4c79-8515-d3b3e273c635','6b38b27e-c73c-4c3e-85e2-2a72f6427923',3,'Tổ chức phiên phản biện chéo và ghi nhận góp ý cải tiến (Mốc 60 ngày)','Thu thập ý kiến đóng góp từ 3 người bạn học hoặc giảng viên hướng dẫn về nguyên mẫu đã hoàn thành, tổng hợp thành danh sách cải tiến.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-015\",\"evidence-017\"]','2026-08-31 15:59:36.000000'),('2b4858ba-31b0-4a46-85b8-de524f4a4156','a632f50e-8013-4a9b-8e59-9b7215b9ce57',2,'Biên soạn tài liệu Case Study chi tiết cho đồ án (Mốc 85 ngày)','Trình bày hành trình giải quyết vấn đề từ bối cảnh, giải pháp thiết kế, mã nguồn hoặc kiến trúc hệ thống thành một bài viết hoàn chỉnh.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-013\"]','2026-08-31 15:59:36.000000'),('2b63f81e-662d-4ff1-8608-6683b31e0716','e4f72bc1-3839-48dd-b86c-1fddadfd0396',2,'Điều phối buổi học nhóm giải đề chuyên sâu','Lập dàn ý nội dung, phân công nhiệm vụ và dẫn dắt buổi thảo luận giải quyết các bài tập tổng hợp cùng các bạn cùng lớp.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 09:09:29.000000'),('2b6523dc-b369-419b-b391-b1780c8ffbb5','caa938bc-5b48-4fa9-868e-1d1de3083a06',2,'Mốc ngày 80: Thực hành thuyết trình thử nghiệm và ghi nhận đánh giá','Trình bày thử trước nhóm bạn học hoặc ghi hình tự đánh giá, điều chỉnh tốc độ nói và ngôn ngữ cơ thể theo tiêu chí rõ ràng, thu hút.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:10:06.000000'),('2bbfcdaa-3e77-4c69-a6c8-416201331a78','5eed8cfb-5532-4c18-bce7-5207bf99be5f',2,'Chủ động điều phối phiên thảo luận nhóm','Thực hành đặt câu hỏi mở và ghi nhận đóng góp của từng thành viên trong buổi họp nhóm.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 06:08:16.000000'),('2bd35a77-015a-5f1b-9fd3-7af85fd2a4ef','2955d13d-14e2-5300-b4fb-5b708e5499b3',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"d37b7333-f866-5edc-a6ce-52d5244f5d2f\"]','2026-08-25 18:28:00.000000'),('2c95798a-967b-4708-a14c-d19bc10d63ba','5d15a244-f1df-4baa-a3d0-4f3222c5a8a4',2,'Biên soạn hồ sơ năng lực dự án cá nhân (Digital Portfolio)','Tổng hợp các minh chứng đồ án, kết quả học tập và hình ảnh sản phẩm đã hoàn thành thành bộ hồ sơ trực tuyến hoàn chỉnh.',120,'self_task',NULL,NULL,'[\"evidence-020\",\"evidence-025\",\"evidence-029\"]','2026-08-29 06:55:48.000000'),('2cd61a54-e6ee-4da8-bb45-9c6cc34abdc0','2c4c6679-2259-4015-8ce7-38e8937d7023',1,'Khởi tạo tài liệu phân công nhiệm vụ nhóm (Mốc 40 ngày)','Xây dựng biểu đồ phân rã công việc (WBS) cho bài tập lớn của nhóm, xác định rõ người phụ trách, thời hạn và tiêu chí hoàn thành.',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-03 14:30:25.000000'),('2d5e8ea9-2458-4fc6-9a4e-671e7247f8a4','664a65f9-c2a7-4fff-9ef8-d76ba8e02ed2',1,'Lập danh mục hồ sơ ngành học mục tiêu (Mốc ngày 7)','Thu thập thông tin về 3 nhóm ngành thuộc lĩnh vực kỹ thuật, công nghệ và kiến trúc từ đề án tuyển sinh chính thức; ghi chú điểm chuẩn, tổ hợp môn và cơ hội nghề nghiệp vào bảng so sánh.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-04 14:38:51.000000'),('2d7b6263-8c41-498a-b28c-c7c8d300982e','47474713-b413-4ebe-bb11-7be0181a8e15',3,'Đánh giá tiến độ và tinh chỉnh thói quen học tập (Mốc 30 ngày)','Viết bài tự phản tư ngắn gọn 300 từ đánh giá hiệu quả học tập tháng đầu tiên, chỉ ra 2 điểm nghẽn và giải pháp tối ưu thời gian.',45,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-09-03 14:30:25.000000'),('2da4d69a-23c1-44f3-a12f-7cd6a780cc18','792554d3-3b4e-4aea-9c52-45bae3b401df',1,'Mốc 68 ngày: Tối ưu giao diện và kết nối hoàn chỉnh hệ thống','Tích hợp giao diện người dùng với các dịch vụ xử lý dữ liệu ngầm, xử lý các trường hợp ngoại lệ và thông báo phản hồi người dùng.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-022\"]','2026-09-02 15:44:07.000000'),('2eb3dba9-084a-47c2-ba25-647933904aa5','7365eb8a-ae89-4e9a-8676-76aa739fb494',2,'Tham gia trải nghiệm Python & Robot Lab tại trường (Mốc 14 ngày)','Đăng ký và tham dự buổi sinh hoạt tại phòng STEM B305 để làm quen với các khái niệm lập trình điều khiển cơ bản.',90,'register_activity','activity','31000000-0000-4000-8000-000000000005','[\"evidence-009\",\"evidence-017\"]','2026-09-05 07:49:00.000000'),('2f17685f-04d6-4123-96b1-3d5a6cd44062','45ef38ea-ce8f-4de3-a167-8dcd66cd20ed',1,'Xây dựng nguyên mẫu giao diện chi tiết cho sản phẩm','Thiết kế bộ màn hình hoàn chỉnh có tích hợp hiệu ứng chuyển động cơ bản để người dùng thử nghiệm thao tác trực tiếp.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\"]','2026-08-31 15:54:21.000000'),('2f434640-0afd-545c-9d08-bdcf80ce120d','65cf0c6c-b41b-5cd2-abac-defa2917091a',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Điều phối dự án kinh doanh số và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"108349f9-4817-50e6-9cc9-cc516f64061c\"]','2026-08-25 18:42:00.000000'),('2f787152-f225-4596-95d8-73c52dc8cff7','d9419ec7-d013-4f82-8749-16a5481ecac6',1,'Thiết lập khung quản lý mục tiêu cá nhân','Lập danh sách các mục tiêu ngắn hạn theo từng tuần dựa trên thế mạnh tổ chức và lập kế hoạch.',60,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-24 15:21:04.000000'),('306307dc-22a6-4375-ba65-face23d9a156','52b33b60-0bac-43bc-9ae4-05cc9c1d78e6',3,'Thiết kế bộ trình chiếu báo cáo dự án (Slide Deck)','Tổng hợp các nội dung then chốt vào bộ slide thuyết trình khoảng 10-12 trang với cấu trúc mạch lạc, hình ảnh rõ ràng và số liệu thuyết phục. Đầu ra là tệp trình chiếu hoàn thiện sẵn sàng báo cáo.',75,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-08-30 06:51:26.000000'),('31107278-e2ea-4e25-8799-c17baa763b0f','4584f55b-f360-4602-88f2-81d5dfafdd32',2,'Phân tích sai sót và tối ưu chiến thuật làm bài','Ghi nhận các lỗi thường gặp trong quá trình làm bài kiểm tra, phân loại nguyên nhân và xây dựng bảng giải pháp khắc phục.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-27 09:09:29.000000'),('3258d0b0-3f91-4b3e-abb3-3a09d1f2fc4d','02fc279c-4625-41bd-ba0f-db58ade237af',1,'Khảo sát bài toán thực tế trong khuôn viên học tập (Mốc 7 ngày)','Thực hiện phỏng vấn ngắn 5 sinh viên cùng khóa về những khó khăn trong việc quản lý thời gian hoặc tài liệu học tập, ghi chép lại các điểm nghẽn chính vào tài liệu tổng hợp.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:54:44.000000'),('3282d9de-09f1-49dd-93b2-cfe918e9c770','36ed863b-ef2f-49ff-a236-18ef35802458',3,'Thiết kế bản phác thảo giải pháp và nhận phản hồi','Xây dựng bản vẽ hoặc mô hình minh họa giải pháp và gửi lấy ý kiến đóng góp từ ít nhất 3 sinh viên khóa trên để hoàn thiện.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-30 07:17:58.000000'),('32acf6c9-bb41-48c7-9ca7-2396b01f826c','2e962488-04a3-47a7-9667-37a1ebb8a6b3',3,'Xây dựng nguyên mẫu tương tác hoàn chỉnh cho bài toán học tập','Thiết kế bộ giao diện độ chi tiết cao (Hi-fi prototype) liên kết các màn hình chính và tiến hành kiểm thử tương tác với các thành viên trong nhóm học tập.',120,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\",\"evidence-017\"]','2026-08-29 06:39:46.000000'),('32e9c3a7-ed18-50f3-8cda-0e4de92b65e2','e8deed02-a869-565a-afdc-d8df35b44c51',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"4989f77d-56b8-5a4f-843e-1dc05ffa8317\"]','2026-08-25 18:56:00.000000'),('33d36eb9-391b-491e-9582-53a43064c575','264d84b9-3d5f-49fb-97c7-6f17dee3acb1',1,'Lập bảng kế hoạch tự học thuật toán và phân tích logic (Mốc 7 ngày)','Bắt đầu bằng việc phân bổ 60 phút để lập danh sách 5 chủ đề thuật toán và kỹ thuật xử lý dữ liệu trọng tâm cần rèn luyện trong tháng, ghi rõ mục tiêu từng tuần.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-017\",\"evidence-018\"]','2026-08-31 08:22:34.000000'),('33ff7152-f212-4b03-8cef-8c46a50a43bc','d17d7a2a-d8e7-45a6-85bc-b6ca55eff2c9',1,'Thiết lập bảng kế hoạch học tập và quản lý thời gian 30 ngày (Mốc 7 ngày)','Lập thời khóa biểu chi tiết kết hợp lịch học và tự học trên công cụ số, phân bổ ít nhất 6 khung giờ học tập cố định trong tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:20:33.000000'),('342cf4d4-d8f6-4f98-a359-5fde21d5db0c','5eed8cfb-5532-4c18-bce7-5207bf99be5f',3,'Kiểm thử và tối ưu giải pháp thực hành','Rà soát lỗi và cải thiện hiệu quả của bài tập thực hành theo các tiêu chuẩn kỹ thuật.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 06:08:16.000000'),('343fa8f8-15f0-4bb6-9bd6-c96499369401','1757e5a6-980e-4021-9f0e-b30398aed17f',3,'Thực hành thu thập phản hồi và điều chỉnh phương án','Trình bày giải pháp thử nghiệm với bạn bè hoặc giáo viên, ghi nhận ý kiến đóng góp và cải tiến kế hoạch ban đầu.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-27 10:39:35.000000'),('3447b914-e88c-4dcf-9f2c-adbfecbbd00a','a85b6430-56f8-4b81-ab82-69f2cd32ff76',3,'Điều phối buổi phản biện nội bộ và hoàn thiện báo cáo (Mốc 60 ngày)','Chủ trì buổi họp nhóm thử nghiệm thuyết trình, ghi nhận đóng góp và hiệu chỉnh tài liệu báo cáo dự án lần cuối.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:34:53.000000'),('34d28c9a-f731-4028-80f3-90628a43277a','018f20f9-8264-4763-90c9-a7cd6cd2ca68',1,'Cài đặt và thiết lập môi trường lập trình chuẩn','Cấu hình Visual Studio Code, Git, NodeJS hoặc Python trên máy tính cá nhân; tạo tài khoản GitHub và hoàn tất quy trình đẩy mã nguồn đầu tiên với tài liệu hướng dẫn README chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\",\"evidence-010\"]','2026-09-05 05:46:35.000000'),('350c9392-6b94-4570-a2db-cfbb6ab1f387','b9180876-24be-4bf2-84fe-e4014f0d6547',1,'Tổng hợp minh chứng học tập và sản phẩm dự án','Biên tập các thành tích, sản phẩm sáng tạo và báo cáo kết quả rèn luyện thành một bộ hồ sơ năng lực súc tích.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 10:39:35.000000'),('356a8a5e-6c9a-44a8-bc5f-37afdcbb6f25','d332fa6e-085c-4c8f-8019-383be4e84bcb',1,'Xác định bài toán dự án (Mốc 60 ngày)','Chọn một vấn đề thực tế phù hợp ngành An toàn thông tin và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"643bf908-b554-5abd-847c-4d323e93c99c\"]','2026-09-02 14:19:37.000000'),('3593741e-7386-426e-a263-b4e320e24dce','f96f949b-aa13-4c41-9342-a5d505219893',3,'Hoàn thiện bản đồ kiến thức tổng hợp giai đoạn 1 (Mốc 30 ngày)','Tổng hợp toàn bộ nội dung đã học thành một trang infographic hoặc mindmap chi tiết, tự đánh giá mức độ hiểu bài đạt trên 80%.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:59:48.000000'),('35f8ea2a-bb1a-48fc-8796-98786d254251','f60922d5-3890-4ee7-9154-53a2cd5547fe',2,'Thực hành thiết kế infographic tóm tắt bài học lớp 10','Sử dụng công cụ đồ họa trực tuyến tạo một infographic trực quan hóa kiến thức môn Toán hoặc Tin học trong 60 phút.',60,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-014\"]','2026-09-05 07:49:00.000000'),('361a1698-f3c6-4d97-ba28-74837167e249','8203f8c5-9654-440b-aa8d-838fc366bf25',2,'Tổ chức buổi chia sẻ và lắng nghe đóng góp từ nhóm học tập (Mốc 80 ngày)','Thuyết trình demo sản phẩm trong 10 phút trước nhóm bạn cùng lớp, lắng nghe góp ý và ghi chú các điểm cải thiện kỹ năng phối hợp.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-012\",\"evidence-015\",\"evidence-017\"]','2026-08-30 17:02:18.000000'),('363e93fe-03cf-44c7-9151-a92a7ddf02b7','82033c1c-644d-470a-ab99-b926bc6fe41e',1,'Điều phối Kế hoạch Phân công Nhóm Học tập','Lập bảng kế hoạch chi tiết cho một bài tập nhóm ở lớp, phân chia đầu việc theo thế mạnh từng bạn và đặt lịch kiểm tra tiến độ mỗi tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-31 15:26:24.000000'),('366f8466-e65c-44ff-86e7-af5193075b87','d66cb80f-725a-4d6a-884a-43f733cf108b',3,'Thực hành bài tập lập trình cấu trúc cơ bản','Viết và chạy thử một ứng dụng dòng lệnh nhỏ giải quyết bài toán xử lý dữ liệu sinh viên trong 60 phút, đẩy mã nguồn lên kho lưu trữ cá nhân.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 02:49:36.000000'),('370bcf9c-d921-45a3-8b6f-984caaf7f94e','4acb702b-8f89-49b3-b21c-309e36f51868',3,'Thực hiện thuyết trình thử nghiệm đồ án và tiếp thu phản hồi','Thiết kế bộ slide 10 trang trình bày quá trình phát triển sản phẩm, tiến hành thuyết trình thử trong 10 phút trước nhóm bạn và ghi nhận ý kiến cải thiện (hoàn thành trước mốc 90 ngày).',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\",\"evidence-012\"]','2026-09-05 09:58:29.000000'),('3743583c-1b4a-44b9-9c18-c9e1d2196ebc','cb65ccec-9541-45c8-97a6-0cf68ac7f9ea',3,'Lập báo cáo phân tích dữ liệu tương tác người dùng (Mốc 60 ngày)','Thu thập số liệu thời gian hoàn thành tác vụ từ 5 người thử nghiệm, xử lý số liệu bằng bảng tính và trình bày 3 điểm cần tinh chỉnh.',75,'self_task',NULL,NULL,'[\"evidence-017\",\"evidence-018\",\"evidence-027\"]','2026-08-30 17:02:18.000000'),('37d22f56-d420-45df-a2e4-7221dc4023e6','f197fa76-4527-44b6-8af4-595a5bae2332',1,'Biên tập nội dung hồ sơ học tập cá nhân (Mốc 75 ngày)','Lựa chọn 2 bài tập hoặc sản phẩm tiêu biểu trong kỳ học, viết bài phân tích quá trình thực hiện và kết quả đạt được.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-02 14:34:53.000000'),('3843ac1c-ff96-5afc-a593-f024d6524a0f','b21064de-557b-5d6d-91ba-c268dccb415b',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"9e9b9745-528e-5ab1-bbcd-41c521ae2100\"]','2026-08-25 18:21:00.000000'),('386c325f-dddc-4742-b19a-0fe01f154696','b3597d75-1bde-47ca-878d-831172016ff7',2,'Đăng ký tham gia Product Sprint để cọ xát kỹ năng làm sản phẩm số','Đăng ký sự kiện Product Sprint để phối hợp cùng đồng đội xây dựng sản phẩm mẫu và nhận phản hồi thực tế từ cố vấn.',45,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-031\"]','2026-08-30 06:57:48.000000'),('39148c09-65da-411c-ba08-6f0ec54fd170','b0c394a0-2cff-414c-b336-68d23f1e8d52',3,'Mốc Ngày 90: Hoàn thiện hồ sơ năng lực và thực hành phỏng vấn kỹ thuật','Tổng hợp các dự án, chứng chỉ năng lực vào Portfolio cá nhân, đối chiếu với yêu cầu của các vị trí thực tập phần mềm và tự luyện tập trả lời câu hỏi kỹ thuật. Tiêu chí hoàn thành: Bản Portfolio định dạng web/PDF hoàn thiện và danh sách 3 cơ hội thực tập mục tiêu.',90,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-009\",\"evidence-023\"]','2026-09-05 05:33:43.000000'),('39d10590-5ac7-54b2-a89c-bd380629543d','b4708adc-b93c-5e85-af18-eb08b6023450',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Logistics và chuỗi cung ứng và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"1e137bb9-75f5-58be-af2a-d92e9a4639e3\"]','2026-08-25 18:49:00.000000'),('39dae8d2-d434-43ce-b8dc-48cf8e55ea8c','b9180876-24be-4bf2-84fe-e4014f0d6547',2,'Luyện tập kỹ năng trình bày kế hoạch cá nhân','Thực hành diễn đạt mục tiêu học tập và lý do chọn ngành trước gương hoặc người thân nhằm tăng tính tự tin và mạch lạc.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-27 10:39:35.000000'),('39e779d8-7340-4653-a23c-8b9d77a07b04','ef54a41d-8316-460f-8867-b5a134b40248',2,'Phác thảo sơ đồ hành trình người dùng (User Journey Map) cho giải pháp học đường','Vẽ sơ đồ luồng trải nghiệm người dùng trên Miro hoặc Figma thể hiện cách sinh viên tiếp cận các thùng rác thông minh hoặc điểm sạc năng lượng tại trường.',120,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-021\"]','2026-09-05 08:20:23.000000'),('3a838809-e221-48d4-8140-db02cd7b2618','5c9d0a05-bbe4-4f55-b6cd-99d6e235277b',3,'Tổ chức buổi trao đổi đánh giá chéo mã nguồn cùng bạn nhóm','Trình bày mã nguồn và thiết kế mô-đun với ít nhất một người bạn cùng lớp, thu thập nhận xét kỹ thuật và lập danh sách 3 điểm cần tinh chỉnh.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\"]','2026-09-04 15:00:27.000000'),('3b90486c-29bb-41c8-bc98-091a6a49e39a','db099061-603f-420f-94ab-9ef2bff4a708',1,'Thiết lập không gian và lịch biểu cá nhân','Sắp xếp lại góc học tập và lập kế hoạch ôn tập tuần cho các môn trọng tâm lớp 12.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 09:02:35.000000'),('3bd003ae-172b-4308-86c5-cab2ec3034fc','4794a5a0-1bb0-4a7f-901b-660a955c2d93',3,'Giải quyết chuỗi bài toán logic và tối ưu thuật toán (Mốc 30 ngày)','Thực hiện phân tích và giải quyết 5 bài toán thuật toán nền tảng, ghi chú chi tiết độ phức tạp thời gian và không gian cho từng giải pháp.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-007\",\"evidence-010\"]','2026-09-04 15:03:37.000000'),('3c01046d-12e8-516b-b4fa-1b4686b7a27b','4231e2d1-384b-5885-8433-9f91dd68c3e7',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"]','2026-08-25 18:35:00.000000'),('3c4cb84a-6e76-472a-9e1f-4d5e09cdbcae','786df7fd-ab49-43a5-9c4d-9c1c0b71502d',2,'Phác thảo nguyên mẫu thiết kế hoặc đồ họa dự án (Mốc 50 ngày)','Sử dụng công cụ thiết kế cơ bản để phác thảo các khung nhìn trực quan cho đề tài đã chọn của nhóm. Tiêu chí hoàn thành: Bộ bản vẽ phác thảo (wireframe hoặc storyboard) gồm ít nhất 5 màn hình/khung hình.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:09:49.000000'),('3cde5b7d-a642-488e-bfe8-e1c56b811da8','0ad3072d-08ff-4a3b-acda-cb3bc400d2c2',1,'Đánh giá tiến độ qua bài kiểm tra định kỳ (Mốc ngày 70)','Tự thực hiện bài thi thử tổ hợp môn thế mạnh theo đúng khung thời gian chuẩn, phân tích các lỗi sai về phương pháp và lập danh sách 5 chủ điểm cần củng cố.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-04 14:38:51.000000'),('3d3467e5-ac26-46fe-9822-2c885a94eefd','0ad3072d-08ff-4a3b-acda-cb3bc400d2c2',3,'Đóng gói hồ sơ cá nhân và kế hoạch bứt phá (Mốc ngày 90)','Tổng kết thành quả 90 ngày, hoàn thiện bảng mục tiêu điểm số cuối cùng và lập danh sách các việc cần làm trong tháng cao điểm ôn thi.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-003\"]','2026-09-04 14:38:51.000000'),('3d434e21-cf77-4c40-8247-a6caedd53bca','185d90aa-f4db-46f5-a267-e0cb6e47ca12',3,'Hoàn thiện bản mẫu tương tác có tính năng AI (Mốc ngày 60)','Kết nối giao diện thiết kế với kịch bản xử lý thông minh, tạo bản demo thử nghiệm có thể tương tác trực tiếp trên thiết bị di động hoặc máy tính.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-013\",\"evidence-018\"]','2026-08-29 06:59:25.000000'),('3dd04e14-c3e3-4ae1-9513-ae08348e9449','6562ee9c-ff9f-435c-a1b9-8437a6855dee',3,'Đăng ký tham gia hoạt động AI Hacklab để mở rộng góc nhìn công nghệ','Ghi danh tham gia chương trình thực hành ứng dụng trí tuệ nhân tạo để học hỏi phương pháp áp dụng công nghệ vào thiết kế sản phẩm.',45,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-030\"]','2026-08-30 06:57:48.000000'),('3dd65576-373b-48f5-98ec-e131fa75cd9e','cf77d74f-f57f-4df9-b594-2f36aeb1038a',3,'Mốc ngày 60: Tổng hợp bảng phản hồi và tinh chỉnh nguyên mẫu','Ghi nhận đóng góp ý kiến của nhóm bạn, lập danh sách 5 điểm cần cải thiện và cập nhật hoàn chỉnh sản phẩm mẫu phiên bản 2.0.',75,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-30 07:10:06.000000'),('3e01755f-e8ad-4974-9ca2-5284267585b5','410be33d-d306-4180-ae0f-c695c510e7dd',2,'Mốc ngày 14: Xây dựng sơ đồ tư duy trực quan cho dự án đầu tay','Sử dụng công cụ sơ đồ trực quan để hệ thống hóa 5 nhánh ý tưởng chính liên quan đến một đề tài học tập hoặc bài tập lớn trên lớp.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:10:06.000000'),('3ea0bddb-d040-41bd-99b0-73cda3133e0b','7365eb8a-ae89-4e9a-8676-76aa739fb494',1,'Thiết lập thời gian biểu học tập và mục tiêu 30 ngày (Mốc 7 ngày)','Lập bảng kế hoạch học tập cá nhân trên sổ tay hoặc ứng dụng ghi chú, phân bổ 45 phút mỗi ngày cho việc tự học và rèn luyện kỹ năng.',45,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-012\"]','2026-09-05 07:49:00.000000'),('3eccb9d6-ee2c-586f-a9ff-52d27e2d9418','e8deed02-a869-565a-afdc-d8df35b44c51',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Thiết kế UI/UX và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"1ffb57aa-4456-535e-888f-c6b0c53e88f6\"]','2026-08-25 18:56:00.000000'),('3ed1ed0e-7128-43f5-9665-bf152ee12b68','86895e14-c7fc-4ed8-8042-12f9c1f60fc2',3,'Lập trình tính năng tương tác cơ bản cho bản mẫu','Hiện thực hóa giao diện tương tác với JavaScript và kết nối dữ liệu mẫu để hoàn thiện bản thử nghiệm.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:46:02.000000'),('3ed34824-aebb-43f6-bdf3-6df3b22fe4cf','54876e78-8ebe-4543-bbcd-8f04d07a1ebe',2,'Thực hiện vòng cải tiến','Cập nhật sản phẩm và ghi lại lý do cho từng quyết định.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 05:08:36.000000'),('3f2ea0fc-09c4-47d8-9985-cc4160ef550b','2c4ffe0e-12a0-48ff-9883-bff13b099c79',1,'Thiết lập sơ đồ tư duy định hướng học tập cá nhân (Mốc 7 ngày)','Bắt đầu bằng việc liệt kê các môn học học kỳ 1, xác định 3 chủ đề công nghệ - thiết kế muốn tìm hiểu sâu và vẽ thành sơ đồ trực quan. Tiêu chí hoàn thành: Một bản sơ đồ tư duy có đầy đủ mục tiêu điểm số và sở thích nghiên cứu.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:09:49.000000'),('3fe63d32-883a-41e3-8f28-c26293d363bc','b163486b-4572-4bd8-853a-0e7c68adc246',2,'Phác thảo nguyên mẫu giải pháp trực quan','Sử dụng công cụ thiết kế cơ bản để tạo bộ khung giao diện mô phỏng cho một bài tập lớn hoặc đề án học tập thực tế.',150,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 03:35:52.000000'),('4072c5e8-f9c9-4e55-89ce-0b8611348e49','93da586a-ba71-4067-a754-8d17835a3047',3,'Đánh giá tiến độ 90 ngày và thiết lập kế hoạch cho học kỳ tiếp theo (Mốc 90 ngày)','Viết bài tự phản chiếu điểm mạnh đã phát huy, điểm cần cải thiện trong học kỳ vừa qua và lập danh sách 3 mục tiêu cho kỳ học mới.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-014\"]','2026-09-05 03:54:06.000000'),('421b016e-14d3-4049-8e91-d81c9d71516b','f025c58a-772d-47b9-8c7c-8b0ce8e2c6b1',3,'Lập lộ trình tự học các kỹ năng công nghệ bổ trợ','Chọn 1 kỹ năng kỹ thuật hoặc công cụ quản lý dự án cần trau dồi, xây dựng mục tiêu 30 ngày tiếp theo kèm tài liệu tham khảo chi tiết.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 07:43:33.000000'),('4229a658-a538-4c44-b1c5-b8bf550520bc','fbcdcfa3-a0a6-40d9-afcb-b5414a640aaf',1,'Thiết lập bảng kế hoạch học tập và quản lý thời gian 30 ngày (Mốc 7 ngày)','Lập thời khóa biểu chi tiết kết hợp lịch học và tự học trên công cụ số, phân bổ ít nhất 6 khung giờ học tập cố định trong tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:34:53.000000'),('42abcae5-afe6-4fe0-acff-a152d941ebc8','36ed863b-ef2f-49ff-a236-18ef35802458',2,'Tổ chức buổi thảo luận ý tưởng giải pháp cùng nhóm học tập','Chủ trì phiên trao đổi 45 phút với 2-3 bạn học để phân tích nguyên nhân và lựa chọn phương án thiết kế trực quan khả thi nhất.',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:17:58.000000'),('42c8a759-e908-480f-b4d5-8226a8f3ca14','530e5ddc-fa0c-4658-9236-738c2af334eb',3,'Đánh giá tổng kết lộ trình và lập kế hoạch ứng tuyển thực tập (Mốc 90 ngày)','Rà soát lại toàn bộ sản phẩm đã hoàn thành, tự chấm điểm kỹ năng đạt được và lập danh sách các vị trí thực tập mục tiêu.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-011\"]','2026-09-04 14:26:53.000000'),('43826639-d882-429c-8c87-abe9f4627a2e','c107ac33-6dcf-4833-b0c3-a61690887d9a',3,'Tổng hợp tài liệu và viết báo cáo thu hoạch ý tưởng công nghệ (Mốc 30 ngày)','Soạn tài liệu tóm tắt dài 1 trang mô tả một ý tưởng giải pháp số đơn giản nhằm giải quyết vấn đề học tập hoặc đời sống sinh viên.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:54:06.000000'),('438faea8-1a1e-42a1-bd9b-f6b1ecd382ce','f7a369a7-7220-43df-86ad-b32b56bc986b',2,'Tạo phương án thử nghiệm','Phác thảo một giải pháp nhỏ có thể hoàn thành trong tuần.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 05:08:36.000000'),('43eea72e-e369-41bc-90fb-6d81d7331d53','4df97144-ba80-48dc-b8dd-e1ee32ec1da0',3,'Tìm hiểu thông tin các nhóm ngành tiềm năng','Nghiên cứu các bài viết học thuật và bản tin giáo dục về xu hướng nghề nghiệp liên quan đến phân tích dữ liệu và quản lý thông tin.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 09:09:29.000000'),('4467edb7-1330-46a6-a33e-93ab0831caef','c3c6e1aa-7d81-4496-8218-102f60fd1afa',1,'Biên tập nội dung hồ sơ học tập cá nhân (Mốc 75 ngày)','Lựa chọn 2 bài tập hoặc sản phẩm tiêu biểu trong kỳ học, viết bài phân tích quá trình thực hiện và kết quả đạt được.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-30 07:59:48.000000'),('44734fab-cb00-4860-aee9-864dc10b8008','8b4afeec-9273-41d1-bdf8-e99c7f992342',1,'Đăng ký tham gia AI Hacklab ứng dụng trí tuệ nhân tạo','Tham gia trải nghiệm tại Innovation Lab để khám phá cách thức đưa các công cụ trí tuệ nhân tạo vào tối ưu hóa giao diện và trải nghiệm người dùng.',60,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-030\"]','2026-08-29 06:39:46.000000'),('448fa6e9-a637-5fe5-af77-ef8bd433ed7f','60fdae6b-748b-59ad-a08c-94f61ee70d3e',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"bfe146ba-09db-5b2a-8589-c7df7ac2a57d\"]','2026-08-25 19:03:00.000000'),('44a32018-ddbb-574a-9ee2-5ae4d677291d','2a5fa512-ae9b-5ff8-a4dc-5e23d484ef69',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Nhà thiết kế trải nghiệm số.',75,'self_task',NULL,NULL,'[\"55ac4e0c-0a45-5e84-94f9-132e6436227f\"]','2026-08-25 18:14:00.000000'),('458714ca-d3e1-55f9-a498-de0d881a0695','65cf0c6c-b41b-5cd2-abac-defa2917091a',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"6fc19e75-06c9-5d2b-9740-7b8c7bf109c8\"]','2026-08-25 18:42:00.000000'),('45d4c740-b5c2-4f14-8833-d9416643da69','f3b5b02c-cfce-4e8a-89db-6fab6fcc4672',2,'Xây dựng bảng khảo sát và phỏng vấn 5 người dùng mục tiêu','Soạn bộ câu hỏi khảo sát hành vi, thực hiện phỏng vấn ngắn và tổng hợp chân dung người dùng (User Persona) vào tài liệu phân tích.',90,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-018\"]','2026-08-30 18:07:57.000000'),('45e67d27-2471-43c7-9a19-9dad43935c78','ccf6f9d9-c863-4fa7-b72f-1619f5935f98',1,'Tổng hợp và đóng gói Case Study dự án (Mốc 75 ngày)','Soạn thảo bài viết phân tích toàn bộ quá trình từ nghiên cứu, thiết kế, thử nghiệm đến kết quả cuối cùng theo cấu trúc trực quan.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-013\",\"evidence-015\"]','2026-08-29 06:44:00.000000'),('46a2ffd7-3445-4acf-861e-2b5f163196e5','479428f9-204e-4750-9c78-8fb3162e811d',1,'Xây dựng sơ đồ luồng người dùng (User Flow) cho giải pháp số','Vẽ sơ đồ trải nghiệm luồng thao tác người dùng từ lúc mở ứng dụng đến khi hoàn thành một tác vụ học tập cơ bản.',75,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-028\"]','2026-09-05 10:14:56.000000'),('46cae778-f861-422e-a781-a6d657f3191c','19d56d0d-7d77-4c1a-8916-2fd379860ff6',3,'Xây dựng lộ trình học tập mở rộng','Lập danh mục kỹ năng chuyên môn cần trau dồi cho 6 tháng tiếp theo nhằm mở rộng cơ hội phát triển.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-24 15:21:04.000000'),('46fe9acf-bdad-517b-98e6-75ea5d474755','18c12df8-cc17-5db3-b20d-a40d9a4d4f14',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"4ca68f30-7db2-5d35-b902-de72dbb99424\"]','2026-08-25 18:56:00.000000'),('47f3c6e7-f457-464f-a3bb-1358bd355617','a60c4388-d949-4052-9de6-cd6344a8afe8',3,'Mốc ngày 30: Đăng ký tham gia hoạt động Innovation Lab','Thực hiện đăng ký tham gia sự kiện AI Hacklab nhằm trải nghiệm quy trình phát triển giải pháp công nghệ cùng các cố vấn chuyên môn.',45,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-030\"]','2026-08-29 06:50:07.000000'),('48d9e83a-805f-55b2-b3da-206f9f3ede5a','65cf0c6c-b41b-5cd2-abac-defa2917091a',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"2a44b91b-8bd6-5be1-a1ee-9cc0deec342c\"]','2026-08-25 18:42:00.000000'),('48da6de5-0f56-4ab0-80d1-0cdfb96bb3dc','5db13e78-18a0-44a5-bd6e-5db3bc88c29d',3,'Đăng ký tham gia hoạt động rèn luyện ứng dụng công nghệ thực tế','Hoàn tất đăng ký tham gia chương trình thực hành công nghệ để chuẩn bị thử sức cùng các thử thách thực tế.',30,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-030\"]','2026-08-29 06:55:48.000000'),('48ef7de2-00da-546e-b4fa-d7097485c932','2955d13d-14e2-5300-b4fb-5b708e5499b3',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"bb3a5fc8-1199-590f-b2d6-50904c80682d\"]','2026-08-25 18:28:00.000000'),('49fd38e8-70fb-42a9-8357-df11f77575f5','99c36e53-3fc3-4e64-b086-7d08834836a8',3,'Đăng ký tham gia hoạt động AI Hacklab để mở rộng góc nhìn công nghệ (Mốc 30 ngày)','Ghi danh tham gia hoạt động AI Hacklab tại Innovation Lab nhằm cọ xát kiến thức thực tế và kết nối cùng cộng đồng học thuật.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-037\"]','2026-09-02 07:52:47.000000'),('4a0d665a-fefc-4365-bbff-e1dd47813864','4d765328-2862-4931-8dd0-314878a40702',3,'Tổ chức buổi thảo luận lấy ý kiến phản hồi từ nhóm bạn','Lên lịch họp ngắn 45 phút cùng nhóm học tập để trình bày ý tưởng, ghi nhận ý kiến đóng góp và cải tiến tài liệu sản phẩm.',60,'self_task',NULL,NULL,'[\"evidence-014\"]','2026-09-05 03:19:52.000000'),('4a63e2d0-e521-4a9b-b126-bed0060509f9','5ae07e3b-d682-4615-9454-6f38bfa33e63',1,'Nghiên cứu cấu trúc và trải nghiệm của một ứng dụng phổ biến','Lựa chọn một ứng dụng công nghệ quen thuộc, ghi chép lại hành trình người dùng và phân tích các điểm chạm giao diện chính.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:09:11.000000'),('4a8334c9-bb5d-43e1-82f3-01985dc6816b','5d6dc234-faa0-43ec-a8f3-b9a020140d86',1,'Thiết lập môi trường lập trình chuẩn và cấu hình kho mã nguồn','Cài đặt công cụ lập trình (IDE), thiết lập tài khoản Git, tạo repository cá nhân và viết file README giới thiệu lộ trình học tập để làm quen với quy trình quản lý mã nguồn (hoàn thành trước mốc 7 ngày).',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-05 09:58:29.000000'),('4acdcaee-9db5-4584-8ec1-5f9d7a08ef2b','5c9d0a05-bbe4-4f55-b6cd-99d6e235277b',1,'Xây dựng bản thảo thiết kế luồng xử lý dữ liệu cho ứng dụng','Lập tài liệu đặc tả yêu cầu cho một ứng dụng quản lý tiện ích học tập đơn giản, vẽ biểu đồ luồng dữ liệu giữa các mô-đun chức năng.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-007\"]','2026-09-04 15:00:27.000000'),('4afa24b1-cc90-4d99-a37c-f0abaef8a2ed','460cc8a6-9bb5-4089-9a18-b6424883b704',3,'Điều phối buổi phản biện nội bộ và hoàn thiện báo cáo (Mốc 60 ngày)','Chủ trì buổi họp nhóm thử nghiệm thuyết trình, ghi nhận đóng góp và hiệu chỉnh tài liệu báo cáo dự án lần cuối.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:20:33.000000'),('4b423ff1-e7cf-45f3-8a2f-94e621a9888b','33251f2f-216b-4dc8-9121-d3583a53d4bd',2,'Xây dựng slide thuyết trình giải pháp và kịch bản demo','Thiết kế bộ trình chiếu 10 slide tóm tắt vấn đề, kiến trúc giải pháp, trải nghiệm người dùng và kết quả dữ liệu kiểm thử.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-014\",\"evidence-015\"]','2026-09-02 08:08:52.000000'),('4bd2ff1f-a2f2-4cef-9582-03354056d317','f3b5b02c-cfce-4e8a-89db-6fab6fcc4672',1,'Đăng ký tham gia chương trình Product Sprint xây dựng sản phẩm số','Thực hiện đăng ký và tham gia workshop định hướng phát triển sản phẩm tại Product Lab để tiếp cận quy trình chuẩn.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-037\"]','2026-08-30 18:07:57.000000'),('4be8a61a-0bd5-4042-a2e0-90ec526b44e7','6b38b27e-c73c-4c3e-85e2-2a72f6427923',2,'Đăng ký tham gia hoạt động Product Sprint để hoàn thiện quy trình sản phẩm (Mốc 50 ngày)','Ghi danh tham gia chương trình Product Sprint tại Product Lab FPT để trải nghiệm phương pháp phát triển sản phẩm theo vòng lặp nhanh.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-038\"]','2026-08-31 15:59:36.000000'),('4c0edf19-a049-4d5c-b0c9-48da0cdf9d5c','7b030543-80a7-4176-8cbb-8ea2fb2ed9b9',1,'Hiện thực hóa các API cốt lõi và xử lý luồng dữ liệu (Mốc 40 ngày)','Viết mã nguồn xử lý nghiệp vụ chính, tối ưu hóa các câu truy vấn và kiểm tra luồng phản hồi dữ liệu qua Postman.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-09-04 14:26:53.000000'),('4c274de5-5177-498a-ac31-942e4857d011','54876e78-8ebe-4543-bbcd-8f04d07a1ebe',3,'Đánh giá kết quả','So sánh trước và sau để rút ra một bài học cụ thể.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 05:08:36.000000'),('4c303419-f729-4f26-836c-abaa5db4a2c1','6ff93b0d-4f36-4126-96ba-cf4bc10a8a9b',3,'Tổ chức phiên kiểm thử nguyên mẫu và họp nhóm phản hồi (Mốc 60 ngày)','Mời 2 thành viên nhóm cùng tham gia đánh giá chéo nguyên mẫu, ghi nhận biên bản 5 điểm cần cải tiến về trải nghiệm giao diện.',75,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\",\"evidence-017\"]','2026-08-31 04:21:44.000000'),('4c326354-3be5-4ca0-88d0-b71a1897b243','0932d3f6-e190-4530-8324-595793ce686c',1,'Tham dự Startup Demo Day FPT University','Đăng ký tham dự sự kiện Demo Day tại Hội trường Innovation FPT để học hỏi cách trình bày và thương mại hóa sản phẩm công nghệ.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-010\",\"evidence-022\"]','2026-09-05 02:49:36.000000'),('4d2e617f-6eb6-4c17-8cf0-70dbb035de58','9ba56e8d-6b0f-4e02-8ce3-11d316af3e00',3,'Mốc 30 ngày: Tổng hợp tài liệu kỹ thuật và tự đánh giá mã nguồn','Viết tài liệu tóm tắt các nguyên tắc lập trình sạch (Clean Code) đã áp dụng, chạy kiểm thử tự động đơn giản và đẩy phiên bản đầu tiên lên kho mã nguồn.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-012\"]','2026-09-02 15:44:07.000000'),('4d68f134-52f4-43fc-94db-4562b0d6e2d0','f025c58a-772d-47b9-8c7c-8b0ce8e2c6b1',2,'Viết báo cáo tự rút kinh nghiệm sau giai đoạn làm việc nhóm','Phân tích 3 điểm đã làm tốt và 2 điểm cần cải thiện trong phong cách điều phối nhóm, đề xuất giải pháp cụ thể cho học kỳ sau.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 07:43:33.000000'),('4d74e831-ccaa-4cd8-bddf-618ea4d75954','1947498b-9d81-4bc7-ab62-2866fdb5e519',2,'Xây dựng các chức năng cốt lõi và kiểm thử đơn vị (Mốc 50 ngày)','Thực hiện lập trình các luồng xử lý chính, viết tối thiểu 5 bộ kiểm thử tự động (Unit Tests) để xác minh độ chính xác của logic nghiệp vụ.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-009\",\"evidence-011\"]','2026-09-04 15:03:37.000000'),('4e711b7b-216f-40a8-828a-f30812fd7c65','02ef1cd1-76e8-47cd-a6c4-c4e65046340e',3,'Xây dựng khung ứng dụng và thiết kế sơ đồ cơ sở dữ liệu (Mốc 30 ngày)','Thiết kế biểu đồ quan hệ thực thể (ERD) và viết mã nguồn khung (boilerplate code) cho dự án đầu tay.',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-04 14:26:53.000000'),('4e764513-f754-495f-a916-df89d96014f2','786df7fd-ab49-43a5-9c4d-9c1c0b71502d',3,'Tổng hợp sản phẩm và hoàn thiện slide thuyết trình (Mốc 60 ngày)','Thiết kế bộ slide thuyết trình trực quan, tổ chức một buổi tập dượt thuyết trình thử nghiệm cùng nhóm. Tiêu chí hoàn thành: Bộ slide chuẩn mực dài 8-12 trang và bản ghi nhận phản hồi từ buổi tập dượt.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-30 07:09:49.000000'),('4f5ab3f2-f4d3-4a34-bf9d-91bd113c3430','41be4372-cfae-483a-8f17-29186718e7d0',3,'Tổng kết lộ trình và xác định mục tiêu học kỳ tiếp theo','Đánh giá lại những bước tiến về tư duy trực quan, phong cách điều phối nhóm và vạch ra 3 ưu tiên chuyên môn cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\",\"evidence-004\"]','2026-08-26 03:35:52.000000'),('4fc058ee-8278-4502-9a0e-0acfc18ea89b','4df97144-ba80-48dc-b8dd-e1ee32ec1da0',1,'Rà soát thời gian biểu học tập và sinh hoạt','Ghi chép và đánh giá việc sử dụng thời gian trong 7 ngày liên tiếp để tối ưu hóa khoảng thời gian tự học trọng điểm.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 09:09:29.000000'),('4fc6d3ea-2350-4202-85aa-8bdcb0492b18','d17d7a2a-d8e7-45a6-85bc-b6ca55eff2c9',2,'Thu thập và phân tích tài liệu chuyên khảo nhập môn (Mốc 14 ngày)','Tìm kiếm và đọc 3 bài viết học thuật hoặc tài liệu ngành, ghi chú lại 5 khái niệm cốt lõi theo dạng sơ đồ tư duy trực quan.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:20:33.000000'),('4fde3bfd-25f8-4bf6-b1f5-3635f5ab8322','f3b5b02c-cfce-4e8a-89db-6fab6fcc4672',3,'Phác thảo sơ đồ luồng người dùng và hệ thống wireframe cơ bản','Vẽ User Flow và thiết kế tối thiểu 6 màn hình wireframe dạng trắng đen trên công cụ thiết kế để xác định cấu trúc tính năng.',120,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-014\"]','2026-08-30 18:07:57.000000'),('4ff7b1a2-ff7f-4e7f-9f3f-131d8151bde9','954ac626-eae0-461d-9fe3-eb330a7ab030',2,'Tham gia AI Hacklab để tìm hiểu ứng dụng thực tế','Đăng ký và tham dự buổi thảo luận chuyên đề về AI để nắm bắt xu hướng công nghệ mới.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-018\"]','2026-09-05 03:46:02.000000'),('500dbe9a-fb63-43b2-8365-eb50f24cd9e0','1bd1f1c9-33c6-4d7b-99bc-8d0b0ac3ba13',3,'Đánh giá tiến độ cá nhân và tinh chỉnh kế hoạch tháng đầu (Mốc 30 ngày)','Viết nhật ký tự phản hồi về mức độ hoàn thành bài tập, chỉ ra 2 điểm làm tốt và 2 điểm cần cải thiện trong cách tự học; tiêu chí hoàn thành là bản đúc kết ngắn gọn dài 1 trang A4.',45,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 08:10:24.000000'),('500f5153-4ca2-47c9-abb6-b0debf470c4d','7b030543-80a7-4176-8cbb-8ea2fb2ed9b9',3,'Tổ chức buổi chia sẻ kỹ thuật nhóm và thu nhận phản hồi (Mốc 60 ngày)','Trình bày sơ đồ kiến trúc và tính năng dự án trước nhóm học tập, ghi nhận góp ý và lập danh sách cải tiến.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-006\"]','2026-09-04 14:26:53.000000'),('502da14c-3283-5216-9423-489de580cd9b','75699170-9919-5861-95e5-c746f100077e',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Thiết kế UI/UX và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"4989f77d-56b8-5a4f-843e-1dc05ffa8317\"]','2026-08-25 18:56:00.000000'),('5069f97c-9f3a-4c9e-96fb-143fdf239ed3','4acb702b-8f89-49b3-b21c-309e36f51868',1,'Đóng gói ứng dụng và cấu hình triển khai trực tuyến','Cấu hình biến môi trường, tối ưu hóa tốc độ tải trang và triển khai sản phẩm lên nền tảng đám mây miễn phí để tạo đường dẫn hoạt động thực tế (hoàn thành trước mốc 75 ngày).',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-005\"]','2026-09-05 09:58:29.000000'),('5085ad2d-5cbb-4283-8e8f-4ee07b79af5a','da025c73-4c09-4113-b803-e323a1aba0dc',1,'Hoàn thiện đầu ra','Tổng hợp phiên bản tốt nhất cùng bằng chứng tiến bộ.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-25 14:17:14.000000'),('50c4e745-ff6f-54b9-b691-b7b303ac2035','dada94c1-b228-5e1d-af32-769318058810',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Digital Marketing và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"4a9e19f3-bd3a-538b-9bee-713ac6369e59\"]','2026-08-25 18:28:00.000000'),('510a7fbb-e81c-4d03-9d3b-52863f4395f1','d9419ec7-d013-4f82-8749-16a5481ecac6',3,'Ghi chép phản tư phong cách tương tác','Theo dõi và ghi nhận phản hồi trong các buổi làm việc nhóm để điều chỉnh cách giao tiếp phù hợp.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-24 15:21:04.000000'),('511e26ae-20c3-4b5c-b0f3-2a3ecd98f73c','ae0b874e-0652-40cb-8060-484156e64b9f',1,'Thiết lập sơ đồ tư duy tổng quan môn học chuyên ngành','Thu thập đề cương môn học nền tảng, sử dụng công cụ vẽ sơ đồ trực quan để hệ thống hóa toàn bộ các chương mục và khái niệm cốt lõi.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:17:58.000000'),('5129da6c-e9a2-4594-aec4-138c0e05e6ee','40210f19-3f63-4950-8da4-32559576b443',2,'Thực hành thu thập và tổng hợp phản hồi đa chiều','Lắng nghe ý kiến đóng góp từ các bạn cùng nhóm về giải pháp của bài tập, ghi nhận ít nhất 2 góc nhìn mới vào tài liệu chỉnh sửa.',50,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-28 07:43:33.000000'),('512bc0cd-e7b3-4b71-b353-334c63b28447','410be33d-d306-4180-ae0f-c695c510e7dd',3,'Mốc ngày 30: Hoàn thiện bản đề xuất dự án học tập cá nhân','Tổng hợp kết quả nghiên cứu thành văn bản đề cương 2 trang gồm mục tiêu học tập, kết quả kỳ vọng và mốc thời gian thực hiện chi tiết.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-003\"]','2026-08-30 07:10:06.000000'),('514b8919-39b6-4b41-87db-0973d988bf4d','3b080d9f-bba3-4e2c-a03d-d40684b897d9',3,'Thực hành phản biện và điều chỉnh kế hoạch linh hoạt','Đưa ra các tình huống phát sinh giả định trong dự án và xây dựng phương án ứng phó thay thế.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:51:04.000000'),('51626364-6da3-4ff9-8842-1afb33883f08','45ef38ea-ce8f-4de3-a167-8dcd66cd20ed',3,'Thực hiện phiên thử nghiệm trải nghiệm người dùng','Quan sát 3 người dùng thực hiện nhiệm vụ trên bản mẫu, ghi nhận các điểm nghẽn thao tác và thời gian hoàn thành.',60,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-018\"]','2026-08-31 15:54:21.000000'),('5162e636-3400-4b09-aa58-0184820d175e','fc6693fd-6091-458d-bbf3-4c8347a87745',1,'Xây dựng mẫu tương tác kỹ thuật số cơ bản','Chuyển đổi bản vẽ phác thảo thành một bản mẫu kỹ thuật số có khả năng tương tác để kiểm tra luồng sử dụng.',180,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:09:11.000000'),('51cf6f74-6f92-4258-9658-15d6b5b7e4ba','5f7e1713-4d7b-4846-8cf4-c8974d0f77fe',1,'Xây dựng hệ thống bảng màu và thành phần giao diện chuẩn','Thiết kế bộ UI Kit gồm màu sắc, kiểu chữ và các nút tương tác cơ bản cho toàn bộ màn hình ứng dụng.',75,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\"]','2026-09-03 14:02:44.000000'),('5217d454-1276-474b-a5a5-aba74a8dec62','1947498b-9d81-4bc7-ab62-2866fdb5e519',3,'Hoàn thiện giao diện và đóng gói tài liệu kỹ thuật (Mốc 60 ngày)','Tinh chỉnh giao diện người dùng thân thiện, kiểm tra trải nghiệm thao tác và cập nhật đầy đủ hướng dẫn cài đặt trong tệp tài liệu dự án.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\"]','2026-09-04 15:03:37.000000'),('52564b97-4d05-4cdf-ba13-fce46722bc79','f32160ac-2713-4173-92b6-711e4c6f12cb',1,'Biên tập nội dung hồ sơ học tập cá nhân (Mốc 75 ngày)','Lựa chọn 2 bài tập hoặc sản phẩm tiêu biểu trong kỳ học, viết bài phân tích quá trình thực hiện và kết quả đạt được.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-02 14:23:47.000000'),('527c983b-8ffd-4f53-8c0a-c89c5201c4da','8b6154bd-6c05-42ac-9919-5e05acbb1f8f',4,'Thực hiện phiên kiểm thử tương tác nhóm và ghi nhận lỗi','Tổ chức phiên kiểm thử nhanh cùng 3 bạn học trong nhóm dự án, quan sát thao tác và ghi nhận các điểm gây bối rối trong quá trình sử dụng. Đầu ra là biên bản tổng hợp 5 điểm cần tinh chỉnh.',75,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-017\"]','2026-08-30 06:51:26.000000'),('52c1b617-92b0-47ae-9756-fd2cdf9a5258','a2502720-8ba6-42c2-8892-e53acf0b12f2',2,'Chuẩn bị câu chuyện','Trình bày vấn đề, cách thử nghiệm, kết quả và bài học.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 03:26:09.000000'),('52d19501-c1ae-427d-bb0b-9c866bc61241','3ba2c0ef-446d-4a5c-8ae4-a757d2425cd6',2,'Thiết kế slide trình bày báo cáo tổng kết đồ án','Soạn bộ slide 8–10 trang cô đọng, nhấn mạnh vào giá trị giải pháp và phân tích dữ liệu thực tế đạt được.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-014\"]','2026-08-31 15:54:21.000000'),('537dc398-f81f-47ae-acff-f980ad392adc','f4c407ff-7dc9-472c-ba65-deab159c356f',3,'Tổng hợp báo cáo phân tích và phản biện kỹ thuật (Mốc 60 ngày)','Viết bản đánh giá phản biện cho thiết kế hệ thống của nhóm, chỉ ra các điểm tối ưu về hiệu năng và phương án cải tiến khả thi.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-015\",\"evidence-029\"]','2026-08-31 08:22:34.000000'),('53d39405-2114-4f4c-86f0-ab1c7803cad1','9f58267d-1f4f-4e21-befc-976ab90b52f0',1,'Lập bảng Ma trận Kế hoạch Tuần tại Mốc 7 Ngày','Vẽ và thiết lập bảng thời gian biểu tuần ưu tiên theo mức độ quan trọng cho các môn học chính lớp 12, phân bổ 45 phút học tập tập trung mỗi ngày.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-31 15:26:24.000000'),('542e2abc-1526-4276-8402-eeafaaab8be1','fc6693fd-6091-458d-bbf3-4c8347a87745',3,'Tổng hợp tài liệu yêu cầu tính năng (PRD cơ bản)','Viết tài liệu mô tả mục tiêu, bài toán người dùng và tiêu chí đánh giá chất lượng cho tính năng vừa thử nghiệm.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-26 05:09:11.000000'),('5440c448-483e-43dd-96cf-ab25ed242043','af98ae9e-f825-406b-b251-c9f234dabcad',1,'Hệ thống hóa kiến thức cấu trúc dữ liệu và giải thuật cơ sở (Mốc 7 ngày)','Thực hiện giải và ghi chú lại 10 bài tập cấu trúc dữ liệu căn bản (mảng, danh sách liên kết, ngăn xếp, hàng đợi) kèm phân tích độ phức tạp thời gian.',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-05 05:53:02.000000'),('5451391f-c5ac-4689-b7d1-6a585ec41d54','414a28d3-ac68-49c2-a015-015beaac2c76',1,'Chọn một vấn đề gần gũi','Mô tả người dùng, nhu cầu và kết quả mong đợi.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 03:26:09.000000'),('5526edb7-6a41-462e-a250-cebc8ac502f8','50a05c54-d738-474b-a949-d4306d4212a8',3,'Tổ chức buổi họp nhóm phản biện và tối ưu hóa phương án (Mốc 60 ngày)','Chủ trì buổi trao đổi nhóm 45 phút để tiếp nhận phản hồi từ các thành viên và thống nhất phiên bản hoàn thiện của sản phẩm mẫu.',75,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\"]','2026-09-05 03:54:06.000000'),('5591a29c-9f3b-499e-9d0f-e6fcf185e8dc','5fa2c9de-a024-4c20-a315-2ed76f92c0c1',3,'Thực hành giải bài tập lập trình cấu trúc và viết nhật ký giải thuật','Triển khai viết mã giải quyết 5 bài toán thuật toán cơ bản, kiểm thử tự động với các bộ dữ liệu mẫu và ghi lại giải thích logic vào tài liệu tổng hợp.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\",\"evidence-007\"]','2026-09-04 15:00:27.000000'),('55b1c957-34e0-4f58-b0f9-944080f72fa6','b01cf096-a8f5-4e6d-8519-04d9aca7c9e5',2,'Phân tích 3 mô hình dự án mẫu','Tìm hiểu cách thức tổ chức và vận hành của 3 dự án thực tế để rút ra các bài học về quy trình triển khai.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-24 15:40:29.000000'),('564360b8-b7c0-4436-be99-93ad0c3b2c3a','c325adb9-ffd5-4803-bf29-5c74ecec1b98',2,'Thiết kế và xuất bản Portfolio số (Mốc 85 ngày)','Tạo trang cá nhân trực tuyến giới thiệu kỹ năng, dự án đã làm và định hướng phát triển học thuật.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:20:33.000000'),('564b58a0-5f92-4772-b087-2ca770bb6302','e7b70721-8423-434b-9765-8236b8dc3718',1,'Xây dựng bài trình bày giải pháp trực quan (Mốc 75 ngày)','Thiết kế bộ trình chiếu 10 trang tóm tắt vấn đề, giải pháp, kết quả thử nghiệm và định hướng mở rộng của dự án.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\"]','2026-09-05 03:54:44.000000'),('5678deb5-ee9c-4f3e-8ae0-6a9782aeb668','6c120050-75da-4589-9a23-695ba8c2c87a',3,'Thực hiện phỏng vấn và thu thập góp ý của người dùng (Mốc 60 ngày)','Tiến hành thử nghiệm nguyên mẫu với ít nhất 03 bạn cùng khóa, ghi nhận các điểm nghẽn và cập nhật bảng danh sách cải tiến giao diện.',75,'self_task',NULL,NULL,'[\"evidence-012\",\"evidence-017\"]','2026-08-29 06:44:00.000000'),('574aadf6-a877-4609-a644-fd95d7b12a62','a773e589-25a6-4bff-93b8-03af6839529c',2,'Xây dựng kịch bản kiểm thử tự động cho module','Viết các bộ kiểm thử đơn vị để kiểm tra tính đúng đắn của hàm xử lý và khả năng bắt lỗi; tiêu chí hoàn thành là toàn bộ bài kiểm thử tự động vượt qua mà không phát sinh lỗi nghiêm trọng.',80,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-05 09:46:28.000000'),('57f7b6b8-e693-45ed-8271-a3af0c5f5f1d','9f58267d-1f4f-4e21-befc-976ab90b52f0',3,'Tổng hợp Báo cáo Khảo sát Hướng ngành tại Mốc 30 Ngày','Thu thập và so sánh 3 ngành học tiềm năng (Quản trị Công nghệ, Khoa học Môi trường, Thiết kế) dựa trên chương trình đào tạo và cơ hội phát triển.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-31 15:26:24.000000'),('58336f3a-b262-5dfb-8bc6-a83b904f3cc6','6ffc820d-491c-5a5a-a0ae-de51a245c9be',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Điện toán đám mây và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"d2563021-c020-5018-9bbb-b90f4627b617\"]','2026-08-25 19:03:00.000000'),('58682679-e806-4962-b03b-006e8b20f87a','b01cf096-a8f5-4e6d-8519-04d9aca7c9e5',3,'Xây dựng thời gian biểu học tập cá nhân','Lập kế hoạch tuần chi tiết, phân bổ khung giờ cố định cho việc tự học và rèn luyện kỹ năng.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-24 15:40:29.000000'),('5968eff3-21b1-4b11-8c61-bde36a1b6b8c','99c36e53-3fc3-4e64-b086-7d08834836a8',1,'Phân tích 3 sản phẩm số tiêu biểu và lập bảng so sánh tính năng (Mốc 7 ngày)','Lựa chọn 3 ứng dụng phổ biến trên thị trường, phân tích luồng trải nghiệm người dùng và tổng hợp ưu, nhược điểm vào bảng so sánh chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-010\"]','2026-09-02 07:52:47.000000'),('59fa6b3f-3966-457f-b8ab-362feca6d647','51d2c08c-d654-4d7b-b77f-1ea3f868a481',1,'Thiết kế lược đồ cơ sở dữ liệu cho dự án học tập','Phác thảo sơ đồ ERD gồm ít nhất 4 bảng dữ liệu cho hệ thống quản lý học tập; tạo các câu lệnh SQL tạo bảng, khóa chính, khóa ngoại và chèn dữ liệu mẫu.',75,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\",\"evidence-024\"]','2026-09-05 05:46:35.000000'),('5a0aff06-f349-43de-81e5-a745ccf7cecf','75710fe4-b8a7-42f1-85d9-3a41585991f0',1,'Soạn thảo bài thuyết trình tổng quan dự án sản phẩm số','Tổng hợp bài toán, giải pháp, giao diện mẫu và kế hoạch triển khai thành tập slide súc tích gồm 7 trang.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-011\"]','2026-09-05 10:14:56.000000'),('5a2b3b45-84ce-4d76-bde7-22b14491957e','79547a5f-83d5-40ec-bbbc-d8a47fde3837',1,'Khảo sát và lập danh mục kỹ năng công nghệ ứng dụng','Nghiên cứu cấu trúc các môn học cơ sở ngành và lập bảng tổng hợp các công cụ hỗ trợ tư duy trực quan cũng như quản lý tiến độ phù hợp với môi trường đại học.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-26 03:35:52.000000'),('5b0b6fc4-a9ff-4b51-a18d-7296c7eb622b','caf3d996-e763-4549-a003-987defd6ddf8',1,'Hoàn thiện báo cáo tổng kết dự án và tài liệu minh chứng','Hệ thống hóa toàn bộ quá trình nghiên cứu, kết quả đạt được và bài học kinh nghiệm vào một tài liệu trình bày trực quan.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 08:08:53.000000'),('5b7284ca-43f2-478a-9980-32e7950ea4a1','ed6446ed-1aa2-4583-b3f3-d337047e57cc',2,'Mốc Ngày 52: Thiết lập bộ kiểm thử đơn vị và kiểm thử tích hợp','Viết bộ kiểm thử tự động cho các hàm chức năng quan trọng và xử lý triệt để các trường hợp biên phát sinh. Tiêu chí hoàn thành: Bộ test chạy tự động không có lỗi và tạo báo cáo kết quả kiểm thử rõ ràng.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-006\",\"evidence-025\"]','2026-09-05 05:33:43.000000'),('5b9d54e7-e53b-4498-bed7-8d9c885c2043','239fc4ad-162d-4c58-b545-58509dbc81cc',3,'Mốc Ngày 30: Xây dựng khung ứng dụng cơ bản và kiểm thử giao tiếp API','Hiện thực hóa khung mã nguồn (boilerplate), kết nối cơ sở dữ liệu và triển khai 3 API định tuyến cơ bản. Tiêu chí hoàn thành: Chạy thử thành công các yêu cầu qua Postman với mã phản hồi chuẩn 200 OK.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-005\",\"evidence-011\"]','2026-09-05 05:33:43.000000'),('5c204e16-3577-481c-9e51-79d6457e70d4','32804826-c2fc-458f-8a53-f2fb1c8fab9a',1,'Xây dựng khung hồ sơ năng lực học tập số (Digital Portfolio)','Tổng hợp các sản phẩm sơ đồ, bài nghiên cứu và dự án nhóm đã thực hiện trong 2 tháng qua vào một trang giới thiệu năng lực trực tuyến.',100,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:17:58.000000'),('5c444999-e080-4a65-bacc-ee94d930daa4','c5ac9ad1-1356-44d7-b5e7-27fe90b70e2d',1,'Triển khai ứng dụng lên môi trường điện toán đám mây','Đóng gói ứng dụng và thiết lập quy trình triển khai tự động lên nền tảng miễn phí (như Vercel/Render/Railway); kiểm tra trạng thái hoạt động trực tuyến 24/7.',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\",\"evidence-038\"]','2026-09-05 05:46:35.000000'),('5cda4207-cfb2-5815-b5e7-e008eaf91c77','7558473a-3bdb-5bf9-aab9-92bfab325f8a',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"b727f954-c3ae-5ff4-81fc-a58424fe319c\"]','2026-08-25 19:10:00.000000'),('5cfdb34b-8e8b-4f7a-816f-162006c8d090','410be33d-d306-4180-ae0f-c695c510e7dd',1,'Mốc ngày 7: Lập bảng phân tích nhu cầu và sở thích học tập','Thực hiện rà soát 3 môn học chuyên ngành yêu thích, liệt kê các chủ đề muốn đào sâu và viết bản tóm tắt 300 từ về định hướng tìm tòi kiến thức.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-30 07:10:06.000000'),('5d52454b-2e48-55be-aeba-d27224e5690f','ea5dab52-172f-5073-b8e4-67764afa44cb',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Digital Marketing và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"bb3a5fc8-1199-590f-b2d6-50904c80682d\"]','2026-08-25 18:28:00.000000'),('5d7a1d36-4926-4171-b9b8-2a341102cf36','6c8bb01c-35c5-4f1e-965a-5e17638bc6bf',1,'Phác thảo sơ đồ luồng hoạt động của sản phẩm (Mốc 37 ngày)','Vẽ sơ đồ các bước trải nghiệm chính của người dùng từ khi bắt đầu đến khi hoàn thành thao tác trên công cụ vẽ sơ đồ hoặc giấy.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:54:44.000000'),('5dd4b64e-82bd-4885-bff1-a84a054b5eb2','40210f19-3f63-4950-8da4-32559576b443',1,'Chủ trì buổi lập kế hoạch cho bài tập nhóm','Tổ chức cuộc họp ngắn 45 phút cùng nhóm học tập, soạn thảo bảng phân chia trách nhiệm và thống nhất thời hạn nộp bài của từng thành viên.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 07:43:33.000000'),('5df8432d-39ea-46b9-97d1-0d0c0e284d1c','52b33b60-0bac-43bc-9ae4-05cc9c1d78e6',2,'Soạn thảo bài viết Case Study phân tích quá trình giải quyết bài toán','Viết bài phân tích chi tiết từ khâu nghiên cứu vấn đề, phân tích dữ liệu đến giải pháp thiết kế cuối cùng dưới định dạng bài viết chuyên môn. Đầu ra là tài liệu Case Study có kèm hình ảnh minh họa.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-015\"]','2026-08-30 06:51:26.000000'),('5ea72969-aa94-4526-8211-bced77c25690','ca952e6f-76f6-4bbe-b11c-9b5157a1251f',1,'Quan sát và học hỏi kinh nghiệm tại Startup Demo Day','Tham dự sự kiện Startup Demo Day FPT University để ghi chép phương pháp pitching và cách trình bày giải pháp của các đội thi.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-022\"]','2026-09-05 03:19:52.000000'),('5f26f95e-3cc6-59fa-9b1d-e3db1b5014c9','60fdae6b-748b-59ad-a08c-94f61ee70d3e',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Kỹ sư nền tảng đám mây và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"5937634f-cb65-52ce-8c23-72aada489064\"]','2026-08-25 19:03:00.000000'),('5f27059b-d800-4c91-9904-d53da85c27c3','f3b5b02c-cfce-4e8a-89db-6fab6fcc4672',4,'Tổ chức buổi họp phản biện nhóm và hoàn thiện hồ sơ thiết kế','Trình bày luồng sản phẩm trước nhóm học tập trong 15 phút, ghi nhận góp ý và chuẩn hóa tài liệu đặc tả yêu cầu người dùng.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-017\"]','2026-08-30 18:07:57.000000'),('5f2f4509-d12b-55ab-8b89-43cf43684b97','b4708adc-b93c-5e85-af18-eb08b6023450',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"1e417d13-8dee-5201-bce3-9dec171db9cb\"]','2026-08-25 18:49:00.000000'),('5f668c96-ece3-41ad-b6a6-f315caef85fb','cbe6c769-32ba-45b4-a961-bce09427bc07',3,'Tổng kết hồ sơ định hướng phát triển','Lưu trữ sản phẩm, đánh giá sự tiến bộ cá nhân và thiết lập mục tiêu học thuật cho học kỳ kế tiếp.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 02:38:47.000000'),('5fdfe3d3-7b90-4cf7-ada6-d35bbea18db2','ef54a41d-8316-460f-8867-b5a134b40248',3,'Tổ chức buổi họp nhóm phản biện nhanh và ghi nhận đóng góp','Chủ trì phiên thảo luận nhóm ngắn 30 phút, áp dụng bảng tiêu chí phản hồi tích cực để lắng nghe và tổng hợp ý kiến hoàn thiện tài liệu đề xuất.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\"]','2026-09-05 08:20:23.000000'),('60255f2f-fef1-4f19-8735-03e420259cce','360aa0a7-4a60-47a8-9f93-ade52750f15c',3,'Xây dựng bộ kiểm thử tự động cho các hàm chức năng chính','Viết tối thiểu 5 ca kiểm thử tự động (unit tests) để kiểm tra các luồng xử lý quan trọng và tạo báo cáo kiểm thử hoàn chỉnh (hoàn thành trước mốc 60 ngày).',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-025\"]','2026-09-05 09:58:29.000000'),('602ea89c-b51c-433b-98af-ccf2e811cfe8','3ba2c0ef-446d-4a5c-8ae4-a757d2425cd6',3,'Tập dượt thuyết trình và ghi nhận nhận xét','Thực hiện thuyết trình thử 10 phút trước bạn bè hoặc giảng viên hướng dẫn để rèn luyện phong thái tự tin và kỹ năng phản biện.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-08-31 15:54:21.000000'),('603112d8-836b-47d6-a499-7d259246c3a0','f9009ae4-5eee-44bb-b53a-ced9c5b7d2bd',1,'Thiết kế và triển khai API backend cho bài toán quản lý sinh viên (Mốc 40 ngày)','Viết mã nguồn xây dựng các endpoint RESTful CRUD hoàn chỉnh, kiểm soát dữ liệu đầu vào và xử lý mã lỗi theo đúng tiêu chuẩn thiết kế.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-09-05 05:53:02.000000'),('608b8515-6441-5dc8-ac86-616800697eca','60fdae6b-748b-59ad-a08c-94f61ee70d3e',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"a868192f-e472-5c04-a024-deac7b0e3801\"]','2026-08-25 19:03:00.000000'),('60f390fa-aee1-40c8-af52-711c99690985','51d2c08c-d654-4d7b-b77f-1ea3f868a481',3,'Thiết kế giao diện người dùng tương tác','Xây dựng giao diện web trực quan hiển thị danh sách, biểu mẫu nhập liệu và kết nối trực tiếp với các API đã xây dựng; đảm bảo giao diện phản hồi mượt mà.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-005\",\"evidence-022\"]','2026-09-05 05:46:35.000000'),('60fb0faf-d8c9-4fca-bca2-781cf6ec665a','a773e589-25a6-4bff-93b8-03af6839529c',3,'Tối ưu hóa mã nguồn và rà soát bảo mật cơ bản','Rà soát lại quy ước mã nguồn, tái cấu trúc các đoạn mã dư thừa và kiểm tra các lỗ hổng xác thực dữ liệu đầu vào; tiêu chí hoàn thành là báo cáo kiểm tra mã nguồn sạch và tối ưu.',70,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-007\"]','2026-09-05 09:46:28.000000'),('615c9c9f-72f6-52ba-9b78-3581bfcf673a','75699170-9919-5861-95e5-c746f100077e',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Nhà thiết kế UI/UX.',75,'self_task',NULL,NULL,'[\"1ffb57aa-4456-535e-888f-c6b0c53e88f6\"]','2026-08-25 18:56:00.000000'),('61e89162-5710-4f0d-9590-891e1fdf46eb','5eaae2d8-e7c6-484d-a023-1c6ae0208820',1,'Đăng ký tham dự Startup Demo Day FPT University','Ghi danh dự khán sự kiện Startup Demo Day để học hỏi cấu trúc thuyết trình, cách trả lời phản biện của các nhà sáng lập sinh viên trước hội đồng chuyên môn.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-022\"]','2026-09-05 08:20:23.000000'),('626b7161-3fe9-43c1-ba15-cd5a291fcffd','caf3d996-e763-4549-a003-987defd6ddf8',2,'Tập dượt và trình bày kết quả dự án cá nhân','Thực hành diễn đạt súc tích các ý tưởng then chốt và trả lời các câu hỏi phản biện liên quan đến sản phẩm.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:08:53.000000'),('62833e12-4855-4382-98cd-279e4c3a6e45','c1807478-4d11-4a2f-b3b5-6e3495550312',1,'Tìm hiểu mô hình Product Sprint và các vai trò trong dự án phần mềm','Nghiên cứu tài liệu nhập môn về Scrum/Agile và quy trình 5 bước phát triển sản phẩm để lập sơ đồ tóm tắt các vai trò chính trong đội ngũ công nghệ.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-011\"]','2026-09-05 10:14:56.000000'),('647dc329-d24b-4315-8817-2c7a2c4a4f15','530e5ddc-fa0c-4658-9236-738c2af334eb',2,'Xây dựng trang portfolio dự án và hoàn thiện tài liệu kỹ thuật (Mốc 80 ngày)','Tổng hợp video demo, hình ảnh giao diện, sơ đồ hệ thống và hướng dẫn cài đặt vào trang cá nhân chuyên nghiệp.',75,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-012\"]','2026-09-04 14:26:53.000000'),('64c872b7-a689-4bb6-8f42-c106e415b29e','f60922d5-3890-4ee7-9154-53a2cd5547fe',3,'Tổ chức thảo luận nhóm và thu thập phản hồi dự án (Mốc 60 ngày)','Chủ trì buổi trao đổi nhóm 45 phút để tiếp nhận ý kiến đóng góp từ các bạn cùng lớp và hoàn thiện sản phẩm truyền thông.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-013\"]','2026-09-05 07:49:00.000000'),('64f4f550-f388-480b-a855-0cc9744f0dd5','5eed8cfb-5532-4c18-bce7-5207bf99be5f',1,'Xây dựng sơ đồ phân tích vấn đề bài tập lớn','Sử dụng sơ đồ tư duy hoặc lưu đồ logic để bẻ nhỏ bài toán phức tạp thành các phần việc cụ thể.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-28 06:08:16.000000'),('6558748d-9500-5532-b1f6-5801b5f42ce9','7999cee7-84c2-5883-b9ab-f9594ca7ab97',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành An toàn thông tin và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"643bf908-b554-5abd-847c-4d323e93c99c\"]','2026-08-25 18:35:00.000000'),('659992d4-8345-4fa0-91f3-f47cf9149224','79547a5f-83d5-40ec-bbbc-d8a47fde3837',2,'Thực hiện phân tích cấu trúc trực quan của một sản phẩm công nghệ','Chọn một ứng dụng di động phổ biến và vẽ lại sơ đồ trải nghiệm người dùng, làm rõ bố cục không gian và luồng thao tác chính.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 03:35:52.000000'),('65bb0670-c358-4d34-aebc-8f30a2469ccc','371916ec-5a1b-4fb4-a252-0da69c907812',2,'Thiết kế slide thuyết trình cấu trúc logic','Soạn thảo bài thuyết trình 10 slide cho bài tập môn học với bố cục: Đặt vấn đề - Phân tích logic - Giải pháp thực tiễn - Đề xuất triển khai. Đầu ra là file slide thuyết trình hoàn chỉnh.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-04 16:07:41.000000'),('6671fd59-26c2-4290-9933-7bd76e9887da','d66cb80f-725a-4d6a-884a-43f733cf108b',1,'Lập kế hoạch tuần học tập và quản lý thời gian cá nhân','Thiết lập bảng theo dõi lịch học, tự học và sinh hoạt bằng công cụ số trong 45 phút, bảo đảm cân bằng việc học môn cơ sở ngành.',45,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\"]','2026-09-05 02:49:36.000000'),('669e3cd1-5190-4acf-bc55-5a68db8ef525','f32160ac-2713-4173-92b6-711e4c6f12cb',3,'Tổng kết 90 ngày và lập kế hoạch kỳ tiếp theo (Mốc 90 ngày)','Tự đánh giá theo các chỉ số tiến bộ, viết 3 bài học kinh nghiệm và đặt mục tiêu rèn luyện cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:23:47.000000'),('66f0e55e-e8d9-4d60-a004-7e667ae266ae','5d15a244-f1df-4baa-a3d0-4f3222c5a8a4',1,'Tổng hợp dữ liệu và viết báo cáo kết quả thử nghiệm dự án','Soạn thảo văn bản tổng kết các chỉ số đo lường hiệu năng của giải pháp, nêu bật tính ứng dụng thực tiễn trong 3 trang tài liệu.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-018\",\"evidence-029\"]','2026-08-29 06:55:48.000000'),('66fbf567-f1ca-44f0-afa2-1b7664a7a968','bcac4fd9-9dc0-4ce3-84b4-567946972391',1,'Tổng kết kết quả rèn luyện và xây dựng Portfolio học tập','Tập hợp các kết quả học tập, dự án thực hành và minh chứng kỹ năng đã tích lũy trong 60 ngày qua.',100,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-004\"]','2026-08-27 08:51:04.000000'),('67144082-4285-4e7c-923e-cd0131e17b66','5f7e1713-4d7b-4846-8cf4-c8974d0f77fe',3,'Tạo bản mẫu tương tác và thực hiện bài kiểm tra khả năng sử dụng','Nối các luồng liên kết màn hình động và quan sát 3 người dùng thao tác mẫu để ghi nhận các điểm nghẽn trải nghiệm.',90,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-017\"]','2026-09-03 14:02:44.000000'),('672f3a56-4a06-4273-8f24-803372263f58','5c9d0a05-bbe4-4f55-b6cd-99d6e235277b',2,'Lập trình mô-đun xử lý nghiệp vụ chính và viết mã kiểm thử','Viết mã nguồn cho chức năng lõi của ứng dụng, bổ sung ít nhất 3 kịch bản kiểm thử tự động để kiểm tra tính đúng đắn của dữ liệu đầu ra.',120,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\",\"evidence-005\"]','2026-09-04 15:00:27.000000'),('683873ea-c100-41c1-b0da-a69451c3ba35','6620d3bf-8691-44a9-9c24-495561b07902',3,'Điều phối buổi phản biện nội bộ và hoàn thiện báo cáo (Mốc 60 ngày)','Chủ trì buổi họp nhóm thử nghiệm thuyết trình, ghi nhận đóng góp và hiệu chỉnh tài liệu báo cáo dự án lần cuối.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:15:57.000000'),('685296c2-eaf4-414f-8240-f2bc04192323','264d84b9-3d5f-49fb-97c7-6f17dee3acb1',3,'Hoàn thiện sổ tay giải thuật toán và xử lý dữ liệu (Mốc 30 ngày)','Giải quyết 3 bài toán xử lý dữ liệu thực tế bằng Python, ghi lại mã nguồn và tài liệu giải thích logic từng bước có kiểm thử rõ ràng.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-006\",\"evidence-018\"]','2026-08-31 08:22:34.000000'),('685bf101-2679-59b9-9627-03cc350af2c3','6ffc820d-491c-5a5a-a0ae-de51a245c9be',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"5937634f-cb65-52ce-8c23-72aada489064\"]','2026-08-25 19:03:00.000000'),('69745c2f-bcfd-49f2-a880-487453dad6b2','6562ee9c-ff9f-435c-a1b9-8437a6855dee',1,'Khảo sát và lập bảng phân tích người dùng mục tiêu (User Persona)','Thực hiện phỏng vấn ngắn 3 bạn học cùng khóa để tìm hiểu nhu cầu quản lý thời gian học tập, tổng hợp thành 1 bản tóm tắt User Persona chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-015\"]','2026-08-30 06:57:48.000000'),('698fb0dd-e7a1-4214-afb4-0a535c474ef6','2754996d-6ebf-4d60-a666-68532bfe1791',1,'Lập khung phân tích yêu cầu người dùng cho dự án số','Thực hiện phỏng vấn thử nghiệm 2-3 bạn học về nhu cầu tiêu dùng và tổng hợp thành bản báo cáo phân tích 2 trang.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-015\"]','2026-09-03 14:02:44.000000'),('6a0ef5e2-d73a-4262-aaf9-e8a637c33c11','a6c50441-9d9f-4757-a7a9-91af98b27b02',3,'Ghi hình video thuyết minh sản phẩm và tổng kết bài học kinh nghiệm','Quay một đoạn video ngắn 5-7 phút giới thiệu tính năng sản phẩm, phân tích phương pháp giải quyết vấn đề và chia sẻ kinh nghiệm đã đúc kết được.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-012\"]','2026-09-04 15:00:27.000000'),('6a143595-0258-4cad-ace0-e81e3ec4a03b','53e265cc-4a04-4c30-b942-4a8f4e80c1ce',3,'Mốc 60 ngày: Rà soát mã nguồn chéo và đồng bộ mã nguồn nhóm','Thực hiện phiên phản biện mã nguồn (Code Review) cùng bạn học, tối ưu hóa các đoạn mã lặp và đóng gói mô-đun sẵn sàng cho giai đoạn hoàn thiện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\"]','2026-09-02 15:44:07.000000'),('6a64bf41-85fa-4ecc-80ac-e9860730072a','839d216c-f287-4e0f-b780-20a61d5961b3',2,'Xây dựng hồ sơ năng lực cá nhân trực tuyến (Mốc 80 ngày)','Thiết lập trang portfolio cá nhân dạng web tĩnh hoặc Notion page công khai, sắp xếp các sản phẩm học thuật một cách khoa học.',120,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-09-03 14:30:25.000000'),('6af26c06-035c-4461-92fb-9345212c75c2','786df7fd-ab49-43a5-9c4d-9c1c0b71502d',1,'Thành lập nhóm học tập và thảo luận ý tưởng đồ án (Mốc 40 ngày)','Chủ động kết nối với 2-3 bạn cùng lớp để chọn đề tài đồ án môn học hoặc bài tập sáng tạo, phân chia vai trò dựa trên thế mạnh từng người. Tiêu chí hoàn thành: Biên bản họp nhóm với mục tiêu rõ ràng và bảng phân công công việc cụ thể.',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:09:49.000000'),('6b3f5a43-4a1b-4932-901e-baf251980c34','de3171b5-a32d-455a-8cae-91c00760e503',2,'Phác thảo sơ đồ cấu trúc thông tin cho ý tưởng dự án cá nhân (Mốc 14 ngày)','Sử dụng công cụ sơ đồ tư duy để vẽ cấu trúc luồng người dùng và xác định các chức năng chính của sản phẩm học tập dự kiến triển khai.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-09-02 08:03:06.000000'),('6bbe6e48-4ec9-4452-9242-909f561e234d','0932d3f6-e190-4530-8324-595793ce686c',4,'Đánh giá tổng kết 90 ngày và lập kế hoạch học kỳ kế tiếp','Tự đánh giá mức độ tiến bộ kỹ năng chuyên môn, kỹ năng mềm và xác định 3 mục tiêu trọng tâm cho học kỳ sau trong 60 phút.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-012\",\"evidence-017\"]','2026-09-05 02:49:36.000000'),('6c4527b1-5574-44ef-9215-27d2cb9116a7','02fc279c-4625-41bd-ba0f-db58ade237af',3,'Tổng hợp bản đề cương dự án học tập mini (Mốc 30 ngày)','Viết tài liệu mô tả ý tưởng giải pháp số gồm mục tiêu, đối tượng sử dụng, tính năng chính và bảng kế hoạch thực hiện 4 tuần.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-020\"]','2026-09-05 03:54:44.000000'),('6ded18ec-ebaa-4628-b835-44bf930a9efd','664a65f9-c2a7-4fff-9ef8-d76ba8e02ed2',2,'Phân tích thời gian biểu và lịch học lớp 12 (Mốc ngày 14)','Thực hiện nhật ký theo dõi việc sử dụng thời gian học tập trong 1 tuần, sau đó phân bổ khung giờ cố định cho các môn trọng tâm và các hoạt động rèn luyện kỹ năng.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 14:38:51.000000'),('6ea73e41-e2f0-4ff1-81ee-00584932f224','eadaca9b-f2d1-43bd-8850-628621cc2b3f',2,'Biên soạn tài liệu Case Study chi tiết cho đồ án (Mốc 85 ngày)','Trình bày toàn bộ hành trình giải quyết vấn đề từ bối cảnh, giải pháp thiết kế, mã nguồn đến kiến trúc hệ thống thành một bài viết hoàn chỉnh.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-013\"]','2026-09-02 07:52:47.000000'),('6f1ba347-5c56-447d-9ee7-47e5fb5f4d09','f7a369a7-7220-43df-86ad-b32b56bc986b',1,'Chọn một vấn đề gần gũi','Mô tả người dùng, nhu cầu và kết quả mong đợi.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 05:08:36.000000'),('6f7dd00d-9e22-50f2-b48c-6d551f450350','6ffc820d-491c-5a5a-a0ae-de51a245c9be',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"bfe146ba-09db-5b2a-8589-c7df7ac2a57d\"]','2026-08-25 19:03:00.000000'),('6fa52c47-342f-431d-a132-a5083f94a3bc','1bc0dafa-a8f9-4696-a45c-07cb5e0bb970',3,'Thiết kế mô hình trực quan cho giải pháp của dự án nhóm','Sử dụng công cụ thiết kế để tạo sơ đồ giải pháp hoặc mô hình tương tác trực quan cho sản phẩm thuyết trình.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:15:08.000000'),('70077139-f235-4c24-9a3c-b97c8b9d6c9f','6c8bb01c-35c5-4f1e-965a-5e17638bc6bf',3,'Thực hiện buổi kiểm thử nội bộ và ghi nhận góp ý (Mốc 60 ngày)','Tổ chức phiên thử nghiệm 45 phút với 5 bạn học cùng lớp, quan sát thao tác và ghi chép danh sách cải tiến cần thiết.',75,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\"]','2026-09-05 03:54:44.000000'),('7067de61-aead-4fb6-8dae-fc17b8a30fe8','185d90aa-f4db-46f5-a267-e0cb6e47ca12',2,'Tổ chức phiên thảo luận nhóm để phân chia nhiệm vụ (Mốc ngày 45)','Chủ động thiết lập buổi họp nhóm 45 phút, lắng nghe ý kiến thành viên và lập bảng phân công công việc cụ thể trên bảng biểu số.',60,'self_task',NULL,NULL,'[\"evidence-012\",\"evidence-016\",\"evidence-017\"]','2026-08-29 06:59:25.000000'),('70ae25f4-26b4-457f-82a7-c7b1c89535eb','fbcdcfa3-a0a6-40d9-afcb-b5414a640aaf',3,'Hoàn thiện bản đồ kiến thức tổng hợp giai đoạn 1 (Mốc 30 ngày)','Tổng hợp toàn bộ nội dung đã học thành một trang infographic hoặc mindmap chi tiết, tự đánh giá mức độ hiểu bài đạt trên 80%.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:34:53.000000'),('70e0b987-c3ca-4ed6-925a-95565a365384','eabdb9ad-4f30-44bc-aaf5-e068038392d2',2,'Triển khai ứng dụng lên nền tảng đám mây miễn phí','Deploy ứng dụng web/API lên nền tảng Cloud (Render/Vercel), cấu hình biến môi trường an toàn và ghi nhận đường dẫn trực tuyến (Mốc 80 ngày).',100,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-038\"]','2026-09-05 05:50:04.000000'),('712a5e7a-43db-49e7-841f-b6b3476424e6','fbe0fc20-a7db-450f-91d4-0077293fec36',1,'Xác định bài toán thực tế cần giải quyết','Chọn một vấn đề cụ thể trong học tập hoặc công việc hàng ngày và phác thảo giải pháp khả thi.',75,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-24 15:40:29.000000'),('7146a8ee-a87a-457a-b52e-e60b5e0254a4','9cba4dc2-dd9a-4453-baae-1f5db58d4515',4,'Kiểm thử và tối ưu hóa module tính năng chính','Viết kịch bản kiểm thử cho 3 chức năng trọng tâm của ứng dụng và ghi nhận kết quả kiểm thử trong 60 phút.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 02:49:36.000000'),('71a459f9-e37d-473e-890d-2b38faff518b','7365eb8a-ae89-4e9a-8676-76aa739fb494',3,'Tổng kết nhật ký học tập và kỹ năng đầu kỳ (Mốc 30 ngày)','Viết bài thu hoạch 1 trang tổng kết các kiến thức nhập môn đã học, tự đánh giá mức độ tiến bộ so với mục tiêu ban đầu.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-014\",\"evidence-016\"]','2026-09-05 07:49:00.000000'),('72845ac5-db9c-46b9-b302-1af84bad817f','f9b3d0ce-b031-4d26-b8f3-6f13ba9eb20f',2,'Tổ chức buổi thảo luận nhóm 3 người để kiểm thử trải nghiệm (Mốc 45 ngày)','Chuẩn bị kịch bản thử nghiệm ngắn, điều phối buổi trao đổi trong 45 phút với bạn cùng lớp để ghi nhận trải nghiệm thực tế và các lỗi giao diện.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:59:22.000000'),('72d7ed3c-6b75-443d-8bc8-2194f4e9762e','a632f50e-8013-4a9b-8e59-9b7215b9ce57',1,'Tổng hợp số liệu và phân tích kết quả thử nghiệm dự án (Mốc 75 ngày)','Thực hiện thống kê mức độ hài lòng, thời gian hoàn thành tác vụ của người dùng trên bản mẫu và lập biểu đồ trực quan hóa dữ liệu.',90,'self_task',NULL,NULL,'[\"evidence-018\",\"evidence-027\"]','2026-08-31 15:59:36.000000'),('72f8dac0-8e7f-4a00-87b1-6f1b32095abd','8a1de756-43cd-45d5-8aac-5a270a7d748a',1,'Hoàn thiện đầu ra','Tổng hợp phiên bản tốt nhất cùng bằng chứng tiến bộ.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 05:08:36.000000'),('736ea43e-f968-4b09-8ac0-8632c148384d','16644473-7970-435c-8d3d-2924b751067e',1,'Chọn phản hồi ưu tiên','Phân loại phản hồi và chọn một thay đổi quan trọng.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-25 14:17:14.000000'),('738f5307-ae3a-46ce-b9e5-7933d13cfc3c','94dc5d45-ed95-4cea-bc9c-b4b8090d0154',1,'Kiểm thử trải nghiệm và thu thập phản hồi người dùng (Mốc ngày 70)','Mời 4 bạn học trải nghiệm thử bản mẫu, ghi nhận ít nhất 5 điểm cần cải tiến và tối ưu lại độ mượt mà của giao diện.',60,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-010\",\"evidence-014\"]','2026-08-29 06:59:25.000000'),('739dd3e1-f05f-4460-b20a-adff2d9fd3aa','dc95f4e8-67df-4ef5-b3ed-8e898c353b80',2,'Xây dựng chiến lược ôn thi nước rút cho lớp 12','Phân bổ thời gian ôn tập chi tiết cho từng giai đoạn nhỏ, chú trọng các nội dung cần cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 09:02:35.000000'),('73a06061-8aef-4abf-b096-a7c1eabc099b','12fe5a17-d2b7-4345-91c7-c66ce886329b',3,'Tổng kết hồ sơ năng lực học tập và định hướng tương lai (Mốc 90 ngày)','Hệ thống hóa toàn bộ các dự án, chứng nhận hoạt động và bài tập lớn thành một hồ sơ học tập (portfolio) số sẵn sàng cho việc chọn ngành đại học.',90,'self_task',NULL,NULL,'[\"evidence-020\",\"evidence-021\",\"evidence-027\"]','2026-08-31 08:22:34.000000'),('74220108-438a-48fd-b64e-cbfa7e9db767','4d765328-2862-4931-8dd0-314878a40702',2,'Soạn thảo tài liệu mô tả tính năng cho một ý tưởng số','Thực hiện viết tài liệu tóm tắt mục tiêu, chân dung người dùng và 3 chức năng chính cho giải pháp công nghệ đã chọn.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\"]','2026-09-05 03:19:52.000000'),('74a6ceb7-1f85-4955-a8b5-856371ee9e83','a1f141bf-108c-44d2-abc5-23b0ac7de6e7',1,'Xây dựng bộ giao diện tương tác hoàn chỉnh có thể thao tác (Mốc 45 ngày)','Thiết kế tối thiểu 5 màn hình chính của giải pháp số trên công cụ thiết kế chuyên dụng với hệ thống màu sắc và bố cục nhất quán.',120,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-018\"]','2026-09-02 07:52:47.000000'),('74d4d595-2e5b-4f10-8351-510ece7f2a89','b7713564-b690-4a97-b6fd-c33f3d0ef4af',3,'Hoàn thiện bảng mục tiêu học tập tháng đầu tiên','Viết rõ 3 mục tiêu cụ thể cần đạt trong tháng về điểm số chuyên cần và kết quả bài tập nhỏ, đính kèm tiêu chí tự kiểm tra mỗi cuối tuần.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 07:43:33.000000'),('74f671eb-044c-566b-977d-987d4360bfdc','d8983f7c-e675-5420-8f55-ff354743b56c',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành An toàn thông tin và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"]','2026-08-25 18:35:00.000000'),('75019af8-d365-49c6-aae5-bab1d3ea3285','8afe7a57-4e83-4ecf-a593-b814f0eec2c3',2,'Xây dựng khung theo dõi mục tiêu học tập lớp 12','Lập bảng kế hoạch học tập theo tuần, phân bổ thời gian cụ thể cho từng môn học trọng tâm và các mục tiêu ôn luyện cá nhân.',90,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-27 09:46:18.000000'),('75514de8-d6a6-4a24-adf6-17ffe71e2c4c','5d15a244-f1df-4baa-a3d0-4f3222c5a8a4',3,'Thực hành thuyết trình giải pháp và tiếp nhận phản hồi đóng góp','Thực hiện buổi thuyết trình thử nghiệm 10 phút về đồ án trước nhóm bạn học, ghi chép lại các góp ý để tinh chỉnh sản phẩm cuối kỳ.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-015\",\"evidence-016\"]','2026-08-29 06:55:48.000000'),('75572c15-751c-4af4-aa96-dae3c4ad0b0c','caa938bc-5b48-4fa9-868e-1d1de3083a06',3,'Mốc ngày 90: Đóng gói bài học kinh nghiệm và cập nhật Portfolio cá nhân','Viết bài thu hoạch 500 từ tổng kết kỹ năng đã phát triển, lưu trữ sản phẩm và minh chứng vào kho học liệu cá nhân trực tuyến.',80,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\",\"evidence-004\"]','2026-08-30 07:10:06.000000'),('75bcc774-d575-53b7-a73a-645707515fa3','2a5fa512-ae9b-5ff8-a4dc-5e23d484ef69',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"5d430ff3-d899-5704-9407-aa82f06eca77\"]','2026-08-25 18:14:00.000000'),('761172b6-6d1d-45cd-a246-86e0fa2725cc','6620d3bf-8691-44a9-9c24-495561b07902',1,'Khảo sát thực trạng và định hình bài toán nhóm (Mốc 40 ngày)','Cùng nhóm học tập thảo luận, phỏng vấn nhanh 5 sinh viên khác để xác định một vấn đề thực tế trong môi trường học đường cần cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:15:57.000000'),('76fa3b9e-6a35-4f29-be15-9e500f0e626a','360aa0a7-4a60-47a8-9f93-ade52750f15c',2,'Lập trình chức năng xử lý dữ liệu và xây dựng API','Viết mã nguồn xử lý logic phía máy chủ kết nối với cơ sở dữ liệu, đảm bảo bảo mật đầu vào và trả về phản hồi định dạng JSON chuẩn (hoàn thành trước mốc 50 ngày).',120,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-024\"]','2026-09-05 09:58:29.000000'),('7724e38c-348d-41c1-877b-7a999e33a4b6','a6370bba-24f5-44f4-8f75-c1a12c9ea2e9',2,'Tham gia hoạt động trải nghiệm ứng dụng công nghệ tại AI Hacklab','Đăng ký tham dự chương trình AI Hacklab tại Innovation Lab FPT để quan sát cách ứng dụng công nghệ giải quyết bài toán thực tế.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-018\"]','2026-09-05 03:19:52.000000'),('7740a008-5556-46b7-8d3e-109434cde657','d931ff41-05f7-403b-bf98-8bc5ce4eaffe',3,'Điều phối buổi phản biện nội bộ và hoàn thiện báo cáo (Mốc 60 ngày)','Chủ trì buổi họp nhóm thử nghiệm thuyết trình, ghi nhận đóng góp và hiệu chỉnh tài liệu báo cáo dự án lần cuối.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:59:48.000000'),('778d9052-4fe0-4ed3-acab-d2010b8cddea','44f359da-2def-41a8-9db0-19840582dd5d',2,'Khảo sát và đối chiếu tiêu chuẩn các ngành học sáng tạo - công nghệ','Tìm hiểu chương trình đào tạo, yêu cầu đầu vào và cơ hội phát triển của các ngành thuộc lĩnh vực thiết kế ứng dụng và quản trị dự án.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 10:39:35.000000'),('77a1e04f-cd68-448c-9e7f-f7ceedbafba6','b7713564-b690-4a97-b6fd-c33f3d0ef4af',1,'Lập thời gian biểu cá nhân và phân bổ lịch học','Thực hiện phân tích thời khóa biểu môn học trên trường, liệt kê các khung giờ tự học cố định từ 45-60 phút mỗi ngày và thiết lập bảng theo dõi tiến độ học tập tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-28 07:43:33.000000'),('77eaca14-7c28-46f1-888b-db5a836d8954','a6370bba-24f5-44f4-8f75-c1a12c9ea2e9',1,'Lập kế hoạch mục tiêu học tập và rèn luyện 90 ngày','Vạch ra mục tiêu cá nhân theo từng tuần, phân bổ thời gian tự học từ 45-60 phút mỗi buổi để bảo đảm cân bằng với lịch học chính khóa Năm 1.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-012\"]','2026-09-05 03:19:52.000000'),('7825b347-d11e-46fa-9022-680fc410ea1e','19ba47ee-105d-4701-abbe-ad4cdde0bab1',1,'Xác định đề tài và phỏng vấn nhu cầu học tập (Mốc ngày 7)','Lựa chọn một vấn đề thực tế trong trường học, tiến hành khảo sát nhanh với 3 bạn học cùng lớp để lập bảng tổng hợp khó khăn và nhu cầu sử dụng ứng dụng.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-015\"]','2026-08-29 06:59:25.000000'),('78629635-ec46-436f-9987-1b8ed252993e','ebc97266-1916-4647-8128-369d6883ca37',1,'Biên tập nội dung hồ sơ học tập cá nhân (Mốc 75 ngày)','Lựa chọn 2 bài tập hoặc sản phẩm tiêu biểu trong kỳ học, viết bài phân tích quá trình thực hiện và kết quả đạt được.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-02 14:15:57.000000'),('7885baa7-732c-4b36-8cdb-bdebea5edcf8','4367aee4-74d0-40b0-a948-36ad425cf7df',2,'Xây dựng sơ đồ trực quan hóa vấn đề nghiên cứu (Mốc 14 ngày)','Sử dụng công cụ vẽ sơ đồ trực tuyến để hệ thống hóa bối cảnh, đối tượng người dùng và các điểm nghẽn của đề tài đã chọn thành một bản đồ tư duy trực quan.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-30 07:59:22.000000'),('7942c263-5e04-4f70-980c-c6dbf956454a','171dda5b-7e4f-47b8-a4ef-5eb2f3d73c92',2,'Thu thập phản hồi đánh giá và hiệu chỉnh giao diện sản phẩm','Xin ý kiến đóng góp từ giảng viên hướng dẫn hoặc anh chị khóa trên để tối ưu các chỉ số hiển thị và tính logic trong bài thuyết minh đồ án.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-029\"]','2026-08-30 06:57:48.000000'),('7a249827-5bcd-47fc-9a1b-a35ca79921e6','79547a5f-83d5-40ec-bbbc-d8a47fde3837',3,'Xây dựng khung theo dõi tiến độ học tập cá nhân','Thiết lập bảng theo dõi mục tiêu học tập tuần với các tiêu chí đo lường rõ ràng nhằm tối ưu hóa phong cách hành động quyết đoán.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 03:35:52.000000'),('7a4687c4-eb7a-4844-b481-71eb0316ea8f','eb4fe206-94a7-4a24-ac46-083ea23445dd',2,'Thực hành ghi nhận phản hồi và thích ứng linh hoạt','Ghi chép lại các ý kiến đóng góp từ bạn bè, thầy cô và điều chỉnh phương pháp học cho phù hợp.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 09:02:35.000000'),('7a7c7bf2-5bf1-461d-830c-08162b0ff5cd','5ae07e3b-d682-4615-9454-6f38bfa33e63',3,'Xây dựng bảng mục tiêu học tập cá nhân cho học kỳ','Lập kế hoạch phân bổ thời gian giữa học tập chuyên ngành và tự học kỹ năng phân tích thiết kế theo từng tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:09:11.000000'),('7a8827fb-da72-41d5-80a1-01097515e775','d450b365-399d-4641-8033-1a3f4a0257b3',1,'Soạn thảo bài trình bày nghiên cứu tình huống dự án','Viết bài phân tích quá trình từ khảo sát bài toán, giải pháp thiết kế đến kết quả đạt được dưới dạng slide 10 trang.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-018\"]','2026-09-03 14:02:44.000000'),('7ade04fc-294b-402c-aea0-3ad0e38af603','ed6446ed-1aa2-4583-b3f3-d337047e57cc',1,'Mốc Ngày 45: Lập trình mô-đun xử lý nghiệp vụ chính','Viết mã nguồn xử lý logic nghiệp vụ chính của ứng dụng, bổ sung cơ chế xác thực và mã hóa an toàn. Tiêu chí hoàn thành: Các luồng nghiệp vụ chạy thông suốt, dữ liệu lưu trữ chính xác vào cơ sở dữ liệu.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\",\"evidence-024\"]','2026-09-05 05:33:43.000000'),('7b09c19e-c75b-4990-b9ed-441728cd6e58','5fa2c9de-a024-4c20-a315-2ed76f92c0c1',2,'Lập sơ đồ tư duy phân tích 3 thuật toán nền tảng','Vẽ sơ đồ giải thuật cho các bài toán tìm kiếm và sắp xếp dữ liệu, ghi chú chi tiết các bước xử lý logic và điều kiện dừng trước khi viết mã.',90,'self_task',NULL,NULL,'[\"evidence-005\",\"evidence-007\"]','2026-09-04 15:00:27.000000'),('7b44e28f-921d-5a71-9d5d-b86f99613c85','18c12df8-cc17-5db3-b20d-a40d9a4d4f14',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"4989f77d-56b8-5a4f-843e-1dc05ffa8317\"]','2026-08-25 18:56:00.000000'),('7b77c4a1-7a44-40f3-86a4-4ee9f27d0294','94dc5d45-ed95-4cea-bc9c-b4b8090d0154',2,'Biên soạn báo cáo kỹ thuật và tài liệu thuyết trình (Mốc ngày 80)','Tổng hợp sơ đồ kiến trúc, logic xử lý và kết quả kiểm thử thành một bài trình chiếu 10 trang mạch lạc, chuẩn mực.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-015\",\"evidence-029\"]','2026-08-29 06:59:25.000000'),('7bbc78e7-32d7-4cc4-994a-56712e53869b','eadaca9b-f2d1-43bd-8850-628621cc2b3f',1,'Tổng hợp số liệu và phân tích kết quả thử nghiệm dự án (Mốc 75 ngày)','Thống kê mức độ hài lòng, thời gian hoàn thành tác vụ của người dùng trên bản mẫu và lập biểu đồ trực quan hóa dữ liệu thu được.',90,'self_task',NULL,NULL,'[\"evidence-018\",\"evidence-027\"]','2026-09-02 07:52:47.000000'),('7bf6ad9e-7e71-4e38-b617-a0e7a699ea88','ca952e6f-76f6-4bbe-b11c-9b5157a1251f',2,'Thiết kế bộ trình bày giải pháp học tập cá nhân','Tạo slide thuyết trình từ 7-10 trang tổng kết lại toàn bộ kết quả thử nghiệm và bài học rút ra trong suốt 60 ngày trước.',90,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-022\"]','2026-09-05 03:19:52.000000'),('7c6959f1-2120-4174-a042-7e70f0d622a8','a1f141bf-108c-44d2-abc5-23b0ac7de6e7',3,'Tổ chức phiên phản biện chéo và ghi nhận đóng góp cải tiến (Mốc 60 ngày)','Thu thập ý kiến đóng góp từ 3 bạn học hoặc giảng viên hướng dẫn về nguyên mẫu đã hoàn thành, sau đó tổng hợp thành danh sách các điểm cần cải tiến.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-015\",\"evidence-017\"]','2026-09-02 07:52:47.000000'),('7c8afcfa-076b-4d68-98ec-e8819ee72262','4886d51a-3099-4264-9a54-bbb54b0012eb',2,'Luyện tập kỹ năng thuyết trình giải pháp','Soạn slide tóm tắt giải pháp trong 5 phút và tự ghi hình để điều chỉnh ngữ điệu, cử chỉ và tính thuyết phục.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:09:11.000000'),('7ce5405d-feb3-4e2d-abc1-c2997444179c','0c7f33e4-a21c-4947-b6ab-0dbd25544788',2,'Đăng ký tham gia workshop Product Sprint trải nghiệm sản phẩm số (Mốc 14 ngày)','Đăng ký tham gia hoạt động Product Sprint tại Product Lab FPT để tiếp cận quy trình xây dựng sản phẩm thực tế từ chuyên gia.',45,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-037\"]','2026-08-31 04:21:44.000000'),('7d7875ef-9300-4ace-ae74-f702cedc078b','3b080d9f-bba3-4e2c-a03d-d40684b897d9',1,'Thực hiện khảo sát nhỏ về nhu cầu học tập tại trường','Thiết kế biểu mẫu khảo sát, thu thập ý kiến bạn bè và sử dụng công cụ bảng tính để phân tích số liệu.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 08:51:04.000000'),('7d83faec-268e-400f-9330-2bf54281ba3c','584a8151-2de8-46ad-bb69-866bcc7c3eea',1,'Tối ưu hóa hiệu năng và rà soát bảo mật mã nguồn (Mốc 70 ngày)','Bắt đầu bằng việc quét mã nguồn bằng công cụ phân tích tĩnh, xử lý các cảnh báo bảo mật và tối ưu tốc độ xử lý của ứng dụng.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-012\"]','2026-09-04 15:03:37.000000'),('7db83ef7-b58c-4856-8ad0-c39e719ad1df','47474713-b413-4ebe-bb11-7be0181a8e15',1,'Thiết lập hệ thống quản lý học tập cá nhân (Mốc 7 ngày)','Bắt đầu tạo bảng quản lý công việc trên Notion hoặc Trello, phân chia môn học thành các chuyên mục rõ ràng và lên lịch cố định cho việc ôn tập.',60,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-09-03 14:30:25.000000'),('7ecf641b-3f7f-4343-9142-9322a43bb697','a1f141bf-108c-44d2-abc5-23b0ac7de6e7',2,'Đăng ký tham gia hoạt động Product Sprint để hoàn thiện quy trình sản phẩm (Mốc 50 ngày)','Ghi danh tham gia chương trình Product Sprint tại Product Lab FPT để trải nghiệm phương pháp phát triển sản phẩm theo chu trình lặp nhanh.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-038\"]','2026-09-02 07:52:47.000000'),('7f2f6c70-8de0-4e98-a507-9f19d99eb16b','5dbd4c3b-5abc-4d23-aeed-e04282ba54c9',3,'Phỏng vấn tiền bối hoặc giảng viên cố vấn','Tham vấn ý kiến của giảng viên hoặc sinh viên khóa trên về các môn học chuyên ngành và định hướng dự án sắp tới.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-26 05:15:08.000000'),('7f9fdc63-fbc7-4de1-9e1c-c2955167e40c','690c02ca-beb6-4eb4-9ff1-ec81189c47f6',2,'Đóng gói ứng dụng và cấu hình tự động hóa triển khai cơ bản (Mốc 85 ngày)','Tạo tệp cấu hình container (hoặc kịch bản triển khai dịch vụ đám mây miễn phí) để đưa sản phẩm lên môi trường trực tuyến có thể truy cập công khai.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-024\"]','2026-09-05 05:53:02.000000'),('7ff824db-c8a9-5770-95a8-31e0a1a6f858','b21064de-557b-5d6d-91ba-c268dccb415b',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Chuyên viên phân tích dữ liệu và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"2ed69cba-f563-5108-9703-284daa915c5e\"]','2026-08-25 18:21:00.000000'),('8025ce5a-5fa7-462b-a28a-f82b7cdf1c77','e5d72e6a-4c4a-4b0a-a459-a36b68913927',2,'Thu thập và phân tích tài liệu chuyên khảo nhập môn (Mốc 14 ngày)','Tìm kiếm và đọc 3 bài viết học thuật hoặc tài liệu ngành, ghi chú lại 5 khái niệm cốt lõi theo dạng sơ đồ tư duy trực quan.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:23:47.000000'),('805b4c7f-9754-42c5-8fa5-d49e212fc389','8203f8c5-9654-440b-aa8d-838fc366bf25',3,'Xuất bản trang Portfolio cá nhân và chuẩn bị hồ sơ ứng tuyển (Mốc 90 ngày)','Đưa sản phẩm lên trang cá nhân trực tuyến, cập nhật các minh chứng kỹ năng đã xác thực để sẵn sàng cho các chương trình thực tập sinh viên.',90,'self_task',NULL,NULL,'[\"evidence-016\",\"evidence-020\",\"evidence-025\",\"evidence-043\"]','2026-08-30 17:02:18.000000'),('80da02e7-c35a-4201-a722-e477776bf039','e4f72bc1-3839-48dd-b86c-1fddadfd0396',3,'Thực hành viết bài phân tích quan điểm ngắn','Soạn thảo bài viết ngắn khoảng 500 từ về một chủ đề xã hội hoặc học thuật để rèn luyện cấu trúc lập luận mạch lạc.',75,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-27 09:09:29.000000'),('815cc0bf-c78a-4e0a-ac99-a2d81030c328','eb4fe206-94a7-4a24-ac46-083ea23445dd',1,'Chủ trì buổi thảo luận giải bài tập chuyên sâu','Điều phối buổi học nhóm, phân chia phần việc và tổng hợp các giải pháp hiệu quả cho cả nhóm.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-27 09:02:35.000000'),('81abc06d-9f84-4b69-aa11-f50316c4ae46','cf77d74f-f57f-4df9-b594-2f36aeb1038a',1,'Mốc ngày 40: Tổ chức buổi thảo luận và phân công nhiệm vụ nhóm','Lập kế hoạch làm việc nhóm 3-4 thành viên, phác thảo ma trận trách nhiệm và thống nhất mục tiêu đầu ra cho bài tập lớn.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:10:06.000000'),('81e68a9f-e3bc-4f17-92d8-39cd02f3ecbb','9a464336-3c56-4344-9a4a-26215f5e5656',3,'Xây dựng slide thuyết trình và thực hành chia sẻ kỹ thuật','Biên soạn slide trình bày giải pháp kỹ thuật, điểm nổi bật của dự án và trình bày thử nghiệm trước nhóm bạn học để nhận phản hồi; tiêu chí hoàn thành là bộ slide hoàn chỉnh và biên bản ghi nhận góp ý phản biện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\"]','2026-09-05 09:46:28.000000'),('81eb734d-0d73-47fd-a0d5-ad831854e207','839d216c-f287-4e0f-b780-20a61d5961b3',1,'Tuyển chọn và biên tập bài học kinh nghiệm (Mốc 70 ngày)','Chọn lọc 2 dự án học phần đạt kết quả tốt nhất, viết bản tóm tắt mô tả bối cảnh, vai trò đóng góp và bài học đúc kết được.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-03 14:30:25.000000'),('8234ef51-33f5-4222-bdc4-aa5c86d56d56','7f6856fe-b940-4f8e-9f4e-a906c3e0562b',1,'Thiết kế bảng câu hỏi khảo sát học tập','Xây dựng bộ câu hỏi thu thập ý kiến về thói quen học tập và ứng dụng công nghệ trong học sinh lớp 12.',90,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-27 09:46:18.000000'),('829314b9-7833-42f6-a0de-0e4fe567ee90','f4c407ff-7dc9-472c-ba65-deab159c356f',2,'Phác thảo sơ đồ giải pháp kỹ thuật sáng tạo cho dự án học tập (Mốc 50 ngày)','Thực hiện buổi động não cùng 2 bạn học để thiết kế sơ đồ luồng dữ liệu cho một ứng dụng hỗ trợ học tập lớp 12, đề xuất ít nhất 2 tính năng mới mẻ.',75,'self_task',NULL,NULL,'[\"evidence-012\",\"evidence-013\",\"evidence-016\"]','2026-08-31 08:22:34.000000'),('8375b539-89e3-4af1-b7fd-7c5db034cc49','e7b70721-8423-434b-9765-8236b8dc3718',2,'Tham dự ngày hội kết nối và trình diễn ý tưởng (Mốc 85 ngày)','Đăng ký tham gia Startup Demo Day để giao lưu, học hỏi kỹ năng pitching và nhận xét từ các dự án sinh viên nổi bật.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-022\"]','2026-09-05 03:54:44.000000'),('847bd00c-6737-4085-8b2a-3f2224958b27','699286a4-e746-445e-a882-57cb48a429b7',1,'Tổng hợp và phân tích 03 sản phẩm số tiêu biểu (Mốc 7 ngày)','Lựa chọn 03 ứng dụng di động phổ biến, lập bảng đối chiếu ưu - nhược điểm về giao diện người dùng và lưu trữ thành tài liệu ghi chép cá nhân.',60,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-08-29 06:44:00.000000'),('84850f1a-63f1-465a-ae34-06e67c674c75','d332fa6e-085c-4c8f-8019-383be4e84bcb',3,'Nhận phản hồi và cải tiến (Mốc 60 ngày)','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"c6c194fc-96f3-5783-8c4a-b8a927485a3e\"]','2026-09-02 14:19:37.000000'),('8488f869-f152-40ec-afff-eb5699c4bf30','953ac3ad-b090-4610-8f9b-78ffc14300e8',1,'Tổng hợp và phân tích hồ sơ ngành nghề liên quan','Lập danh sách các chương trình đào tạo đại học thuộc nhóm ngành Quản lý Hệ thống, Y tế công cộng và Công nghệ giáo dục.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 08:51:04.000000'),('84d78a6b-e59f-4f96-afd0-7288ad303be6','02ef1cd1-76e8-47cd-a6c4-c4e65046340e',2,'Phân tích và lựa chọn ngăn xếp công nghệ cho dự án mẫu (Mốc 14 ngày)','Nghiên cứu tài liệu kỹ thuật, so sánh 2 bộ công nghệ phổ biến và lập bảng đánh giá ngắn để chọn ra ngăn xếp phù hợp với bài tập lớn.',75,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-04 14:26:53.000000'),('855a48df-4acd-4eb3-b9a9-3968bf1c0df5','9b9397de-d562-4ca9-bb26-fea647cfe053',3,'Thiết kế và hoàn thiện bộ khung giao diện tương tác (Wireframe)','Sử dụng công cụ thiết kế để tạo ít nhất 5 màn hình tương tác chính cho đồ án nhóm, thu thập phản hồi từ giảng viên hoặc bạn học.',120,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\"]','2026-08-29 06:55:48.000000'),('85606bbb-761b-455b-9102-dde2fea77630','ae0b874e-0652-40cb-8060-484156e64b9f',3,'Tổng hợp bài thu hoạch trực quan từ 3 tài liệu tham khảo','Đọc và trích xuất các ý chính từ 3 bài báo khoa học hoặc tài liệu chuyên ngành, trình bày lại dưới dạng infographic tóm tắt 1 trang.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:17:58.000000'),('859ecf20-f325-4c4e-b0c6-99d78b2d7448','22e36f00-f43f-49ec-86b4-a4ae49e03fdd',3,'Mốc ngày 90: Diễn tập thuyết trình dự án và lập kế hoạch thực tập','Thực hiện buổi thuyết trình thử nghiệm 15 phút trước bạn bè hoặc giảng viên hướng dẫn, ghi nhận nhận xét để tinh chỉnh định hướng tiếp theo.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-015\",\"evidence-016\"]','2026-08-29 06:50:07.000000'),('85cfb9ca-06ec-4d38-a1b2-904e0970678c','d450b365-399d-4641-8033-1a3f4a0257b3',2,'Luyện tập thuyết trình và phản biện giải pháp','Tập dượt bài báo cáo 10 phút trước các bạn trong nhóm, thu thập 3 ý kiến đóng góp để hoàn thiện kỹ năng ứng biến.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-09-03 14:02:44.000000'),('85f2c927-6a48-4d6b-940d-9d54b615053c','2e962488-04a3-47a7-9667-37a1ebb8a6b3',1,'Đăng ký tham gia chương trình Product Sprint xây dựng sản phẩm số','Ghi danh tham gia hoạt động trải nghiệm tại Product Lab để nắm bắt quy trình làm việc nhóm thực tế và áp dụng tư duy phát triển sản phẩm công nghệ.',60,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-031\"]','2026-08-29 06:39:46.000000'),('8715f6ad-3c89-491e-b9ce-85dde15d7c60','5ea93051-aac9-4cb5-ba36-f43c59f63328',3,'Tập hợp tài liệu và mô hình hóa ý tưởng','Vẽ sơ đồ tư duy liên kết kiến thức toán học và công nghệ vào một vấn đề thực tế quen thuộc.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 02:38:47.000000'),('8747f633-1f5a-45dc-81ec-1aa92e009ab8','6620d3bf-8691-44a9-9c24-495561b07902',2,'Phát thảo mô hình giải pháp dạng trực quan (Mốc 50 ngày)','Sử dụng công cụ thiết kế cơ bản để vẽ wireframe hoặc sơ đồ quy trình giải quyết vấn đề đã khảo sát.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:15:57.000000'),('8793cc40-e72b-4e55-a389-2f7f29647514','b9b16f87-3990-4305-93db-3ba64740b44c',2,'Thiết lập mục tiêu SMART (Mốc 30 ngày)','Xây dựng mục tiêu 90 ngày gắn với định hướng Kỹ sư an toàn thông tin.',75,'self_task',NULL,NULL,'[\"643bf908-b554-5abd-847c-4d323e93c99c\"]','2026-09-02 14:19:37.000000'),('87bcd837-eed8-50b8-a45b-b7ac8a9b47c0','00eeab3f-6b43-5c95-82eb-e4db1aed3acb',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"2ed69cba-f563-5108-9703-284daa915c5e\"]','2026-08-25 18:21:00.000000'),('87ebc36f-d8e5-42ac-a57e-8077015a05dd','52b33b60-0bac-43bc-9ae4-05cc9c1d78e6',4,'Thực hành diễn tập thuyết trình và hoàn thiện hồ sơ học tập','Tự ghi hình hoặc diễn tập thuyết trình trong 7 phút, rà soát lại toàn bộ tài liệu minh chứng để cập nhật vào hồ sơ năng lực cá nhân. Đầu ra là bản checklist hoàn thành toàn bộ mục tiêu 90 ngày.',60,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-020\",\"evidence-026\"]','2026-08-30 06:51:26.000000'),('8831f414-4f48-46c9-9cd6-5f5727dbbfab','ccf6f9d9-c863-4fa7-b72f-1619f5935f98',3,'Cập nhật hồ sơ học tập và tìm kiếm cơ hội thực tập sớm (Mốc 90 ngày)','Đồng bộ sản phẩm vào hồ sơ năng lực cá nhân, đối chiếu các yêu cầu tuyển dụng thực tập sinh thiết kế để lập mục tiêu cho kỳ tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-020\",\"evidence-036\"]','2026-08-29 06:44:00.000000'),('8838fc62-4ea6-4265-a370-8c3ee5af9677','a8bfbfd4-92b2-49c6-a365-8a95b1a2eb67',2,'Xây dựng khung theo dõi tiến độ cá nhân','Thiết lập bảng theo dõi nhiệm vụ học tập theo mức độ ưu tiên và thời hạn cụ thể trên công cụ quản lý số.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:15:08.000000'),('884a2d72-c862-412d-a41d-4a59cd53bbb6','fa09eeb0-a584-46e9-9223-78b92d6e99df',3,'Tổng hợp và trình bày báo cáo phân tích trải nghiệm người dùng đầu tiên','Hoàn thiện bản báo cáo UX Audit định dạng PDF gồm phân tích vấn đề, giải pháp đề xuất và slide tóm tắt 5 trang để luyện tập kỹ năng trình bày logic.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-006\",\"evidence-015\"]','2026-08-29 06:39:46.000000'),('88c667d9-1e4f-4b28-8e83-566aa506ba53','c0ed31aa-73f0-44dc-a302-6b6a53b4fe26',1,'Xây dựng đề cương dự án sáng kiến học đường','Phác thảo cấu trúc bài thuyết trình về một giải pháp ứng dụng công nghệ hoặc môi trường xanh trong khuôn viên trường THPT Nguyễn Trãi.',75,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-010\"]','2026-09-05 07:49:00.000000'),('88d59f37-a6b1-5f62-b331-7ecb90356efa','00eeab3f-6b43-5c95-82eb-e4db1aed3acb',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"ac6912c8-4e65-5e98-b67d-e3f76f3ff3ed\"]','2026-08-25 18:21:00.000000'),('88e5f973-cfce-4e70-a69a-6ed74d381ed9','c664f29e-520b-4182-b86b-2eae53ebcf6d',2,'Mô hình hóa kiến thức môn học bằng sơ đồ trực quan (Mốc 14 ngày)','Đọc giáo trình một môn chuyên ngành, chọn một chương cốt lõi và vẽ sơ đồ khái niệm trực quan liên kết các định nghĩa và công thức chính. Đầu ra là 1 bản mindmap chuẩn hóa.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-04 16:07:41.000000'),('88ebca4d-e089-45b0-a919-208b334e89fd','75710fe4-b8a7-42f1-85d9-3a41585991f0',2,'Tham dự sự kiện Startup Demo Day để học hỏi kinh nghiệm thực tế','Tham gia ngày hội khởi nghiệp để theo dõi cách các đội thi thuyết minh sản phẩm và ghi nhận bài học cải thiện cho bản thân.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-011\",\"evidence-022\"]','2026-09-05 10:14:56.000000'),('8933dc4f-4306-41a8-a8d2-5e80cf35f60e','c0ed31aa-73f0-44dc-a302-6b6a53b4fe26',2,'Tham gia hoạt động Hùng biện Ý tưởng Khởi nghiệp Trẻ','Tham dự sự kiện tại Hội trường B để rèn luyện sự tự tin, kỹ năng phản xạ và trình bày giải pháp trước đám đông.',120,'register_activity','activity','31000000-0000-4000-8000-000000000008','[\"evidence-010\",\"evidence-020\"]','2026-09-05 07:49:00.000000'),('898d1e74-6b58-42a4-9145-ee5d759ab68a','b3c0872e-ca09-4784-8dd8-01fbe91c94ae',3,'Hoàn thiện báo cáo phân tích tương tác và đề xuất tối ưu (Mốc 60 ngày)','Viết tài liệu tổng kết 3 trang đánh giá hiệu năng giao diện và đề xuất các điểm cải tiến chức năng dựa trên cơ sở dữ liệu đã phân tích.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-018\",\"evidence-027\"]','2026-09-02 08:08:52.000000'),('89a7806e-10b4-483b-9918-1769f3c8a82c','c325adb9-ffd5-4803-bf29-5c74ecec1b98',1,'Biên tập nội dung hồ sơ học tập cá nhân (Mốc 75 ngày)','Lựa chọn 2 bài tập hoặc sản phẩm tiêu biểu trong kỳ học, viết bài phân tích quá trình thực hiện và kết quả đạt được.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-02 14:20:33.000000'),('8a2ea852-91de-46ef-9b84-054cb9bcfc00','08d47b5b-cae9-4fe5-ab2e-6aaa706e73ef',3,'Đánh giá lại chặng đường và lập kế hoạch tiếp theo','Tự nhìn nhận những điểm tiến bộ, những điều cần cải thiện sau 90 ngày và vạch ra định hướng học tập mới.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-24 15:40:29.000000'),('8a6553dc-fdce-4035-a4cc-947269c700a4','f36bc857-81ac-4b59-afb1-813495179c8c',3,'Thu thập phản hồi và điều chỉnh cấu trúc giải pháp','Ghi nhận ý kiến đóng góp từ thầy cô, bạn bè để chỉnh sửa và nâng cao tính khả thi của mô hình thực hành.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:08:53.000000'),('8a8606c2-4fca-4444-9eee-574f67d061c0','2cdfe31b-f850-46f2-99c5-58ceac1b7426',1,'Thu thập phản hồi và chuẩn hóa tài liệu dự án (Mốc 75 ngày)','Lấy ý kiến nhận xét của giảng viên hoặc cố vấn học tập về đồ án đã hoàn thành, tiến hành chỉnh sửa các chi tiết chưa tối ưu. Tiêu chí hoàn thành: Tài liệu dự án được cập nhật hoàn chỉnh với danh mục các điểm đã cải tiến.',80,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-30 07:09:49.000000'),('8b3cb266-05c8-491c-8596-bf549415efe9','b3597d75-1bde-47ca-878d-831172016ff7',3,'Thực hiện buổi kiểm thử khả năng sử dụng (Usability Testing)','Mời 2 thành viên trong nhóm thực hiện thử nghiệm tương tác trên bản mẫu, ghi nhận ít nhất 3 điểm cần cải thiện về độ mượt mà và trực quan.',75,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-017\"]','2026-08-30 06:57:48.000000'),('8bda7f08-9e02-5fd0-8f3e-fd8455327787','dada94c1-b228-5e1d-af32-769318058810',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"ee93d485-4487-5750-81e1-cd8093b0dde0\"]','2026-08-25 18:28:00.000000'),('8bfea2f0-c934-4b34-85f3-f0335cb0c310','50a05c54-d738-474b-a949-d4306d4212a8',1,'Đăng ký tham gia chuỗi hoạt động thực hành xây dựng sản phẩm số','Tham gia buổi thực hành quy trình tinh gọn để nắm rõ các bước từ hình thành ý tưởng đến xây dựng sản phẩm mẫu.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-020\"]','2026-09-05 03:54:06.000000'),('8cd18585-40fc-409a-af44-2211568d79f5','ebc97266-1916-4647-8128-369d6883ca37',3,'Tổng kết 90 ngày và lập kế hoạch kỳ tiếp theo (Mốc 90 ngày)','Tự đánh giá theo các chỉ số tiến bộ, viết 3 bài học kinh nghiệm và đặt mục tiêu rèn luyện cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:15:57.000000'),('8cf0c453-106f-4684-b4e0-0db64c6ec53d','a5237557-bf50-4b12-834a-8851191222ba',2,'Mốc ngày 50: Đăng ký tham gia hội thảo Product Lab','Đăng ký tham gia chuỗi hoạt động Product Sprint để hoàn thiện tư duy đóng gói sản phẩm và quản lý vòng đời tính năng.',45,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-031\"]','2026-08-29 06:50:07.000000'),('8cf6de47-1dbe-448f-9c22-3011c13185d1','6c8bb01c-35c5-4f1e-965a-5e17638bc6bf',2,'Tham gia workshop thực hành thiết kế sản phẩm số (Mốc 45 ngày)','Đăng ký tham gia Product Sprint để học hỏi quy trình tạo mẫu nhanh và áp dụng vào việc tinh chỉnh giao diện sản phẩm nhóm.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-020\"]','2026-09-05 03:54:44.000000'),('8cfdf5ef-f9d1-51d0-9678-bd9c2eec8af4','ea551add-a4bd-5c52-8230-465bebb44b9f',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Kỹ sư phần mềm backend và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"b11e33bd-a90b-5bb6-8fd3-37958b03358c\"]','2026-08-25 18:07:00.000000'),('8d122ca1-6635-4152-ae4c-c1d997210415','5fa2c9de-a024-4c20-a315-2ed76f92c0c1',1,'Cài đặt và chuẩn hóa môi trường lập trình cá nhân','Thực hiện cài đặt công cụ soạn thảo mã nguồn, trình biên dịch và khởi tạo kho lưu trữ Git cục bộ. Hoàn thành bài kiểm tra cấu hình thành công với ít nhất một chương trình mẫu.',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-04 15:00:27.000000'),('8ddbe943-ba5b-435e-b804-a8b7bf03a002','d9419ec7-d013-4f82-8749-16a5481ecac6',2,'Khảo sát và ghi nhận các phương pháp học tập thực hành','Tổng hợp 3 phương pháp học tập kết hợp giữa thực hành thực tế và phân tích logic.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-24 15:21:04.000000'),('8e148303-110b-4081-9e66-1521fc48d93f','b538408d-9381-4851-bcf1-02999402d515',2,'Thực hành thuyết trình giải pháp kỹ thuật','Chuẩn bị slide và luyện tập trình bày logic, mạch lạc trước nhóm bạn học.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-28 06:08:16.000000'),('8e14a8fe-4d9c-4458-b65b-dfaa1afba9d1','5d6dc234-faa0-43ec-a8f3-b9a020140d86',3,'Viết bài chia sẻ kỹ thuật ngắn gọn về tối ưu mã nguồn','Tổng hợp kinh nghiệm sửa lỗi lập trình thường gặp thành 1 bài viết ngắn hoặc bản ghi chú học tập Markdown dài khoảng 500 từ và chia sẻ trong nhóm học tập lớp (hoàn thành trước mốc 30 ngày).',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-006\",\"evidence-012\"]','2026-09-05 09:58:29.000000'),('8e442a3b-be35-4c62-afe3-b282da7f520b','185d90aa-f4db-46f5-a267-e0cb6e47ca12',1,'Đăng ký tham gia phòng thực hành AI Hacklab (Mốc ngày 35)','Ghi danh tham gia hoạt động AI Hacklab để nghiên cứu cách thức ứng dụng trí tuệ nhân tạo vào mô hình sản phẩm số.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-030\"]','2026-08-29 06:59:25.000000'),('8e52fc44-7e85-46d4-a79a-e5100b6c70d3','a5237557-bf50-4b12-834a-8851191222ba',1,'Mốc ngày 40: Xây dựng nguyên mẫu tương tác cho sản phẩm số','Chuyển đổi khung giao diện thành bản nguyên mẫu có thể bấm chuyển trang, gắn các tương tác cơ bản phục vụ người dùng trải nghiệm thử.',120,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\"]','2026-08-29 06:50:07.000000'),('8ea89478-dec5-4eca-b190-0686b16af93d','d9f63493-3fb5-4a40-ab60-759adca151da',3,'Đánh giá kết quả','So sánh trước và sau để rút ra một bài học cụ thể.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 03:26:09.000000'),('8fa14217-7a40-4dd3-82cf-d24f95cf9c3c','018f20f9-8264-4763-90c9-a7cd6cd2ca68',2,'Luyện tập cấu trúc dữ liệu và thuật toán cơ bản','Giải quyết 10 bài toán về mảng, chuỗi và xử lý logic trên nền tảng trực tuyến; ghi chú lại độ phức tạp thuật toán và cách tối ưu mã cho từng bài vào sổ tay kỹ thuật số.',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-05 05:46:35.000000'),('901469f9-6bd4-5df3-8667-ecf952c4135b','b4edf7c5-b74f-5222-a16e-0c8e726396aa',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"36ee4e32-9812-50cb-9602-4dff0b3877ff\"]','2026-08-25 18:14:00.000000'),('90549009-418f-4c68-880b-d6c595682cd1','45ef38ea-ce8f-4de3-a167-8dcd66cd20ed',2,'Đăng ký trải nghiệm chuyên sâu tại Product Sprint','Tham gia buổi làm việc thực tế cùng các nhóm sinh viên để tiếp thu phương pháp phát triển sản phẩm linh hoạt.',45,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-038\"]','2026-08-31 15:54:21.000000'),('90569484-6ead-4b98-85a5-5dfe39a0d198','264d84b9-3d5f-49fb-97c7-6f17dee3acb1',2,'Đăng ký và tham gia câu lạc bộ kỹ thuật thực hành (Mốc 14 ngày)','Đăng ký tham gia câu lạc bộ Python & Robot Lab tại trường THPT Nguyễn Trãi để bắt đầu giao lưu học thuật và thực hành các bài tập STEM.',120,'register_activity','activity','31000000-0000-4000-8000-000000000005','[\"evidence-001\",\"evidence-039\"]','2026-08-31 08:22:34.000000'),('90694472-716d-55c3-9d83-934c50c985f5','edfca528-8316-5713-bb88-4c3af41a5371',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"66d7b289-9cbf-518d-9108-42c56aa01aba\"]','2026-08-25 18:49:00.000000'),('90f4b88d-eddf-49bd-b36b-8b45c680ae0b','fbcdcfa3-a0a6-40d9-afcb-b5414a640aaf',2,'Thu thập và phân tích tài liệu chuyên khảo nhập môn (Mốc 14 ngày)','Tìm kiếm và đọc 3 bài viết học thuật hoặc tài liệu ngành, ghi chú lại 5 khái niệm cốt lõi theo dạng sơ đồ tư duy trực quan.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:34:53.000000'),('9173c928-cc58-4a5f-be11-9a1b842d0aa0','eb4fe206-94a7-4a24-ac46-083ea23445dd',3,'Xây dựng bài thuyết trình trực quan ngắn','Tạo bài trình bày ngắn gọn, kết hợp số liệu và hình ảnh để chia sẻ phương pháp giải một dạng bài khó.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 09:02:35.000000'),('9180ff41-6af5-497b-95b5-b2600ad92bdf','b62d2179-ef23-426d-8d99-6df2eddbf493',3,'Tự đánh giá và hoàn thiện lộ trình dài hạn','Nhìn nhận lại quá trình 90 ngày, đúc rút bài học về quản lý cảm xúc và thiết lập kế hoạch học tập tiếp theo cho kỳ 2.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 09:46:18.000000'),('9186fcf0-bca1-5366-b34a-5307844f7132','4231e2d1-384b-5885-8433-9f91dd68c3e7',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"4501e0b0-acc0-529a-ab14-e82d54ee3550\"]','2026-08-25 18:35:00.000000'),('9228fe01-b90c-4422-baf1-e4d5e22a8118','fbe0fc20-a7db-450f-91d4-0077293fec36',3,'Viết tài liệu mô tả giải pháp rõ ràng','Soạn thảo bản tóm tắt ngắn gọn, dễ hiểu về mục tiêu, các mốc thời gian và kết quả mong đợi của dự án.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-24 15:40:29.000000'),('925eab0d-61c6-4968-930e-9427e688493d','22e36f00-f43f-49ec-86b4-a4ae49e03fdd',2,'Mốc ngày 80: Thiết kế và xuất bản trang Portfolio cá nhân','Đưa các dự án, hình ảnh sản phẩm và kỹ năng đã được chứng nhận lên trang cá nhân trực tuyến với giao diện chuyên nghiệp.',120,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\",\"evidence-025\"]','2026-08-29 06:50:07.000000'),('929f48ab-b9d8-40d9-946e-2d90e761fe63','2ffb28d4-2d61-493f-bbaa-32df1887cdef',1,'Chủ trì buổi lập kế hoạch học nhóm (Mốc ngày 40)','Tổ chức một buổi thảo luận chuyên đề môn Toán hoặc Vật lý/Tin học với nhóm bạn (3-4 người), phân công công việc cụ thể và thiết lập hạn chót nộp bài tập.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 14:38:51.000000'),('92e1b832-e69b-49b8-a1e2-5182b968f6ef','5f7e1713-4d7b-4846-8cf4-c8974d0f77fe',4,'Tối ưu hóa bản thiết kế và cập nhật nhật ký tiến độ mốc 60 ngày','Điều chỉnh lại 100% các lỗi bất hợp lý trong giao diện dựa trên góp ý và ghi chú bài học kinh nghiệm.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-027\"]','2026-09-03 14:02:44.000000'),('93472d06-4f2f-5f44-8397-077178013a39','0cd7474b-0a25-5568-91fe-5def493e832e',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"90c5ee93-441c-583d-bd55-6407459bde29\"]','2026-08-25 19:10:00.000000'),('93f4eaef-5d99-440b-88d3-c4a6786885e0','b163486b-4572-4bd8-853a-0e7c68adc246',3,'Thu thập và tổng hợp phản hồi cải tiến','Xây dựng bảng câu hỏi ngắn gọn để lấy ý kiến đóng góp về tính khả thi của nguyên mẫu và cập nhật các điểm chỉnh sửa cần thiết.',60,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-26 03:35:52.000000'),('9493a2b8-ce18-493e-91a1-b88ebb90b4e4','530e5ddc-fa0c-4658-9236-738c2af334eb',1,'Đóng gói ứng dụng và tự động hóa quy trình triển khai (Mốc 70 ngày)','Cấu hình Docker container và thiết lập luồng GitHub Actions để tự động đưa ứng dụng lên dịch vụ đám mây miễn phí.',90,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-012\"]','2026-09-04 14:26:53.000000'),('94b1f1ac-be20-4f2c-906b-fc1e2ba4d665','fbe0fc20-a7db-450f-91d4-0077293fec36',2,'Thiết kế sơ đồ quy trình và luồng công việc','Sử dụng công cụ trực quan để vẽ sơ đồ từng bước thực hiện cho giải pháp đã chọn.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-24 15:40:29.000000'),('95107605-603c-4cd3-a004-63f2e2725707','52b33b60-0bac-43bc-9ae4-05cc9c1d78e6',1,'Tinh chỉnh nguyên mẫu sản phẩm dựa trên phản hồi kiểm thử','Tiến hành chỉnh sửa các điểm nghẽn giao diện đã phát hiện ở giai đoạn trước nhằm tối ưu hóa độ tiện dụng. Đầu ra là phiên bản nguyên mẫu cuối cùng được cập nhật đầy đủ.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-029\"]','2026-08-30 06:51:26.000000'),('95b5be8e-c718-47a3-9485-443485682a4c','eed0d553-28f4-4e65-805e-9a61979db152',1,'Xây dựng bộ giao diện tương tác hoàn chỉnh có thể thao tác (Mốc 45 ngày)','Thiết kế tối thiểu 5 màn hình chính của giải pháp số trên công cụ thiết kế chuyên dụng với hệ thống màu sắc và bố cục nhất quán.',120,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-018\"]','2026-09-02 08:03:06.000000'),('95e2d235-9259-4f42-854d-8e68b6ab5692','e5d72e6a-4c4a-4b0a-a459-a36b68913927',3,'Hoàn thiện bản đồ kiến thức tổng hợp giai đoạn 1 (Mốc 30 ngày)','Tổng hợp toàn bộ nội dung đã học thành một trang infographic hoặc mindmap chi tiết, tự đánh giá mức độ hiểu bài đạt trên 80%.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:23:47.000000'),('9636b51b-57a6-4bcf-8fe1-36e503415b0a','a773e589-25a6-4bff-93b8-03af6839529c',1,'Lập trình chức năng xử lý dữ liệu trọng tâm','Hiện thực hóa logic nghiệp vụ của module theo bản thiết kế trước đó; tiêu chí hoàn thành là mã nguồn chạy ổn định với các bộ dữ liệu thử nghiệm.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-012\"]','2026-09-05 09:46:28.000000'),('976063e6-3a50-4066-bad8-f162b1cc0638','93da586a-ba71-4067-a754-8d17835a3047',2,'Tổng hợp kết quả học tập và tạo Portfolio cá nhân năm thứ nhất','Tập hợp các bài tập lớn, ghi nhận bài học kinh nghiệm và sản phẩm thực hành đã làm trong kỳ thành một trang hồ sơ trực tuyến hoàn chỉnh.',120,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-016\"]','2026-09-05 03:54:06.000000'),('97d1a730-9675-4c43-b7d0-1532e29b28ee','5e7268bd-3c85-453c-978a-d695a79daafb',3,'Tổng hợp tài liệu đọc mở rộng và phương pháp thực nghiệm','Thu thập ít nhất 3 nguồn tài liệu học thuật đáng tin cậy về chủ đề nghiên cứu đã chọn để chuẩn bị cho giai đoạn ứng dụng.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 08:08:53.000000'),('97d3aef4-0992-461d-9c8e-b5e44f438dfd','cf77d74f-f57f-4df9-b594-2f36aeb1038a',2,'Mốc ngày 50: Thiết kế bản thảo mô hình trực quan đầu tiên','Thực hiện vẽ phác thảo bố cục, xây dựng cấu trúc nội dung và phối màu cho sản phẩm học tập theo tiêu chuẩn dễ hiểu.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:10:06.000000'),('98349764-9777-4744-9ca4-c9024a563e38','a8bfbfd4-92b2-49c6-a365-8a95b1a2eb67',1,'Hệ thống hóa đề cương các môn học đại cương','Chuyển đổi toàn bộ đề cương môn học học kỳ 1 thành sơ đồ tư duy trực quan để nắm bắt lộ trình môn học.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:15:08.000000'),('98fe40dc-638b-41dd-becd-24aed7a27898','eed0d553-28f4-4e65-805e-9a61979db152',3,'Tổ chức phiên phản biện chéo và ghi nhận đóng góp cải tiến (Mốc 60 ngày)','Thu thập ý kiến đóng góp từ 3 bạn học hoặc giảng viên hướng dẫn về nguyên mẫu đã hoàn thành, sau đó tổng hợp thành danh sách các điểm cần cải tiến.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-015\",\"evidence-017\"]','2026-09-02 08:03:06.000000'),('99defeb3-842f-418c-923c-59950b3ca557','a632f50e-8013-4a9b-8e59-9b7215b9ce57',3,'Tập dượt bài thuyết trình giới thiệu sản phẩm trong 10 phút (Mốc 90 ngày)','Chuẩn bị slide súc tích và tự ghi hình bài thuyết trình giới thiệu dự án để rèn luyện kỹ năng truyền đạt thuyết phục và tự tin.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-08-31 15:59:36.000000'),('99e7a9f8-20ec-4205-9540-fa57ab24955b','b7713564-b690-4a97-b6fd-c33f3d0ef4af',2,'Đánh giá và tối ưu hóa phương pháp ghi chép bài giảng','Áp dụng phương pháp ghi chép có cấu trúc cho hai môn học chính, tổng hợp lại các ý chính thành sơ đồ tóm tắt ngắn sau mỗi buổi học.',45,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 07:43:33.000000'),('9a28b042-b591-4cdc-ae2a-7055fd48f491','4d765328-2862-4931-8dd0-314878a40702',1,'Tham gia sân chơi thực hành Product Sprint','Đăng ký tham gia sự kiện Product Sprint tại Product Lab FPT để học hỏi quy trình xây dựng sản phẩm mẫu và làm việc nhóm.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-020\"]','2026-09-05 03:19:52.000000'),('9a4003c7-a9c8-400d-ad66-d2d0682921bc','3b080d9f-bba3-4e2c-a03d-d40684b897d9',2,'Soạn thảo tài liệu đề xuất giải pháp học tập nhóm','Viết báo cáo ngắn gọn nêu rõ thực trạng, nguyên nhân và giải pháp tổ chức nhóm học tập hiệu quả.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:51:04.000000'),('9a9a0f3d-54d2-4fcf-aea7-657fe05be9b6','c1807478-4d11-4a2f-b3b5-6e3495550312',3,'Thiết kế khảo sát nhu cầu sinh viên cho một ứng dụng học tập','Tạo bảng câu hỏi ngắn gồm 5 câu hỏi để thu thập phản hồi từ 10 bạn học cùng lớp về trải nghiệm sử dụng ứng dụng quản lý học tập tại trường.',45,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-015\"]','2026-09-05 10:14:56.000000'),('9ad9cbea-96fa-4f13-b8e1-4860217ce52d','33251f2f-216b-4dc8-9121-d3583a53d4bd',3,'Tổng kết hồ sơ năng lực học tập 90 ngày (Mốc 90 ngày)','Tổng hợp các sản phẩm đã làm, chứng nhận hoạt động và bài học kinh nghiệm thành trang hồ sơ cá nhân số phục vụ cho đăng ký đồ án kỳ tiếp theo.',60,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-019\",\"evidence-025\"]','2026-09-02 08:08:52.000000'),('9b15e0e0-b9be-451f-8b4e-fe9bf41c0d99','44f359da-2def-41a8-9db0-19840582dd5d',3,'Xây dựng ma trận lựa chọn ưu tiên hướng đi chuyển cấp','So sánh các lựa chọn ngành học dựa trên tiêu chí sở thích, năng lực thực tế và điều kiện cá nhân để xác định thứ tự ưu tiên.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 10:39:35.000000'),('9c25fa19-777c-4767-beb9-44d3e5b6728a','e5764c15-5829-4e07-9280-98c2ccf457a0',2,'Thực hiện thí nghiệm mô phỏng và thu thập dữ liệu','Thực hiện các bước thử nghiệm, ghi nhận kết quả vào bảng theo dõi và phân tích tính khả thi.',180,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-28 02:38:47.000000'),('9c7a9caa-fdfb-46f5-9021-5cc5fb0edd49','caf3d996-e763-4549-a003-987defd6ddf8',3,'Xây dựng định hướng hoạt động học thuật cho kỳ học tiếp theo','Tổng kết điểm mạnh đã phát huy, những điểm cần rèn luyện thêm và đặt mục tiêu tham gia các hoạt động ngoại khóa phù hợp.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-003\",\"evidence-004\"]','2026-08-27 08:08:53.000000'),('9d2bac97-f739-4ba3-af66-3c2a5868c821','b0c394a0-2cff-414c-b336-68d23f1e8d52',1,'Mốc Ngày 75: Tự động hóa triển khai ứng dụng lên nền tảng đám mây','Đóng gói ứng dụng bằng container và cấu hình quy trình CI/CD cơ bản để triển khai lên dịch vụ đám mây miễn phí (như Vercel/Render). Tiêu chí hoàn thành: Đường link trang web hoạt động công khai và người dùng truy cập thử nghiệm được.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-012\",\"evidence-022\"]','2026-09-05 05:33:43.000000'),('9d540ce4-cb6f-5c49-a1cf-225bb01bc735','a69872f4-8f11-5831-99d5-8db3ddfb7808',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Quản trị kinh doanh và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"9d8d5151-152c-52f7-afd1-b48f29882269\"]','2026-08-25 18:42:00.000000'),('9df3712d-5cd1-5467-8121-a8fa23bcc926','7558473a-3bdb-5bf9-aab9-92bfab325f8a',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Chuyên viên trải nghiệm khách hàng.',75,'self_task',NULL,NULL,'[\"700cc2f3-0e83-5ae0-a59e-91cdd50cea83\"]','2026-08-25 19:10:00.000000'),('9e0f9822-74ee-47e0-919b-24c503e349ae','0932d3f6-e190-4530-8324-595793ce686c',2,'Đóng gói mã nguồn và tài liệu hướng dẫn sử dụng sản phẩm','Soạn thảo tệp README chi tiết, hướng dẫn cài đặt và video minh họa 3 phút cho dự án đã hoàn thành trong 75 phút.',75,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 02:49:36.000000'),('9eca3a7b-bff4-4e77-b149-6d7616e57da2','dc95f4e8-67df-4ef5-b3ed-8e898c353b80',3,'Tổng kết hồ sơ năng lực và định hướng học tập','Tổng hợp các dự án, bài tập xuất sắc và mục tiêu học tập thành một bản kế hoạch tổng thể.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 09:02:35.000000'),('9edea020-b50e-4a57-8f30-e6836e0126b3','7c8e34a3-fc57-4490-8be7-548474d5ef03',3,'Mô phỏng phỏng vấn (Mốc 90 ngày)','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"4501e0b0-acc0-529a-ab14-e82d54ee3550\"]','2026-09-02 14:19:37.000000'),('9f6c88ed-d7f4-59f3-8f42-7f76ff70fa0b','a4049fe8-f128-5ae8-ac64-311db2d2fd42',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"90c5ee93-441c-583d-bd55-6407459bde29\"]','2026-08-25 19:10:00.000000'),('9fbe1135-16c1-45bb-847f-5d668a5d325a','d66cb80f-725a-4d6a-884a-43f733cf108b',2,'Tham gia trải nghiệm AI Hacklab tại Innovation Lab','Đăng ký và tham dự buổi AI Hacklab để làm quen với các ứng dụng trí tuệ nhân tạo thực tế trong khuôn viên trường.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-010\",\"evidence-018\"]','2026-09-05 02:49:36.000000'),('a0ae7ce0-6321-4844-8462-7cf2e25161a5','4acb702b-8f89-49b3-b21c-309e36f51868',2,'Soạn thảo tài liệu bàn giao kỹ thuật và hướng dẫn sử dụng','Viết tài liệu mô tả chi tiết kiến trúc hệ thống, hướng dẫn cài đặt cục bộ và luồng sử dụng ứng dụng dưới dạng file định dạng PDF/Markdown (hoàn thành trước mốc 82 ngày).',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-012\"]','2026-09-05 09:58:29.000000'),('a1b572d5-18fa-5c53-9369-db4a1869c610','ea551add-a4bd-5c52-8230-465bebb44b9f',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"d0805143-4ac6-5b00-89ea-ecc8605788d6\"]','2026-08-25 18:07:00.000000'),('a25876a3-bbdd-4449-af94-f42273234fab','8afe7a57-4e83-4ecf-a593-b814f0eec2c3',3,'Đánh giá phương pháp học tập cá nhân','Ghi nhận và phân tích các phương pháp ghi chép, hệ thống hóa kiến thức nhằm tìm ra cách tiếp thu hiệu quả nhất.',60,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-27 09:46:18.000000'),('a25ce725-bd97-4fd3-aac6-0c93c7f1f4c8','e4f35577-dce5-44e7-bb81-00857cf20bfe',3,'Thực hành ghi chép cấu trúc','Ứng dụng phương pháp ghi chép có hệ thống để nắm bắt nhanh các bài giảng trên lớp.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-28 06:08:16.000000'),('a28994ad-1d89-4a01-a11d-727ca8d69791','be691e0d-403d-43f0-98af-fdc971d08990',4,'Đóng gói bản thiết kế luồng trải nghiệm sơ bộ (User Flow)','Sử dụng công cụ thiết kế để vẽ sơ đồ luồng trải nghiệm người dùng gồm tối thiểu 5 bước tương tác chính dựa trên kết quả khảo sát. Đầu ra là liên kết xem sơ đồ thiết kế có đính kèm phần chú thích chức năng.',90,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-029\"]','2026-08-30 06:51:26.000000'),('a2e9e298-4cef-4220-986f-747813836f8b','019beb2b-d9e0-4d8b-b4fc-1fdc03450504',2,'Xây dựng hệ thống UI Style Guide và Component Kit','Thiết lập bảng màu, phân cấp kiểu chữ (typography), bộ icon và các nút tương tác tái sử dụng theo chuẩn thiết kế hiện đại.',90,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-014\"]','2026-08-30 18:07:57.000000'),('a30a5fc2-036b-4ef0-abe7-cbeddad52980','a60c4388-d949-4052-9de6-cd6344a8afe8',1,'Mốc ngày 7: Lập hồ sơ phân tích nhu cầu người dùng trong khuôn viên trường','Thu thập ý kiến từ ít nhất 5 bạn học về khó khăn khi tìm tài liệu học tập, tổng hợp thành bảng danh sách tính năng cần thiết cho sản phẩm số trong 60 phút.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-018\"]','2026-08-29 06:50:07.000000'),('a3a94664-46c4-46f3-8658-94f4d4714941','a85b6430-56f8-4b81-ab82-69f2cd32ff76',1,'Khảo sát thực trạng và định hình bài toán nhóm (Mốc 40 ngày)','Cùng nhóm học tập thảo luận, phỏng vấn nhanh 5 sinh viên khác để xác định một vấn đề thực tế trong môi trường học đường cần cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:34:53.000000'),('a3c0311c-a6ee-481a-9674-c5a6e2ecedb6','19d56d0d-7d77-4c1a-8916-2fd379860ff6',1,'Tổng hợp kết quả và sản phẩm dự án','Biên tập lại toàn bộ báo cáo, bảng biểu và sản phẩm hoàn chỉnh của giai đoạn trước.',120,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-24 15:21:04.000000'),('a3c585dc-63b0-45a7-ae13-828064f956eb','ed6b069b-cd3a-4d0f-abbc-f014b1a9538f',3,'Tổng hợp và hoàn thiện báo cáo phân tích kỹ thuật (Mốc 60 ngày)','Rà soát toàn bộ số liệu và logic của bài tập lớn, kiểm tra tính nhất quán giữa các phần; tiêu chí hoàn thành là bản báo cáo kỹ thuật hoàn chỉnh không lỗi định dạng.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 08:10:24.000000'),('a3f64f0d-b158-4bbf-a46c-6061815c7492','d9f63493-3fb5-4a40-ab60-759adca151da',2,'Thực hiện vòng cải tiến','Cập nhật sản phẩm và ghi lại lý do cho từng quyết định.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 03:26:09.000000'),('a40dfb81-e531-48f1-bdb9-b79eebace389','c2cc7c54-7026-4c2d-b1a4-150f36f869b1',1,'Phân tích 3 sản phẩm số tiêu biểu và lập bảng so sánh tính năng (Mốc 7 ngày)','Chọn 3 ứng dụng phổ biến trên thị trường, phân tích luồng trải nghiệm người dùng và ghi chép ưu/nhược điểm vào bảng phân tích so sánh.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-010\"]','2026-08-31 15:59:36.000000'),('a46dd879-f5ee-4d3f-b3f5-843336bced84','ae0b874e-0652-40cb-8060-484156e64b9f',2,'Xây dựng bảng biểu theo dõi tiến độ học tập 30 ngày','Lập danh sách các đầu mục bài tập, bài đọc tuần và gắn thời hạn cụ thể vào ứng dụng lịch học cá nhân nhằm duy trì nhịp độ học tập ổn định.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:17:58.000000'),('a4833686-9d90-4cc0-9703-2a5244c21899','5b814882-6b95-4d23-b896-3b367a479c6b',1,'Thiết lập môi trường và cấu trúc thư mục chuẩn cho dự án học tập','Tiến hành cài đặt công cụ quản lý mã nguồn, thiết lập cấu hình chuẩn và tạo khung dự án ứng dụng mẫu có phân chia module rõ ràng; tiêu chí hoàn thành là kho mã nguồn được khởi tạo với tập tin hướng dẫn chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-05 09:46:28.000000'),('a48e25ce-2340-4570-b5a4-8557d6a107fc','d4b808e3-3588-4171-b253-95ab353918e0',2,'Đăng ký và tham gia sự kiện Product Sprint tại Lab trường (Mốc 14 ngày)','Ghi danh tham gia buổi thực hành xây dựng sản phẩm để học hỏi quy trình tinh gọn từ các anh chị khóa trên và kết nối đồng đội tiềm năng.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-005\",\"evidence-037\"]','2026-08-30 17:02:18.000000'),('a4e80bb2-c46b-47c3-a20a-3580fd5dc3bd','a327fb28-29e7-4302-8ef2-f8422c64c8f0',1,'Khảo sát thực trạng và định hình bài toán nhóm (Mốc 40 ngày)','Cùng nhóm học tập thảo luận, phỏng vấn nhanh 5 sinh viên khác để xác định một vấn đề thực tế trong môi trường học đường cần cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:23:47.000000'),('a52cd7bd-c653-4180-b0c7-6d1b39b9e258','a60c4388-d949-4052-9de6-cd6344a8afe8',2,'Mốc ngày 14: Phác thảo sơ đồ luồng thông tin và khung giao diện ban đầu','Sử dụng công cụ thiết kế để vẽ luồng người dùng chính gồm 3 màn hình tương tác, xuất file tài liệu hoàn chỉnh để chuẩn bị trao đổi nhóm.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\"]','2026-08-29 06:50:07.000000'),('a5915327-1234-4113-9d6d-b660658cfc5b','1bc0dafa-a8f9-4696-a45c-07cb5e0bb970',2,'Thực hành buổi phản hồi và lắng nghe tích cực','Tổ chức một phiên thảo luận ngắn ghi nhận ý kiến đóng góp từ các thành viên khác mà không ngắt lời hay phán xét.',45,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-26 05:15:08.000000'),('a5cb5fb3-afa9-5d87-a8fe-90e0e93b5885','2ecf4e0b-fece-5678-b5ba-a22384cd5633',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Phát triển phần mềm và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"d0805143-4ac6-5b00-89ea-ecc8605788d6\"]','2026-08-25 18:07:00.000000'),('a5e38974-3da2-48eb-96a7-6863455113f4','552778f1-95a1-4389-8413-bee5e2627334',1,'Thiết lập môi trường làm việc và tài khoản quản lý mã nguồn GitHub','Cài đặt IDE lập trình, thiết lập Git cá nhân, tạo repository đầu tiên và viết tài liệu README tóm tắt mục tiêu rèn luyện lập trình trong tuần đầu tiên (Mốc 7 ngày).',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-05 05:50:04.000000'),('a615deed-08da-4acd-bf34-dc20c5115f46','e7b70721-8423-434b-9765-8236b8dc3718',3,'Viết báo cáo phản tư cá nhân sau 90 ngày (Mốc 90 ngày)','Đúc kết 3 bài học lớn về kỹ năng lãnh đạo, làm việc nhóm và phương pháp triển khai dự án vào tài liệu lưu trữ cá nhân.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\",\"evidence-017\"]','2026-09-05 03:54:44.000000'),('a632080f-70be-4f90-b356-42598e64838f','be691e0d-403d-43f0-98af-fdc971d08990',2,'Thu thập dữ liệu khảo sát và tổng hợp biểu đồ nhu cầu','Tiến hành khảo sát nhanh với 15 sinh viên, xử lý và làm sạch dữ liệu khảo sát để trích xuất 3 điểm nghẽn chính của người dùng. Đầu ra là bảng tổng hợp dữ liệu kèm 3 biểu đồ trực quan hóa nhu cầu.',90,'self_task',NULL,NULL,'[\"evidence-018\"]','2026-08-30 06:51:26.000000'),('a81d1dc7-40e8-5d71-87e6-f84514ea02df','c9d27261-64f8-53df-a65b-171aa5928726',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"36ee4e32-9812-50cb-9602-4dff0b3877ff\"]','2026-08-25 18:14:00.000000'),('a82a0e63-b166-433b-b196-75bfa6a46a34','371916ec-5a1b-4fb4-a252-0da69c907812',1,'Xây dựng bảng phân chia cấu trúc công việc cho bài tập lớn','Lập bảng phân rã công việc (WBS) cho dự án môn học nhóm, xác định rõ trách nhiệm của từng thành viên, thời hạn nộp bài và tiêu chí đánh giá. Đầu ra là tài liệu phân công nhiệm vụ chi tiết.',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 16:07:41.000000'),('a85d7a04-f967-4058-875e-76bf35b2a42d','8b6154bd-6c05-42ac-9919-5e05acbb1f8f',3,'Thiết kế chi tiết 8 màn hình và tạo tương tác nguyên mẫu','Ứng dụng hệ thống linh kiện để hoàn thiện 8 màn hình chính và liên kết các luồng chuyển động mô phỏng trải nghiệm thực tế. Đầu ra là đường dẫn nguyên mẫu tương tác hoạt động mượt mà.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-014\"]','2026-08-30 06:51:26.000000'),('a881d21b-b364-4c2d-a74f-800bd8f59616','de3171b5-a32d-455a-8cae-91c00760e503',1,'Phân tích 3 sản phẩm số tiêu biểu và lập bảng so sánh tính năng (Mốc 7 ngày)','Lựa chọn 3 ứng dụng phổ biến trên thị trường, phân tích luồng trải nghiệm người dùng và tổng hợp ưu, nhược điểm vào bảng so sánh chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-010\"]','2026-09-02 08:03:06.000000'),('a8b41d68-37d1-4dc0-a196-28f3e422f6f0','db099061-603f-420f-94ab-9ef2bff4a708',2,'Khảo sát và phân loại tài liệu theo sơ đồ tư duy','Sử dụng hình ảnh trực quan và dàn ý logic để tổng hợp các chủ đề kiến thức nền tảng.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 09:02:35.000000'),('a999a8a5-9f53-4060-a7d7-bd20d63e2410','41be4372-cfae-483a-8f17-29186718e7d0',2,'Thực hiện bài thuyết trình giải pháp thử nghiệm','Tập dượt và trình bày đề án trước bạn bè hoặc cố vấn học tập, tập trung vào việc diễn đạt mạch lạc lợi ích và cấu trúc vận hành của giải pháp.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 03:35:52.000000'),('aa1fd6da-51e4-4a82-88e5-d4c21f582b0e','c3c6e1aa-7d81-4496-8218-102f60fd1afa',2,'Thiết kế và xuất bản Portfolio số (Mốc 85 ngày)','Tạo trang cá nhân trực tuyến giới thiệu kỹ năng, dự án đã làm và định hướng phát triển học thuật.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:59:48.000000'),('aaf723af-ffb8-51bb-bcd6-01b362cfaf2e','ea551add-a4bd-5c52-8230-465bebb44b9f',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"4afd7d1f-b372-543f-aa9e-bc00e34193d7\"]','2026-08-25 18:07:00.000000'),('ab756d2e-45b7-464b-8e38-432982be6eef','0c66f2a1-7332-4834-8dec-244768ebde76',2,'Lập trình hệ thống RESTful API kết nối cơ sở dữ liệu','Xây dựng các API chức năng CRUD hoàn chỉnh, tích hợp xác thực dữ liệu đầu vào và sinh tài liệu Swagger UI tự động (Mốc 45 ngày).',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-024\"]','2026-09-05 05:50:04.000000'),('abb1a662-44e2-4432-8dcf-c0e0a5a47704','94dc5d45-ed95-4cea-bc9c-b4b8090d0154',3,'Xây dựng portfolio và định hướng vị trí thực tập (Mốc ngày 90)','Đưa đồ án đã hoàn thành vào hồ sơ năng lực cá nhân, rà soát các tiêu chí của cơ hội thực tập thiết kế sản phẩm số để chuẩn bị kế hoạch dài hạn.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-025\",\"evidence-036\"]','2026-08-29 06:59:25.000000'),('ac20798e-8aac-4bf4-9a6f-46f2f4f9cf30','171dda5b-7e4f-47b8-a4ef-5eb2f3d73c92',1,'Viết bài phân tích chi tiết quy trình dự án (Case Study Write-up)','Tổng hợp từ bước xác định bài toán, khảo sát dữ liệu, thử nghiệm giải pháp cho đến giao diện cuối cùng thành một bài viết mạch lạc dài khoảng 800 từ.',100,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-018\"]','2026-08-30 06:57:48.000000'),('accd065e-f0aa-4082-a254-99a8e3e80ba9','0c7f33e4-a21c-4947-b6ab-0dbd25544788',1,'Phỏng vấn và tổng hợp nhu cầu người dùng mục tiêu (Mốc 7 ngày)','Tiến hành khảo sát và phỏng vấn ngắn 3 bạn sinh viên về khó khăn khi sử dụng nền tảng số tại trường, sau đó tổng hợp thành 1 bản User Persona chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-014\",\"evidence-015\"]','2026-08-31 04:21:44.000000'),('ad6f6915-652e-4bcf-8ff6-d39730cecc1d','2e962488-04a3-47a7-9667-37a1ebb8a6b3',2,'Thực hiện khảo sát người dùng thực tế và phân tích yêu cầu tính năng','Phối hợp cùng bạn học thực hiện phỏng vấn ngắn 5 người dùng tiềm năng, tổng hợp bảng phân tích nhu cầu và lập danh sách các chức năng cần ưu tiên phát triển.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-017\",\"evidence-018\"]','2026-08-29 06:39:46.000000'),('adcfd5a0-7b34-5ba5-bc39-fda0f043df1d','bb6a448f-787b-5b06-b94a-94683bc00d60',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"9e9b9745-528e-5ab1-bbcd-41c521ae2100\"]','2026-08-25 18:21:00.000000'),('adfbadf3-1845-5fd7-b956-bf13ef9b951d','2a5fa512-ae9b-5ff8-a4dc-5e23d484ef69',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Thiết kế đồ họa và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"36ee4e32-9812-50cb-9602-4dff0b3877ff\"]','2026-08-25 18:14:00.000000'),('ae4d628c-445c-4e83-907c-0206f21c8fa0','c1807478-4d11-4a2f-b3b5-6e3495550312',2,'Tham gia hoạt động AI Hacklab hoặc Product Sprint tại trường','Đăng ký tham gia workshop Product Sprint để quan sát cách lập kế hoạch sản phẩm và học hỏi cách xây dựng giải pháp số theo nhóm.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-018\",\"evidence-020\"]','2026-09-05 10:14:56.000000'),('ae6b5d2e-f63e-4a4a-8d31-876543331932','5dbd4c3b-5abc-4d23-aeed-e04282ba54c9',1,'Tổng kết và đánh giá hiệu quả phương pháp học','Viết bài tự phản tư về những điểm mạnh đã phát huy và những khía cạnh giao tiếp cần tiếp tục rèn luyện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:15:08.000000'),('aeb7db89-a5ff-4d60-8c10-1d65b643ae9d','19ba47ee-105d-4701-abbe-ad4cdde0bab1',3,'Đăng ký tham gia hội thảo thực hành sản phẩm số (Mốc ngày 30)','Ghi danh tham gia hoạt động Product Sprint để tiếp cận quy trình chuẩn về phát triển sản phẩm công nghệ từ các chuyên gia.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-031\"]','2026-08-29 06:59:25.000000'),('af61f118-97c9-424f-aab9-447ef633a2ef','16644473-7970-435c-8d3d-2924b751067e',2,'Thực hiện vòng cải tiến','Cập nhật sản phẩm và ghi lại lý do cho từng quyết định.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-25 14:17:14.000000'),('b0a00ee6-a3cb-5be6-8e0c-2951101861dd','c9d27261-64f8-53df-a65b-171aa5928726',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Thiết kế đồ họa và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"55ac4e0c-0a45-5e84-94f9-132e6436227f\"]','2026-08-25 18:14:00.000000'),('b0d71c38-08a2-4dd8-bced-f72b0d579e8f','0fda7433-fbe8-496a-bb2b-b41a44a78b9b',3,'Lập hồ sơ tổng kết hành trình 90 ngày và định hướng học kỳ tới (Mốc 90 ngày)','Viết bản tổng kết các kết quả đạt được, kỹ năng đã rèn luyện và lập 3 mục tiêu cho học kỳ tiếp theo; tiêu chí hoàn thành là bài tổng hợp hoàn chỉnh lưu trong hồ sơ cá nhân.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 08:10:24.000000'),('b121721b-2928-4883-9eea-cd6c088bf982','7c8e34a3-fc57-4490-8be7-548474d5ef03',1,'Hoàn thiện portfolio (Mốc 90 ngày)','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"]','2026-09-02 14:19:37.000000'),('b2b23cdf-777a-4c60-8549-0a75de9a4708','2502f190-cee9-4228-af89-f0db77efc252',2,'Thiết kế biểu đồ theo dõi tiến độ','Tạo bảng kiểm soát các đầu việc, phân bổ nguồn lực và đo lường kết quả theo ngày.',60,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-24 15:21:04.000000'),('b412252f-e44a-5398-b3fc-d7cdcb664f0d','46f2906f-8db9-57b5-9e1d-d53e23d5557f',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Chuyên viên vận hành chuỗi cung ứng.',75,'self_task',NULL,NULL,'[\"1e137bb9-75f5-58be-af2a-d92e9a4639e3\"]','2026-08-25 18:49:00.000000'),('b45825a1-36d1-44f5-9b49-7f9c754070f2','99abd075-f415-4eb2-80c9-ba1a663700ce',2,'Thu thập và phân tích tài liệu chuyên khảo nhập môn (Mốc 14 ngày)','Tìm kiếm và đọc 3 bài viết học thuật hoặc tài liệu ngành, ghi chú lại 5 khái niệm cốt lõi theo dạng sơ đồ tư duy trực quan.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:15:57.000000'),('b4696e2d-2321-4c40-bef1-b46808dbb05e','da025c73-4c09-4113-b803-e323a1aba0dc',3,'Nhận đánh giá cuối kỳ','Xin nhận xét có cấu trúc và chọn mục tiêu tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-25 14:17:14.000000'),('b55d4e09-4341-4b2c-bb67-1d84a0a5ebc2','75710fe4-b8a7-42f1-85d9-3a41585991f0',3,'Ghi hình bài thuyết minh thử nghiệm và hoàn thiện hồ sơ dự án cá nhân','Tự quay video 2 phút trình bày về ý tưởng sản phẩm, lưu trữ sản phẩm vào portfolio cá nhân để chuẩn bị cho các kỳ học chuyên ngành.',75,'self_task',NULL,NULL,'[\"evidence-012\",\"evidence-016\"]','2026-09-05 10:14:56.000000'),('b595a059-7bb1-4e26-8651-2afeebf59d2b','0fda7433-fbe8-496a-bb2b-b41a44a78b9b',1,'Thiết kế slide thuyết trình đồ án mạch lạc và trực quan (Mốc 75 ngày)','Biên soạn slide trình bày kết quả đồ án học tập với cấu trúc logic gồm Vấn đề - Giải pháp - Kết quả thực tế; tiêu chí hoàn thành là bộ slide từ 8–12 trang chuẩn chỉnh.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-28 08:10:24.000000'),('b5dac0d2-f0ec-4c25-b95d-ba5fc349bdf1','f36bc857-81ac-4b59-afb1-813495179c8c',1,'Phác thảo đề cương chi tiết cho dự án thực hành cá nhân','Xác định mục tiêu, các bước thực hiện, công cụ cần thiết và tiêu chí đánh giá cho một mô hình hoặc báo cáo phân tích nhỏ.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 08:08:53.000000'),('b5dba7eb-a76d-4a69-b700-f6d1525dc286','2c4ffe0e-12a0-48ff-9883-bff13b099c79',2,'Tìm hiểu và tổng hợp 2 bài nghiên cứu chuyên ngành (Mốc 14 ngày)','Tìm đọc 2 bài viết hoặc bài nghiên cứu về ứng dụng đồ họa/giao diện người dùng trong công nghệ, sau đó ghi chú lại các điểm cốt lõi vào sổ tay học tập. Tiêu chí hoàn thành: Bản tóm tắt 1 trang giấy nêu bật 5 thuật ngữ và 3 xu hướng nổi bật.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-30 07:09:49.000000'),('b66cca36-3189-44ef-9045-0284e31cff0d','2c4c6679-2259-4015-8ce7-38e8937d7023',3,'Điều phối buổi phản biện thử nghiệm nội bộ (Mốc 60 ngày)','Tổ chức buổi chạy thử bài thuyết trình 30 phút cùng các thành viên, thu thập ý kiến góp ý và hoàn thiện sản phẩm trình bày.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-09-03 14:30:25.000000'),('b679bb4c-e554-403c-88c0-358be8adf899','5db13e78-18a0-44a5-bd6e-5db3bc88c29d',2,'Thực hiện bài tập phân tích cấu trúc dữ liệu và giao diện mẫu','Chọn một ứng dụng học tập quen thuộc, vẽ lại sơ đồ luồng người dùng (User Flow) và liệt kê 3 điểm cải thiện giao diện trong tài liệu tóm tắt.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\",\"evidence-018\"]','2026-08-29 06:55:48.000000'),('b6be9d41-ac38-46a3-a8b2-4f083044f1fc','da025c73-4c09-4113-b803-e323a1aba0dc',2,'Chuẩn bị câu chuyện','Trình bày vấn đề, cách thử nghiệm, kết quả và bài học.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-25 14:17:14.000000'),('b6c49745-0485-5eeb-b07c-85ee40a255b8','18c12df8-cc17-5db3-b20d-a40d9a4d4f14',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Nhà thiết kế UI/UX và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"45ff8540-1493-5a64-a787-f5643550fe4c\"]','2026-08-25 18:56:00.000000'),('b769c754-deea-4ad2-95e5-763a453bbb8b','479428f9-204e-4750-9c78-8fb3162e811d',2,'Vẽ bản mẫu Wireframe 5 màn hình chức năng trên Figma hoặc giấy','Thiết kế bố cục trực quan cho các màn hình chính nhằm trực quan hóa giải pháp giải quyết vấn đề của sinh viên trong khuôn viên trường.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 10:14:56.000000'),('b779e9fb-a19f-49a3-9f0a-c46d3e383b57','08d47b5b-cae9-4fe5-ab2e-6aaa706e73ef',2,'Đóng gói sản phẩm và cập nhật hồ sơ cá nhân','Tổng hợp kết quả, hình ảnh và tài liệu dự án vào hồ sơ năng lực để lưu trữ các thành tựu đạt được.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-24 15:40:29.000000'),('b77c86e2-6255-52ee-b1ca-e88619ec6616','e3a7d34a-7fa3-51ef-84f8-88380c976784',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Điều phối dự án kinh doanh số.',75,'self_task',NULL,NULL,'[\"9d8d5151-152c-52f7-afd1-b48f29882269\"]','2026-08-25 18:42:00.000000'),('b7be57eb-9e0d-4c32-aaad-3e19d796083b','16644473-7970-435c-8d3d-2924b751067e',3,'Đánh giá kết quả','So sánh trước và sau để rút ra một bài học cụ thể.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-25 14:17:14.000000'),('b7c02014-e20c-4031-b11e-ac4920e03b45','9b9397de-d562-4ca9-bb26-fea647cfe053',1,'Đăng ký tham gia khóa chạy nước rút phát triển sản phẩm số','Ghi danh vào hoạt động Product Sprint để rèn luyện kỹ năng giải quyết bài toán nghiệp vụ trong môi trường tương tác thực tế.',30,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-031\"]','2026-08-29 06:55:48.000000'),('b7d9b3a8-f11d-47e5-8886-6ff7d1f948ec','0fda7433-fbe8-496a-bb2b-b41a44a78b9b',2,'Tập dượt thuyết trình và xử lý câu hỏi phản biện (Mốc 82 ngày)','Tự quay video hoặc thuyết trình thử trước nhóm bạn trong 10 phút, chuẩn bị sẵn câu trả lời cho 3 câu hỏi tiềm năng; tiêu chí hoàn thành là bản ghi âm/video tập dượt hoàn tất.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-28 08:10:24.000000'),('b820ea09-3d53-5a48-a330-90c850cdeeb2','46f2906f-8db9-57b5-9e1d-d53e23d5557f',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Logistics và chuỗi cung ứng và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"1e417d13-8dee-5201-bce3-9dec171db9cb\"]','2026-08-25 18:49:00.000000'),('b89d00c0-0085-460e-96e8-1bfbbdad2509','171dda5b-7e4f-47b8-a4ef-5eb2f3d73c92',3,'Hoàn thiện và xuất bản trang hồ sơ năng lực cá nhân (Portfolio Page)','Trình bày trực quan Case Study lên trang cá nhân hoặc tài liệu trình chiếu chuyên nghiệp phục vụ việc ứng tuyển các vị trí học việc/thực tập.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-036\"]','2026-08-30 06:57:48.000000'),('b8a922c3-6155-413c-8fff-c70580c73ad0','1bc0dafa-a8f9-4696-a45c-07cb5e0bb970',1,'Chủ động đề xuất cấu trúc phân chia nhiệm vụ trong nhóm','Đóng góp kế hoạch phân công công việc cụ thể cho từng thành viên trong bài tập nhóm lớn.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:15:08.000000'),('b907fb43-d05f-4172-a6ea-11c12f8de13a','6388e0d2-9357-48e6-8934-beabd0dc99ee',3,'Tổng kết dự án và lập hồ sơ năng lực 90 ngày (Mốc 90 ngày)','Viết báo cáo tổng kết dự án gồm kết quả đạt được, bài học kinh nghiệm và cập nhật dự án vào hồ sơ học tập cá nhân (portfolio). Đầu ra là bộ hồ sơ tổng kết 90 ngày sẵn sàng chia sẻ.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-003\",\"evidence-004\"]','2026-09-04 16:07:41.000000'),('b9513981-22bf-4448-b29f-557b66069f16','5ea93051-aac9-4cb5-ba36-f43c59f63328',1,'Khảo sát và phân loại các chủ đề khoa học kỹ thuật lớp mười','Thu thập thông tin về các môn khoa học tự nhiên, liệt kê 3 chuyên đề yêu thích để chuẩn bị định hướng học tập.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 02:38:47.000000'),('b9d44541-4714-598a-92fa-56dedac1b309','ed44bd5e-1a21-5d6c-ace5-db9c9dcb1c97',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Phát triển phần mềm và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"66bff28d-df5e-5dd0-9706-2b4281e9263b\"]','2026-08-25 18:07:00.000000'),('ba66c635-fa76-41b9-a0ce-83aae7f5b2e7','c5ac9ad1-1356-44d7-b5e7-27fe90b70e2d',4,'Tổng kết lộ trình và phỏng vấn thử nghiệm kỹ thuật','Tự thực hành trả lời 10 câu hỏi kỹ thuật trọng tâm theo hồ sơ dự án đã xây dựng; đánh giá lại các kỹ năng đạt được và lập kế hoạch học tập cho học kỳ tiếp theo.',60,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-009\",\"evidence-011\",\"evidence-024\"]','2026-09-05 05:46:35.000000'),('bad7c759-665e-4477-8bde-262c85e2828b','93da586a-ba71-4067-a754-8d17835a3047',1,'Đăng ký tham dự Ngày hội Trình diễn Ý tưởng Khởi nghiệp Sinh viên','Tham dự sự kiện Demo Day tại trường để lắng nghe các đội thi thuyết trình và học hỏi cách giải quyết vấn đề từ các đàn anh.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-022\"]','2026-09-05 03:54:06.000000'),('bb05985e-0d00-4532-b414-ca43ecaab47f','32804826-c2fc-458f-8a53-f2fb1c8fab9a',2,'Thực hiện bài thuyết trình chia sẻ phương pháp học tập','Chuẩn bị slide và trình bày ngắn trong 10 phút tại nhóm học tập hoặc câu lạc bộ về cách ứng dụng tư duy hình ảnh trong ghi nhớ kiến thức.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:17:58.000000'),('bb585029-63d9-4e9a-b332-e6f784cab34c','82033c1c-644d-470a-ab99-b926bc6fe41e',3,'Hoàn thiện Dự án Thực hành Nhỏ tại Mốc 60 Ngày','Tổng hợp kết quả làm việc nhóm thành bài trình bày slide hoặc mô hình thực nghiệm trực quan, tự đánh giá mức độ hoàn thành so với mục tiêu ban đầu.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-004\"]','2026-08-31 15:26:24.000000'),('bc0ea80a-728c-452b-a710-a946d46c3699','690c02ca-beb6-4eb4-9ff1-ec81189c47f6',1,'Tích hợp giao diện người dùng trực quan với hệ thống backend (Mốc 75 ngày)','Xây dựng giao diện web tương tác mượt mà, kết nối dữ liệu trực tiếp với các API đã phát triển và xử lý trải nghiệm phản hồi người dùng.',120,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-022\"]','2026-09-05 05:53:02.000000'),('bc43c7c8-613d-4869-b9a0-7ee821ed23db','d332fa6e-085c-4c8f-8019-383be4e84bcb',2,'Xây dựng sản phẩm thử nghiệm (Mốc 60 ngày)','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"]','2026-09-02 14:19:37.000000'),('bcce5d0b-2cad-4efd-abf3-e301db47314c','1a5238c1-ecd7-44af-ac07-cc41d321c2f6',3,'Tập dượt bài thuyết trình giới thiệu sản phẩm trong 10 phút (Mốc 90 ngày)','Chuẩn bị slide súc tích và tự ghi hình bài thuyết trình giới thiệu dự án để hoàn thiện kỹ năng diễn đạt tự tin, thuyết phục.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-09-02 08:03:06.000000'),('bd09f0a6-3a22-4235-8ad5-9e9d7447414e','9a464336-3c56-4344-9a4a-26215f5e5656',2,'Triển khai thử nghiệm ứng dụng lên nền tảng đám mây','Cấu hình tự động hóa triển khai ứng dụng lên môi trường lưu trữ miễn phí để phục vụ trình chiếu; tiêu chí hoàn thành là có đường dẫn web truy cập trực tiếp kiểm tra tính năng.',85,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-09-05 09:46:28.000000'),('bded757d-101d-4322-9612-7719324a0a0f','0b3fae6f-f0e4-4b2d-af60-a0464c9cfd10',2,'Đóng gói Hồ sơ Năng lực Học sinh Lớp 12','Tập hợp các sơ đồ tư duy, báo cáo dự án thực hành và minh chứng hoạt động đã làm thành tài liệu hồ sơ cá nhân hoàn chỉnh dạng PDF.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-31 15:26:24.000000'),('be7288e8-5611-4c5c-b42a-93962cd17937','0b3fae6f-f0e4-4b2d-af60-a0464c9cfd10',1,'Tổng kết Dữ liệu Điểm số và Đánh giá Tiến bộ','Lập biểu đồ theo dõi kết quả các bài kiểm tra định kỳ trong 60 ngày qua để xác định rõ điểm cần bứt phá trong giai đoạn thi cử sắp tới.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-31 15:26:24.000000'),('bea4d4dd-5245-44e6-94db-efad1a2ccf3a','1a5238c1-ecd7-44af-ac07-cc41d321c2f6',1,'Tổng hợp số liệu và phân tích kết quả thử nghiệm dự án (Mốc 75 ngày)','Thống kê mức độ hài lòng, thời gian hoàn thành tác vụ của người dùng trên bản mẫu và lập biểu đồ trực quan hóa dữ liệu thu được.',90,'self_task',NULL,NULL,'[\"evidence-018\",\"evidence-027\"]','2026-09-02 08:03:06.000000'),('bef9e1ee-ca38-4a19-a1d6-c3ea22256fa7','b3c0872e-ca09-4784-8dd8-01fbe91c94ae',1,'Đăng ký và tham gia chương trình Product Sprint xây dựng sản phẩm','Nộp hồ sơ tham gia sự kiện Product Sprint tại Product Lab để rèn luyện kỹ năng xây dựng giải pháp số theo nhóm thực tế.',60,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-004\",\"evidence-016\",\"evidence-038\"]','2026-09-02 08:08:52.000000'),('bfb57c70-169f-4e01-b442-698432710fe5','b163486b-4572-4bd8-853a-0e7c68adc246',1,'Tổ chức phiên trao đổi định hướng nhóm nhỏ','Chủ động đề xuất ý tưởng trong nhóm học tập, thực hành kỹ thuật lắng nghe tích cực và ghi nhận góc nhìn từ các thành viên trước khi chốt giải pháp.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 03:35:52.000000'),('bfc91ca6-3b9d-43f6-b3e7-b26277d1729a','47474713-b413-4ebe-bb11-7be0181a8e15',2,'Tổng hợp phương pháp ghi chép có cấu trúc (Mốc 14 ngày)','Áp dụng phương pháp ghi chú Cornell hoặc sơ đồ tư duy cho 3 môn học chuyên ngành đầu tiên để tăng khả năng hệ thống hóa kiến thức.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-09-03 14:30:25.000000'),('c00aaa47-5af9-4980-ac2a-651f4ff0390b','eabdb9ad-4f30-44bc-aaf5-e068038392d2',1,'Đóng gói ứng dụng vào Docker Container và cấu hình môi trường','Viết Dockerfile tối ưu, đóng gói toàn bộ ứng dụng và kiểm tra khả năng chạy nhất quán trên môi trường cục bộ (Mốc 70 ngày).',90,'self_task',NULL,NULL,'[\"evidence-005\",\"evidence-038\"]','2026-09-05 05:50:04.000000'),('c036ebd2-2502-42b6-b151-7298c7c2cdb3','6ff93b0d-4f36-4126-96ba-cf4bc10a8a9b',1,'Xây dựng bộ thiết kế mẫu và nguyên mẫu tương tác','Áp dụng hệ thống màu sắc, kiểu chữ và thành phần giao diện chuẩn để tạo mẫu thử tương tác hoàn chỉnh cho 5 màn hình ứng dụng.',120,'self_task',NULL,NULL,'[\"evidence-009\",\"evidence-013\",\"evidence-014\"]','2026-08-31 04:21:44.000000'),('c1864128-4620-4edf-a8b0-4470f1fb0443','954ac626-eae0-461d-9fe3-eb330a7ab030',1,'Thiết lập môi trường làm việc và công cụ lập trình','Cài đặt trình biên soạn mã nguồn, Git và tạo tài khoản lưu trữ mã để chuẩn bị cho việc học tập kỹ thuật.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\"]','2026-09-05 03:46:02.000000'),('c1cb007a-9e01-44ad-9e2b-447c694f9b17','2754996d-6ebf-4d60-a666-68532bfe1791',3,'Vẽ luồng người dùng và khung giao diện sơ cấp','Sử dụng công cụ thiết kế tạo 5 màn hình wireframe minh họa luồng trải nghiệm chính của ứng dụng kết nối nông sản.',90,'self_task',NULL,NULL,'[\"evidence-014\",\"evidence-018\"]','2026-09-03 14:02:44.000000'),('c1d35bed-421a-4505-a108-6a4c8c1d5065','0acbe34f-147d-450a-a19c-dca06e910791',3,'Thu thập phản hồi','Xin phản hồi từ ít nhất hai người và ghi lại điều học được.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-25 14:17:14.000000'),('c280253e-55de-45f0-920e-a99f94a9e1b4','f9009ae4-5eee-44bb-b53a-ced9c5b7d2bd',2,'Xây dựng bộ kiểm thử đơn vị tự động cho các hàm nghiệp vụ chính (Mốc 50 ngày)','Áp dụng một thư viện kiểm thử tự động để viết tối thiểu 8 ca kiểm thử (test cases) bao phủ các trường hợp biên và luồng xử lý chính của ứng dụng.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-025\"]','2026-09-05 05:53:02.000000'),('c2a96a46-ca7d-45f5-8705-ac88966fde6a','f60922d5-3890-4ee7-9154-53a2cd5547fe',1,'Đăng ký tham gia Thiết kế Poster Truyền thông Học đường','Tham gia buổi thực hành tại phòng B204, làm quen với bố cục thị giác và công cụ thiết kế ấn phẩm thông tin cho lớp học.',90,'register_activity','activity','31000000-0000-4000-8000-000000000006','[\"evidence-014\",\"evidence-018\"]','2026-09-05 07:49:00.000000'),('c397801a-2fc5-4abe-9dda-750427a4f39c','ccf6f9d9-c863-4fa7-b72f-1619f5935f98',2,'Ghi hình bài thuyết trình giới thiệu sản phẩm (Mốc 85 ngày)','Quay một đoạn clip ngắn (3-5 phút) diễn giải cách giải quyết vấn đề của sản phẩm và gửi cho giảng viên hướng dẫn xin nhận xét.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-08-29 06:44:00.000000'),('c3e7b01e-b079-4229-922e-66f2ccb2da81','605c3b41-f3ff-4d33-879b-e50158b99991',2,'Biên tập trang Case Study và quay video demo tương tác','Đưa toàn bộ hình ảnh mockup, luồng tương tác và video minh họa 2 phút lên trang hồ sơ cá nhân trực tuyến.',105,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-014\",\"evidence-016\"]','2026-08-31 04:21:44.000000'),('c3f0b7b4-315a-437b-8bf1-9f2b56a69af2','51d2c08c-d654-4d7b-b77f-1ea3f868a481',2,'Xây dựng các điểm cuối API xử lý nghiệp vụ','Lập trình dịch vụ Back-end cung cấp các API CRUD dữ liệu, kiểm tra tính hợp lệ của dữ liệu đầu vào và viết tài liệu hướng dẫn gọi API theo chuẩn OpenAPI/Postman.',120,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-005\",\"evidence-024\"]','2026-09-05 05:46:35.000000'),('c3f612a0-4ef7-4ccc-a793-ce50059682cd','f4c407ff-7dc9-472c-ba65-deab159c356f',1,'Đăng ký tham gia thử thách đổi mới sáng tạo học đường (Mốc 40 ngày)','Đăng ký tham gia chương trình Thử thách Doanh nhân trẻ để áp dụng tư duy logic vào bài toán thực tiễn và rèn luyện góc nhìn sáng tạo kinh doanh.',120,'register_activity','activity','21000000-8e2d-4dae-8d47-ea4ac11c3dc3','[\"evidence-004\",\"evidence-005\",\"evidence-038\"]','2026-08-31 08:22:34.000000'),('c4509c36-c169-45ef-a138-968e6692c53c','0acbe34f-147d-450a-a19c-dca06e910791',1,'Chọn một vấn đề gần gũi','Mô tả người dùng, nhu cầu và kết quả mong đợi.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-25 14:17:14.000000'),('c4d34452-dfeb-4752-8022-412989bd728b','ef54a41d-8316-460f-8867-b5a134b40248',1,'Đăng ký tham gia sáng kiến Green Campus tại Green Hub','Ghi danh dự án Green Campus để cùng các bạn sinh viên đóng góp giải pháp quản trị năng lượng hoặc phân loại rác thông minh cho khuôn viên trường.',90,'register_activity','activity','31000000-0000-4000-8000-000000000011','[\"evidence-021\"]','2026-09-05 08:20:23.000000'),('c5bf5a2e-2e82-4330-a44b-bd24ecb5b8fe','e5764c15-5829-4e07-9280-98c2ccf457a0',3,'Đánh giá và tối ưu hóa giải pháp','Xem xét lại các điểm chưa tối ưu trong quá trình thử nghiệm và tiến hành chỉnh sửa mô hình.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-28 02:38:47.000000'),('c5f2dd19-97b7-47a3-af25-7fe14ab54d52','5e7268bd-3c85-453c-978a-d695a79daafb',2,'Thiết lập lịch trình học tập và theo dõi năng suất cá nhân','Xây dựng thời gian biểu tuần cân đối giữa các môn học chính khóa lớp 10 và thời gian tự nghiên cứu sáng tạo.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:08:53.000000'),('c5f4bcab-4069-4de0-ae04-ba3bc0d8b436','a2502720-8ba6-42c2-8892-e53acf0b12f2',1,'Hoàn thiện đầu ra','Tổng hợp phiên bản tốt nhất cùng bằng chứng tiến bộ.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 03:26:09.000000'),('c7f66245-b586-41ed-829e-3be426e921ac','af98ae9e-f825-406b-b251-c9f234dabcad',3,'Tổng kết tài liệu phân tích kỹ thuật cho một bài toán thực tế (Mốc 30 ngày)','Viết tài liệu tóm tắt giải pháp kỹ thuật (Software Design Document) cho một mô-đun quản lý dữ liệu nhỏ, bao gồm sơ đồ luồng và thiết kế cơ sở dữ liệu mẫu.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\",\"evidence-007\"]','2026-09-05 05:53:02.000000'),('c804c994-25ae-424f-8acb-1477c6f3ac32','0ad3072d-08ff-4a3b-acda-cb3bc400d2c2',2,'Thực hiện phỏng vấn thử hoặc trình bày định hướng (Mốc ngày 80)','Chuẩn bị bài thuyết trình 5 phút về lý do chọn ngành và kế hoạch học tập đại học, sau đó trình bày trước giáo viên/người hướng dẫn để nhận phản hồi cải thiện.',60,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-09-04 14:38:51.000000'),('c922d65e-0e4d-4792-badd-aa089e11f36f','9b9397de-d562-4ca9-bb26-fea647cfe053',2,'Xây dựng khung phân chia công việc và điều phối nhóm 3 thành viên','Lập bảng phân công nhiệm vụ chi tiết theo tuần, áp dụng quy trình trao đổi ngắn 15 phút đầu giờ để tối ưu tiến độ thực hiện.',60,'self_task',NULL,NULL,'[\"evidence-012\",\"evidence-016\",\"evidence-017\"]','2026-08-29 06:55:48.000000'),('c943defc-5aae-4cb3-866d-024a1fb34704','792554d3-3b4e-4aea-9c52-45bae3b401df',3,'Mốc 90 ngày: Hoàn thiện hồ sơ năng lực kỹ thuật và trình diễn đồ án','Xây dựng trang Portfolio cá nhân tổng hợp đồ án thực tế, mã nguồn minh họa và slide thuyết trình sản phẩm phục vụ đánh giá cuối kỳ hoặc ứng tuyển thực tập.',120,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-012\",\"evidence-024\"]','2026-09-02 15:44:07.000000'),('c9825150-44d9-4388-955a-8e8cbd778b54','8b4afeec-9273-41d1-bdf8-e99c7f992342',2,'Đóng gói đồ án học tập thành bài nghiên cứu tình huống (Case Study) chuyên nghiệp','Viết bài chia sẻ chi tiết về quá trình từ nghiên cứu, phác thảo, xử lý phản hồi người dùng đến sản phẩm cuối cùng kèm số liệu đo lường kết quả.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-010\",\"evidence-018\"]','2026-08-29 06:39:46.000000'),('ca0e6346-d7a0-46fa-8b51-9e73024693ec','5eaae2d8-e7c6-484d-a023-1c6ae0208820',2,'Thiết kế bộ Slide thuyết trình giải pháp công nghệ rút gọn (Pitch Deck)','Xây dựng bộ tài liệu trình chiếu 8-10 trang gồm: Vấn đề, Giải pháp, Mô hình vận hành, Phân công nhân sự và Kế hoạch triển khai trong 3 tháng tới.',120,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 08:20:23.000000'),('ca413bb6-a2aa-4c5b-9acd-e1d49baef3de','dc95f4e8-67df-4ef5-b3ed-8e898c353b80',1,'Đánh giá tiến độ và hiệu quả các phương pháp đã áp dụng','So sánh kết quả học tập trước và sau 60 ngày để nhận diện các điểm cần tiếp tục phát huy hoặc điều chỉnh.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 09:02:35.000000'),('ca77d81b-f93f-415b-b30e-96b67fdf6337','7f6856fe-b940-4f8e-9f4e-a906c3e0562b',2,'Thu thập và xử lý số liệu khảo sát','Tổng hợp kết quả khảo sát vào bảng tính, sử dụng các công cụ trực quan hóa dữ liệu cơ bản để phân loại phản hồi.',150,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-27 09:46:18.000000'),('cb835230-52e0-462f-995d-488550701bd3','5b814882-6b95-4d23-b896-3b367a479c6b',3,'Soạn thảo tài liệu mô tả kiến trúc kỹ thuật module','Viết tài liệu tóm tắt cơ chế hoạt động, danh sách hàm chính và quy ước kiểm thử của module; tiêu chí hoàn thành là bản tài liệu kỹ thuật rõ ràng để người khác có thể đọc và hiểu được cấu trúc.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-05 09:46:28.000000'),('cba73be7-c15d-4ae1-809e-783255f2177d','8b4afeec-9273-41d1-bdf8-e99c7f992342',3,'Hoàn thiện trang hồ sơ năng lực cá nhân và nhận xét đánh giá','Tập hợp các sản phẩm đã hoàn thành lên trang cá nhân trực tuyến, trình bày thử nghiệm trước cố vấn học tập hoặc bạn bè để ghi nhận ý kiến cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-015\",\"evidence-016\"]','2026-08-29 06:39:46.000000'),('cbad5f8d-278b-4bb6-bd64-d6be847a6fd0','3ba2c0ef-446d-4a5c-8ae4-a757d2425cd6',4,'Đánh giá lại mục tiêu cá nhân và định hướng học kỳ tới','Đối chiếu kết quả 90 ngày với bảng điểm kỹ năng cá nhân để đặt ra 3 mục tiêu rèn luyện cho các môn học chuyên ngành tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-022\",\"evidence-026\"]','2026-08-31 15:54:21.000000'),('cbaf1237-138b-4b57-aff7-7e7f95f1e91c','018f20f9-8264-4763-90c9-a7cd6cd2ca68',4,'Đánh giá chéo mã nguồn cùng bạn học','Gửi link repository cho 1 bạn cùng lớp để nhận xét cấu trúc mã; ghi nhận ít nhất 3 điểm cần cải thiện và tiến hành tái cấu trúc mã theo phản hồi.',45,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-011\"]','2026-09-05 05:46:35.000000'),('cc81f555-0088-5ca1-9428-5a43f8c96ade','b4708adc-b93c-5e85-af18-eb08b6023450',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"63a115ff-6acc-5bdb-aaf8-e6e2654ff041\"]','2026-08-25 18:49:00.000000'),('cccd679c-0bc9-43e3-911b-9721342748b1','bcac4fd9-9dc0-4ce3-84b4-567946972391',3,'Đánh giá mức độ sẵn sàng và tối ưu hóa thói quen học tập','Thực hiện tự kiểm tra định kỳ hàng tuần, duy trì kỷ luật bản thân và tăng cường khả năng giữ bình tĩnh trước áp lực.',60,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-27 08:51:04.000000'),('ccd904dd-2276-4b73-996a-b98811284a59','3ba2c0ef-446d-4a5c-8ae4-a757d2425cd6',1,'Biên soạn tài liệu câu chuyện sản phẩm (Case Study)','Viết lại hành trình từ vấn đề, giải pháp, thiết kế đến bài học kinh nghiệm dưới dạng bài viết trực quan kèm hình ảnh minh họa.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-015\"]','2026-08-31 15:54:21.000000'),('cd21f5fa-624c-447e-869e-9f6f43b76385','f197fa76-4527-44b6-8af4-595a5bae2332',2,'Thiết kế và xuất bản Portfolio số (Mốc 85 ngày)','Tạo trang cá nhân trực tuyến giới thiệu kỹ năng, dự án đã làm và định hướng phát triển học thuật.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:34:53.000000'),('cde13f35-3d90-414b-92a0-6c85c2d2c571','fa09eeb0-a584-46e9-9223-78b92d6e99df',1,'Nghiên cứu cấu trúc thông tin và giao diện của 3 ứng dụng công nghệ phổ biến','Lựa chọn 3 ứng dụng số yêu thích, dành thời gian phân tích luồng thao tác chính của người dùng và ghi chép lại các điểm mạnh về bố cục cũng như điểm cần cải thiện vào sổ tay học tập cá nhân.',90,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-014\"]','2026-08-29 06:39:46.000000'),('ce0a569d-2cf2-4231-85f5-7a1e492a198f','b3c0872e-ca09-4784-8dd8-01fbe91c94ae',2,'Thu thập và xử lý tập dữ liệu phản hồi người dùng','Tạo biểu mẫu khảo sát trực tuyến, thu thập ít nhất 15 phản hồi thử nghiệm và xử lý bảng số liệu bằng bảng tính để rút ra 3 chỉ số quan trọng.',75,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-009\",\"evidence-018\"]','2026-09-02 08:08:52.000000'),('ce5a6548-3f9d-47be-b6d4-d7cec0725d24','839d216c-f287-4e0f-b780-20a61d5961b3',3,'Lập kế hoạch mục tiêu chuyên ngành năm thứ hai (Mốc 90 ngày)','Xác định 3 chứng chỉ hoặc môn học chuyên ngành trọng tâm cần chinh phục trong năm tiếp theo cùng các mốc hành động chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-09-03 14:30:25.000000'),('ceb96ea1-f7fa-4ec2-955e-e6eec3003968','1bd1f1c9-33c6-4d7b-99bc-8d0b0ac3ba13',2,'Chuẩn hóa phương pháp ghi chép bài giảng theo sơ đồ logic (Mốc 14 ngày)','Áp dụng phương pháp ghi chú cấu trúc cho ít nhất 2 môn học chuyên ngành; tiêu chí hoàn thành là 2 bộ tóm tắt bài giảng có sơ đồ khối và danh sách từ khóa chuyên ngành.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-28 08:10:24.000000'),('cecc469b-7e0a-40fd-82cb-d1c345894d13','19ba47ee-105d-4701-abbe-ad4cdde0bab1',2,'Phác thảo cấu trúc luồng người dùng và wireframe (Mốc ngày 14)','Sử dụng công cụ thiết kế để xây dựng sơ đồ luồng thao tác và hoàn thiện 5 màn hình khung xương mô phỏng tính năng chính của sản phẩm.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-014\"]','2026-08-29 06:59:25.000000'),('cf59f8f0-5d2f-57ac-b5e1-206abadec887','e3a7d34a-7fa3-51ef-84f8-88380c976784',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Quản trị kinh doanh và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"2a44b91b-8bd6-5be1-a1ee-9cc0deec342c\"]','2026-08-25 18:42:00.000000'),('cfa7e967-83b2-49cc-8735-38fe78973c34','9cba4dc2-dd9a-4453-baae-1f5db58d4515',3,'Tổ chức phiên phản biện chéo tiến độ dự án nhóm','Chủ trì phiên trao đổi nội bộ 45 phút để rà soát mã nguồn, phân tích lỗi và lắng nghe ý kiến phản biện từ đồng đội.',45,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\"]','2026-09-05 02:49:36.000000'),('d088dd1a-50c9-40dc-b75e-faab3e70d249','36ed863b-ef2f-49ff-a236-18ef35802458',1,'Khảo sát và ghi nhận vấn đề thực tế tại khuôn viên trường','Quan sát thực địa không gian học tập hoặc sinh hoạt chung, chụp ảnh và ghi chú 3 điểm cần cải thiện trải nghiệm cho sinh viên.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:17:58.000000'),('d0bb9469-4b3e-4ea0-abbd-5180b3a582a0','9a464336-3c56-4344-9a4a-26215f5e5656',1,'Tích hợp toàn diện các thành phần của ứng dụng','Kết nối module nghiệp vụ với giao diện người dùng và cơ sở dữ liệu; tiêu chí hoàn thành là toàn bộ ứng dụng hoạt động thông suốt từ đầu đến cuối luồng trải nghiệm.',100,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-012\"]','2026-09-05 09:46:28.000000'),('d150364f-ede1-567d-aff0-6c31e4aaae22','7999cee7-84c2-5883-b9ab-f9594ca7ab97',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"]','2026-08-25 18:35:00.000000'),('d19bb370-3b08-4dff-afaa-5c498428879e','44f359da-2def-41a8-9db0-19840582dd5d',1,'Lập bảng tự đánh giá sở thích và thế mạnh học tập','Ghi nhận lại các môn học, hoạt động thực hành và chủ đề sáng tạo mà bạn cảm thấy hào hứng nhất trong năm học lớp 12.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 10:39:35.000000'),('d1bdec29-bfa2-4bc0-8d10-5ab1dcf7f058','24b17946-5242-47c0-8827-063fdead4de3',2,'Viết bài phân tích chuyên sâu Case Study cho sản phẩm số','Trình bày cấu trúc bài viết gồm: Vấn đề - Phương pháp nghiên cứu - Quá trình lặp thiết kế - Kết quả thử nghiệm và bài học rút ra.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-014\"]','2026-08-30 18:07:57.000000'),('d27649c0-a039-4d9f-a412-8beea0a9c4bf','eed0d553-28f4-4e65-805e-9a61979db152',2,'Đăng ký tham gia hoạt động Product Sprint để hoàn thiện quy trình sản phẩm (Mốc 50 ngày)','Ghi danh tham gia chương trình Product Sprint tại Product Lab FPT để trải nghiệm phương pháp phát triển sản phẩm theo chu trình lặp nhanh.',120,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-038\"]','2026-09-02 08:03:06.000000'),('d35255f6-a39e-4ab2-a248-1977a451f131','cf9ad7f5-62ae-4468-902c-757beeceacf5',2,'Khảo sát và lập bảng so sánh các công cụ quản lý dự án học tập','Tìm hiểu và thực hành tạo không gian làm việc cá nhân trên Notion hoặc Trello; thiết lập bảng theo dõi các môn học và dự án ngoại khóa trong học kỳ.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-011\"]','2026-09-05 08:20:23.000000'),('d35abd67-8238-45a3-a94b-fb3539516512','2cdfe31b-f850-46f2-99c5-58ceac1b7426',3,'Đăng ký tham gia một câu lạc bộ học thuật hoặc cuộc thi sinh viên (Mốc 90 ngày)','Tìm hiểu thông tin và nộp đơn tham gia một câu lạc bộ chuyên môn hoặc cuộc thi ý tưởng sáng tạo cấp trường phù hợp với định hướng. Tiêu chí hoàn thành: Đơn đăng ký hoặc kế hoạch dự thi được gửi đi thành công.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:09:49.000000'),('d4966f97-eac6-5f98-bd50-be0b2cd52952','dada94c1-b228-5e1d-af32-769318058810',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"bb3a5fc8-1199-590f-b2d6-50904c80682d\"]','2026-08-25 18:28:00.000000'),('d586fe54-c118-4aa3-921a-00a9122577ca','b9180876-24be-4bf2-84fe-e4014f0d6547',3,'Hoàn thiện chiến lược ôn tập và mốc thời gian chuyển tiếp','Lập thời gian biểu chi tiết cho các kỳ thi quan trọng cuối cấp kết hợp duy trì sở thích sáng tạo cá nhân.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 10:39:35.000000'),('d604c941-4778-41d6-8c9f-b196d043a703','22e36f00-f43f-49ec-86b4-a4ae49e03fdd',1,'Mốc ngày 70: Soạn thảo bài phân tích trường hợp (Case Study) cho dự án','Viết bài tổng kết dự án theo cấu trúc: Đặt vấn đề, Giải pháp thiết kế, Kết quả kiểm thử và Bài học kinh nghiệm trong 90 phút.',90,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-029\"]','2026-08-29 06:50:07.000000'),('d67f2dc0-1936-57d7-8e2c-a564b4a470c4','62a1d2cd-97e8-51d8-a485-164040409753',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Điện toán đám mây và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"bfe146ba-09db-5b2a-8589-c7df7ac2a57d\"]','2026-08-25 19:03:00.000000'),('d6b872a4-7928-464f-b6b9-d298a2f3cdd1','b0c394a0-2cff-414c-b336-68d23f1e8d52',2,'Mốc Ngày 82: Biên soạn tài liệu hướng dẫn và video demo sản phẩm','Viết tài liệu hướng dẫn sử dụng, giải thích kiến trúc hệ thống và ghi hình một đoạn video demo ngắn (2-3 phút) về các điểm nổi bật của dự án. Tiêu chí hoàn thành: Bộ tài liệu kỹ thuật hoàn chỉnh và link video đính kèm vào kho lưu trữ mã nguồn.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\",\"evidence-028\"]','2026-09-05 05:33:43.000000'),('d6d5fc9d-541c-49bc-a226-11182a52e732','c664f29e-520b-4182-b86b-2eae53ebcf6d',1,'Thiết lập hệ thống quản lý học tập cá nhân (Mốc 7 ngày)','Bắt đầu bằng việc liệt kê toàn bộ môn học kỳ 1, tạo bảng theo dõi tiến độ tuần trên Notion hoặc sổ tay với các cột mục tiêu, deadline và trạng thái hoàn thành. Đầu ra là bảng quản lý lịch học hoàn chỉnh.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 16:07:41.000000'),('d6dc5ef2-b05a-4b02-abbd-0e3db5b55592','f32160ac-2713-4173-92b6-711e4c6f12cb',2,'Thiết kế và xuất bản Portfolio số (Mốc 85 ngày)','Tạo trang cá nhân trực tuyến giới thiệu kỹ năng, dự án đã làm và định hướng phát triển học thuật.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:23:47.000000'),('d71ea07f-eaef-4b68-b042-5219193722e5','019beb2b-d9e0-4d8b-b4fc-1fdc03450504',4,'Tiến hành Usability Testing với 3 sinh viên cùng khóa','Quan sát người dùng thực hiện nhiệm vụ trên prototype, ghi chép điểm nghẽn trải nghiệm và lập bảng tổng hợp cải tiến.',75,'self_task',NULL,NULL,'[\"evidence-017\",\"evidence-018\"]','2026-08-30 18:07:57.000000'),('d7cffd1c-f6b3-443e-b6c9-bfce0aca38d8','b9b16f87-3990-4305-93db-3ba64740b44c',1,'Phân tích hồ sơ năng lực (Mốc 30 ngày)','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"4501e0b0-acc0-529a-ab14-e82d54ee3550\"]','2026-09-02 14:19:37.000000'),('d80be879-b462-5b8d-8463-7b73806d6d56','a69872f4-8f11-5831-99d5-8db3ddfb7808',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"108349f9-4817-50e6-9cc9-cc516f64061c\"]','2026-08-25 18:42:00.000000'),('d8545743-df82-4eef-beb4-a13a43295119','371916ec-5a1b-4fb4-a252-0da69c907812',3,'Thực hiện phiên phản hồi nhóm định kỳ (Mốc 60 ngày)','Tổ chức phiên họp ngắn 20 phút cùng nhóm bạn học để thu nhận ý kiến đóng góp về cách điều phối, ghi chú lại các phản hồi mang tính xây dựng. Đầu ra là biên bản ghi nhận phản hồi cải tiến.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 16:07:41.000000'),('d8d2cce8-ecd1-402e-9e29-82d24622b52c','cb65ccec-9541-45c8-97a6-0cf68ac7f9ea',1,'Đăng ký tham gia AI Hacklab để nâng cao kỹ năng ứng dụng AI (Mốc 35 ngày)','Đăng ký chương trình AI Hacklab tại Innovation Lab nhằm tìm hiểu cách tích hợp các mô hình thông minh vào bài toán cá nhân hóa giao diện.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-003\",\"evidence-036\"]','2026-08-30 17:02:18.000000'),('d9411cd0-3609-40db-a35b-6c0d433a3c3e','ba52d42a-9e58-4087-b5c4-8f1b289f0f14',1,'Thiết lập khung phân tích nhu cầu người dùng trong khuôn viên trường','Thực hiện phỏng vấn nhanh 3 bạn học về khó khăn trong học tập và ghi chép thành tài liệu tóm tắt nhu cầu người dùng dài 1 trang.',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-015\"]','2026-08-31 15:54:21.000000'),('da3037f7-6756-5e11-a8d0-95e7186fb102','ed44bd5e-1a21-5d6c-ace5-db9c9dcb1c97',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"d0805143-4ac6-5b00-89ea-ecc8605788d6\"]','2026-08-25 18:07:00.000000'),('da434625-dfff-45cb-a0e9-5440552ca9f1','b9b16f87-3990-4305-93db-3ba64740b44c',3,'Học mô-đun nền tảng (Mốc 30 ngày)','Hoàn thành một mô-đun cốt lõi của ngành An toàn thông tin và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"]','2026-09-02 14:19:37.000000'),('da72cc33-31f6-4957-ad56-09a00297cfd1','b62d2179-ef23-426d-8d99-6df2eddbf493',2,'Soạn thảo bài thuyết trình định hướng bản thân','Chuẩn bị nội dung trình bày về mục tiêu phát triển học thuật và nghề nghiệp dựa trên các trải nghiệm đã tích lũy.',90,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-004\"]','2026-08-27 09:46:18.000000'),('daa5f4f7-7efa-4817-8a77-a10b5d5834d1','019beb2b-d9e0-4d8b-b4fc-1fdc03450504',3,'Thiết kế giao diện chi tiết và tạo nguyên mẫu tương tác','Ghép nối tối thiểu 8 màn hình hoàn chỉnh, tạo các hiệu ứng chuyển động và liên kết luồng để người dùng có thể thao tác trực tiếp.',120,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-014\"]','2026-08-30 18:07:57.000000'),('daccacbf-6b68-421b-ad55-20cbe2c3899b','953ac3ad-b090-4610-8f9b-78ffc14300e8',3,'Đánh giá các dự án mẫu và yêu cầu kỹ năng thực tế','Tìm hiểu 3 dự án thực tế về quản lý dữ liệu cộng đồng để hiểu rõ kỹ năng phân tích và làm việc nhóm cần chuẩn bị.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-27 08:51:04.000000'),('db436467-6953-44df-94a3-caa147e5c36b','98013504-2a10-4f13-9f50-ff758982caf6',2,'Tổng hợp sản phẩm và viết bài giới thiệu dự án','Viết tài liệu tóm tắt mục tiêu, công nghệ sử dụng và bài học rút ra từ dự án đã thực hiện.',80,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\"]','2026-09-05 03:46:02.000000'),('dbcf4361-f0cc-421d-8423-d534fd6abded','9ba56e8d-6b0f-4e02-8ce3-11d316af3e00',1,'Mốc 7 ngày: Thiết lập môi trường và kho lưu trữ Git chuẩn','Cài đặt môi trường lập trình (VS Code/IDE), cấu hình Git cá nhân và khởi tạo kho lưu trữ đồ án theo cấu trúc tiêu chuẩn (README, .gitignore, thư mục mã nguồn).',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-02 15:44:07.000000'),('dbcf9e01-4d3d-4593-b46d-e355a45c0691','4367aee4-74d0-40b0-a948-36ad425cf7df',1,'Thu thập và phân loại 5 bài nghiên cứu/case study về thiết kế tương tác','Tìm kiếm trên thư viện số hoặc các nguồn học thuật uy tín 5 bài viết tiêu biểu liên quan đến trải nghiệm số, sau đó ghi chú lại 3 điểm cốt lõi của mỗi bài vào bảng tổng hợp.',60,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-30 07:59:22.000000'),('dc197ff0-948c-4489-a816-4f8919c18585','0c66f2a1-7332-4834-8dec-244768ebde76',1,'Thiết kế sơ đồ thực thể mối quan hệ cơ sở dữ liệu (ERD)','Phân tích yêu cầu bài toán quản lý sinh viên hoặc sự kiện trường học, dựng sơ đồ ERD chuẩn hóa 3NF và viết tập lệnh SQL tạo bảng (Mốc 37 ngày).',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-05 05:50:04.000000'),('dcdbbf14-8959-40c2-a011-2eacce721ec6','eadaca9b-f2d1-43bd-8850-628621cc2b3f',3,'Tập dượt bài thuyết trình giới thiệu sản phẩm trong 10 phút (Mốc 90 ngày)','Chuẩn bị slide súc tích và tự ghi hình bài thuyết trình giới thiệu dự án để hoàn thiện kỹ năng diễn đạt tự tin, thuyết phục.',60,'self_task',NULL,NULL,'[\"evidence-015\",\"evidence-016\"]','2026-09-02 07:52:47.000000'),('dd5a05cf-586b-4d97-8a78-f535579fc488','98013504-2a10-4f13-9f50-ff758982caf6',1,'Tham dự Startup Demo Day để học hỏi cách thuyết trình dự án','Theo dõi các đội thi thuyết minh sản phẩm công nghệ để rút kinh nghiệm trình bày dự án của bản thân.',120,'register_activity','activity','31000000-0000-4000-8000-000000000012','[\"evidence-022\"]','2026-09-05 03:46:02.000000'),('ddae81f8-237e-4ba7-9dd0-e8a5ed6ca06e','1a5238c1-ecd7-44af-ac07-cc41d321c2f6',2,'Biên soạn tài liệu Case Study chi tiết cho đồ án (Mốc 85 ngày)','Trình bày toàn bộ hành trình giải quyết vấn đề từ bối cảnh, giải pháp thiết kế, mã nguồn đến kiến trúc hệ thống thành một bài viết hoàn chỉnh.',120,'self_task',NULL,NULL,'[\"evidence-006\",\"evidence-013\"]','2026-09-02 08:03:06.000000'),('ddda89f5-a48f-4b79-b81f-e8cdbbe2a91f','53e265cc-4a04-4c30-b942-4a8f4e80c1ce',1,'Mốc 37 ngày: Thiết kế lược đồ cơ sở dữ liệu và luồng xử lý ứng dụng','Vẽ sơ đồ quan hệ thực thể (ERD) cho ứng dụng quản lý nhỏ và liệt kê các điểm cuối API (RESTful endpoints) cần thiết.',75,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-02 15:44:07.000000'),('dea80560-a604-5206-a3da-da004699d767','62a1d2cd-97e8-51d8-a485-164040409753',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"a868192f-e472-5c04-a024-deac7b0e3801\"]','2026-08-25 19:03:00.000000'),('dfa1ab40-5013-40b6-957d-8340922aec59','6ff93b0d-4f36-4126-96ba-cf4bc10a8a9b',2,'Đăng ký tham gia AI Hacklab để ứng dụng công nghệ mới','Ghi danh tham gia hoạt động AI Hacklab tại Innovation Lab FPT nhằm khám phá cách tích hợp AI vào giải pháp giao diện sản phẩm số.',45,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-036\"]','2026-08-31 04:21:44.000000'),('e0076421-f072-5d5c-a9d5-177ff83372cf','ea5dab52-172f-5073-b8e4-67764afa44cb',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"d37b7333-f866-5edc-a6ce-52d5244f5d2f\"]','2026-08-25 18:28:00.000000'),('e02b9cb8-f552-4006-90ea-f9e55d5ab1fb','02ef1cd1-76e8-47cd-a6c4-c4e65046340e',1,'Khởi tạo môi trường phát triển và chuẩn hóa quy trình Git (Mốc 7 ngày)','Cài đặt và thiết lập bộ công cụ lập trình, tạo kho lưu trữ GitHub và cấu hình file README mẫu theo chuẩn kỹ thuật chuyên nghiệp.',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\"]','2026-09-04 14:26:53.000000'),('e03c72c4-dbbc-46b2-9229-ec2ceab6fc70','c664f29e-520b-4182-b86b-2eae53ebcf6d',3,'Đánh giá tiến độ học tập và rà soát thói quen (Mốc 30 ngày)','Thực hiện buổi tự đánh giá cuối tháng 1: tổng hợp số giờ học tự chủ, tỷ lệ nộp bài đúng hạn và ghi nhận 2 điểm cần tối ưu trong quản lý thời gian. Đầu ra là phiếu tổng kết phản tư 1 trang.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-04 16:07:41.000000'),('e136dd7f-2fd5-5cec-b085-81ff23aa32a8','46f2906f-8db9-57b5-9e1d-d53e23d5557f',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"66d7b289-9cbf-518d-9108-42c56aa01aba\"]','2026-08-25 18:49:00.000000'),('e163b3f4-f9a8-41e5-8cc5-3e0c39bdbf57','0932d3f6-e190-4530-8324-595793ce686c',3,'Tạo hồ sơ năng lực học tập số (Digital Portfolio)','Tổng hợp các bài tập lớn, chứng nhận hoạt động ngoại khóa và dự án demo vào trang web cá nhân trong 90 phút.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-016\",\"evidence-017\"]','2026-09-05 02:49:36.000000'),('e1e91292-4319-447c-9877-8d962bacafe0','239fc4ad-162d-4c58-b545-58509dbc81cc',1,'Mốc Ngày 7: Khảo sát kiến trúc và chuẩn bị môi trường phát triển','Cài đặt môi trường lập trình chuẩn, khởi tạo kho lưu trữ Git cá nhân và lập danh sách 5 thư viện cốt lõi cho ứng dụng web/phần mềm. Tiêu chí hoàn thành: Kho mã nguồn sẵn sàng trên GitHub kèm tệp README mô tả cấu hình chi tiết.',60,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-005\",\"evidence-007\"]','2026-09-05 05:33:43.000000'),('e385ed80-9e3d-4710-8766-038507def98a','b538408d-9381-4851-bcf1-02999402d515',3,'Tổng kết và cập nhật lộ trình phát triển kỳ tới','Đánh giá các kỹ năng đã cải thiện và vạch ra các môn học tự chọn cần ưu tiên.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-003\",\"evidence-004\"]','2026-08-28 06:08:16.000000'),('e38a2ea3-39d5-43c1-98b1-d17096fb6ec7','ed6b069b-cd3a-4d0f-abbc-f014b1a9538f',2,'Thực hiện buổi họp đánh giá giữa kỳ và lắng nghe phản hồi (Mốc 45 ngày)','Chủ trì hoặc tham gia tích cực buổi thảo luận nhóm 30 phút, ghi nhận ý kiến đóng góp về phương pháp làm việc; tiêu chí hoàn thành là biên bản họp có 3 hành động cải tiến cụ thể.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-28 08:10:24.000000'),('e39b863c-9d68-4541-b3f2-ed1dbfbba197','c0ed31aa-73f0-44dc-a302-6b6a53b4fe26',3,'Hoàn thiện hồ sơ năng lực và kế hoạch phát triển cá nhân (Mốc 90 ngày)','Tổng hợp các sản phẩm đã đạt được trong 3 giai đoạn vào một portfolio học tập điện tử và đặt mục tiêu cho học kỳ tiếp theo.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-015\",\"evidence-016\"]','2026-09-05 07:49:00.000000'),('e3c48868-f6af-4045-bc08-37a46d972bf9','4df97144-ba80-48dc-b8dd-e1ee32ec1da0',2,'Hệ thống hóa tài liệu học tập theo chuyên đề','Phân loại, sắp xếp lại toàn bộ tài liệu các môn học chính theo danh mục logic để tra cứu nhanh chóng và chính xác.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-27 09:09:29.000000'),('e3d65b3a-3158-43cb-af2a-a9f671c1e74f','be691e0d-403d-43f0-98af-fdc971d08990',3,'Đăng ký tham gia sự kiện chuyên môn AI Hacklab','Đăng ký tham gia hoạt động AI Hacklab để mở rộng góc nhìn công nghệ ứng dụng và học hỏi cách tích hợp trí tuệ nhân tạo vào sản phẩm. Tiêu chí hoàn thành là xác nhận đăng ký thành công qua hệ thống hoạt động.',45,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-030\"]','2026-08-30 06:51:26.000000'),('e5910724-7210-4dba-8b9e-2612756c0ae0','9ba56e8d-6b0f-4e02-8ce3-11d316af3e00',2,'Mốc 14 ngày: Giải quyết bộ bài toán cấu trúc dữ liệu và thuật toán cơ bản','Lựa chọn và giải quyết 5 bài tập về mảng, chuỗi và tìm kiếm/sắp xếp; viết chú thích mã nguồn rõ ràng và kiểm thử đầu vào - đầu ra.',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-02 15:44:07.000000'),('e5d6ede0-74fa-4037-9aca-10926338c7ba','ba52d42a-9e58-4087-b5c4-8f1b289f0f14',4,'Đăng ký tham gia hoạt động AI Hacklab tại trường','Điền thông tin và nộp đơn đăng ký tham gia chương trình AI Hacklab để tiếp cận các công cụ trí tuệ nhân tạo phục vụ học tập.',30,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-037\"]','2026-08-31 15:54:21.000000'),('e6d93e20-cbda-4861-a6fc-a7b13af664ec','9cba4dc2-dd9a-4453-baae-1f5db58d4515',1,'Ghi danh tham gia Product Sprint Xây dựng Sản phẩm Số','Đăng ký tham gia hoạt động Product Sprint tại Product Lab FPT để tiếp cận quy trình kiến tạo giải pháp số nhanh trong 90 phút.',90,'register_activity','activity','31000000-0000-4000-8000-000000000010','[\"evidence-014\",\"evidence-020\"]','2026-09-05 02:49:36.000000'),('e77e4537-7e1b-4570-ae15-6ad7bbbd3d8b','e4f72bc1-3839-48dd-b86c-1fddadfd0396',1,'Tổng hợp kiến thức bằng sơ đồ tư duy trực quan','Xây dựng sơ đồ tư duy cho 3 chủ đề kiến thức quan trọng nhằm liên kết khái niệm logic và tăng cường khả năng ghi nhớ.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 09:09:29.000000'),('e7db47b0-3238-4ec6-8e53-e3052916c081','019beb2b-d9e0-4d8b-b4fc-1fdc03450504',1,'Tham gia hoạt động AI Hacklab ứng dụng trí tuệ nhân tạo','Đăng ký tham dự chương trình AI Hacklab để nghiên cứu cách tích hợp tính năng AI vào nâng cao trải nghiệm ứng dụng.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-036\"]','2026-08-30 18:07:57.000000'),('e7e1dffe-6997-4a9d-9948-20f977f30068','360aa0a7-4a60-47a8-9f93-ade52750f15c',1,'Thiết kế kiến trúc cơ sở dữ liệu và giao diện sơ bộ','Vẽ sơ đồ thực thể mối quan hệ (ERD) cho ứng dụng quản lý nhiệm vụ và phác thảo giao diện người dùng đơn giản đáp ứng đầy đủ tính năng CRUD (hoàn thành trước mốc 40 ngày).',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-05 09:58:29.000000'),('e820b7a4-a0ab-42e2-bf54-484206887b85','c325adb9-ffd5-4803-bf29-5c74ecec1b98',3,'Tổng kết 90 ngày và lập kế hoạch kỳ tiếp theo (Mốc 90 ngày)','Tự đánh giá theo các chỉ số tiến bộ, viết 3 bài học kinh nghiệm và đặt mục tiêu rèn luyện cho học kỳ mới.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:20:33.000000'),('e90b2a9f-00c5-4eec-94cc-52e6a1c62092','f96f949b-aa13-4c41-9342-a5d505219893',2,'Thu thập và phân tích tài liệu chuyên khảo nhập môn (Mốc 14 ngày)','Tìm kiếm và đọc 3 bài viết học thuật hoặc tài liệu ngành, ghi chú lại 5 khái niệm cốt lõi theo dạng sơ đồ tư duy trực quan.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:59:48.000000'),('e959e112-23b3-4c3b-a0d8-39e7e71eb727','cbe6c769-32ba-45b4-a961-bce09427bc07',1,'Soạn thảo bài trình bày kết quả học tập dự án','Thiết kế các slide trực quan trình bày kết quả và bài học rút ra từ giai đoạn thực hành.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 02:38:47.000000'),('e969ccb4-5914-4c6d-be56-11752cbc0eb9','0b3fae6f-f0e4-4b2d-af60-a0464c9cfd10',3,'Xây dựng Kế hoạch Hành động Tương lai tại Mốc 90 Ngày','Viết bài tự phản tư 500 từ về chặng đường 90 ngày vừa qua và xác lập 3 ưu tiên cốt lõi cho học kỳ cuối lớp 12 và mục tiêu xét tuyển.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-31 15:26:24.000000'),('e9e36fb9-3b8f-54c2-bd07-6e6ffead3f80','75699170-9919-5861-95e5-c746f100077e',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"4ca68f30-7db2-5d35-b902-de72dbb99424\"]','2026-08-25 18:56:00.000000'),('e9e6686a-a0a3-495e-be7d-f6ab4adb8eba','98013504-2a10-4f13-9f50-ff758982caf6',3,'Cập nhật và hoàn thiện hồ sơ Portfolio cá nhân','Đưa các liên kết mã nguồn và bản demo vào Portfolio trực tuyến sẵn sàng cho việc tìm kiếm cơ hội thực tập.',60,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-014\"]','2026-09-05 03:46:02.000000'),('ea6685f3-ba95-4fd0-9427-c5e3b6218206','d931ff41-05f7-403b-bf98-8bc5ce4eaffe',1,'Khảo sát thực trạng và định hình bài toán nhóm (Mốc 40 ngày)','Cùng nhóm học tập thảo luận, phỏng vấn nhanh 5 sinh viên khác để xác định một vấn đề thực tế trong môi trường học đường cần cải thiện.',90,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-30 07:59:48.000000'),('ea86bce1-cc0b-4436-af7d-791073d7cfe2','2cdfe31b-f850-46f2-99c5-58ceac1b7426',2,'Xây dựng trang portfolio học tập trực tuyến (Mốc 85 ngày)','Tạo trang lưu trữ dự án cá nhân (sử dụng nền tảng tạo trang web miễn phí), trình bày các bài tập, thiết kế và đúc kết kinh nghiệm từ đầu năm học. Tiêu chí hoàn thành: Đường dẫn portfolio công khai chứa ít nhất 2 sản phẩm hoàn thiện.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-30 07:09:49.000000'),('eb9d7e9e-acf1-42da-895e-7780486e756f','ba52d42a-9e58-4087-b5c4-8f1b289f0f14',3,'Thống nhất quy tắc làm việc và phân chia nhiệm vụ với nhóm bạn','Tổ chức một buổi trao đổi 45 phút cùng nhóm học tập để chia nhỏ các đầu việc cho đồ án môn học và lập bảng tiến độ theo dõi.',45,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-017\"]','2026-08-31 15:54:21.000000'),('eba14831-7b58-5abf-b38c-cf9a7f736b03','b4edf7c5-b74f-5222-a16e-0c8e726396aa',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"5d430ff3-d899-5704-9407-aa82f06eca77\"]','2026-08-25 18:14:00.000000'),('ebb9a9a3-bccb-44e6-a0aa-fd06fd3dceeb','699286a4-e746-445e-a882-57cb48a429b7',2,'Tham gia hoạt động AI Hacklab tại Innovation Lab (Mốc 14 ngày)','Đăng ký và tham dự buổi thảo luận ứng dụng AI để nắm bắt xu hướng công nghệ bổ trợ cho thiết kế sản phẩm.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-030\"]','2026-08-29 06:44:00.000000'),('ec824101-b703-42ca-895d-e8ce752e6348','f025c58a-772d-47b9-8c7c-8b0ce8e2c6b1',1,'Tổng hợp danh mục sản phẩm học tập và bài tập lớn','Thu thập toàn bộ bài tập lớn, mã nguồn hoặc bài luận đã thực hiện trong 60 ngày qua vào một thư mục lưu trữ có cấu trúc rõ ràng.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-08-28 07:43:33.000000'),('eca15983-e9d6-56b2-a212-fb4ced13d04c','e8deed02-a869-565a-afdc-d8df35b44c51',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"45ff8540-1493-5a64-a787-f5643550fe4c\"]','2026-08-25 18:56:00.000000'),('ed20fa54-77d5-4bc1-aee4-12e0c22249a6','7c8e34a3-fc57-4490-8be7-548474d5ef03',2,'Chuẩn bị CV định hướng (Mốc 90 ngày)','Điều chỉnh CV cho vị trí Kỹ sư an toàn thông tin và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"c6c194fc-96f3-5783-8c4a-b8a927485a3e\"]','2026-09-02 14:19:37.000000'),('eda6f82c-b6e9-4aa8-9d17-7efa4bc50eda','a6c50441-9d9f-4757-a7a9-91af98b27b02',2,'Soạn thảo tài liệu kỹ thuật và cẩm nang hướng dẫn triển khai','Viết tài liệu tổng kết kiến trúc hệ thống, hướng dẫn cài đặt từng bước và các lưu ý vận hành để người khác có thể chạy lại đồ án dễ dàng.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-005\"]','2026-09-04 15:00:27.000000'),('edcf805c-68dd-45b6-89a8-938a6da74654','5eaae2d8-e7c6-484d-a023-1c6ae0208820',3,'Tổng kết nhật ký học tập và lập kế hoạch rèn luyện cho kỳ học tiếp theo','Viết bài thu hoạch 500 từ đánh giá sự tiến bộ trong kỹ năng điều phối nhóm, tư duy giải pháp và xác định 2 mục tiêu rèn luyện trọng tâm cho kỳ học mới.',60,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-014\",\"evidence-016\"]','2026-09-05 08:20:23.000000'),('ee6c51bf-bb53-41a4-95da-057e0f6babde','a85b6430-56f8-4b81-ab82-69f2cd32ff76',2,'Phát thảo mô hình giải pháp dạng trực quan (Mốc 50 ngày)','Sử dụng công cụ thiết kế cơ bản để vẽ wireframe hoặc sơ đồ quy trình giải quyết vấn đề đã khảo sát.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:34:53.000000'),('ee732e77-514e-4766-8174-340c2a5ded22','5b814882-6b95-4d23-b896-3b367a479c6b',2,'Thực hiện bài tập phân tích logic và thiết kế luồng dữ liệu','Vẽ sơ đồ luồng dữ liệu cho một chức năng xử lý nghiệp vụ của đồ án lớp học; tiêu chí hoàn thành là sơ đồ thể hiện đầy đủ các trường dữ liệu và trường hợp xử lý ngoại lệ.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-007\"]','2026-09-05 09:46:28.000000'),('ef595c3c-fac6-50fd-8c7d-dab6fee60e4b','4231e2d1-384b-5885-8433-9f91dd68c3e7',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Kỹ sư an toàn thông tin và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"c6c194fc-96f3-5783-8c4a-b8a927485a3e\"]','2026-08-25 18:35:00.000000'),('ef9ee1b3-3b61-471f-8713-adf308d74063','af98ae9e-f825-406b-b251-c9f234dabcad',2,'Thiết lập quy trình chuẩn Git Workflow và quản lý dự án học tập (Mốc 14 ngày)','Tạo một kho lưu trữ cá nhân trên GitHub, cấu hình quy tắc phân nhánh (branching strategy), viết tài liệu hướng dẫn đóng góp và thực hành tạo pull request chuẩn.',60,'self_task',NULL,NULL,'[\"evidence-005\",\"evidence-012\"]','2026-09-05 05:53:02.000000'),('efaf7746-ed88-437e-a83b-2da0c91fa771','552778f1-95a1-4389-8413-bee5e2627334',3,'Tổng hợp tài liệu nguyên tắc viết mã sạch (Clean Code Checklist)','Đọc tài liệu quy chuẩn đặt tên biến, tách hàm và xử lý ngoại lệ; áp dụng để refactor lại mã nguồn của một bài tập lớn trên lớp (Mốc 30 ngày).',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\",\"evidence-012\"]','2026-09-05 05:50:04.000000'),('efcc9b98-e983-4ac8-baf1-a76b550747eb','552778f1-95a1-4389-8413-bee5e2627334',2,'Giải quyết chuỗi 10 bài tập cấu trúc dữ liệu cơ bản','Lựa chọn và tự thực hiện 10 bài tập về mảng, chuỗi và danh sách liên kết; ghi chú phân tích độ phức tạp thời gian O(n) cho từng bài (Mốc 14 ngày).',90,'self_task',NULL,NULL,'[\"evidence-004\",\"evidence-007\"]','2026-09-05 05:50:04.000000'),('f01f0072-9e8c-4ad9-8a26-6481b8d0e6c8','239fc4ad-162d-4c58-b545-58509dbc81cc',2,'Mốc Ngày 14: Phác thảo sơ đồ dữ liệu và thiết kế luồng xử lý','Vẽ sơ đồ luồng dữ liệu (Data Flow Diagram) và mô hình thực thể (ERD) cho bài toán quản lý thông tin học tập. Tiêu chí hoàn thành: Bản vẽ ERD chuẩn hóa tối thiểu 4 bảng quan hệ và tài liệu mô tả luồng logic hoàn tất.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\",\"evidence-007\"]','2026-09-05 05:33:43.000000'),('f068922e-2dcf-4c1d-8185-4d88fb4b0d62','fc6693fd-6091-458d-bbf3-4c8347a87745',2,'Thực hiện buổi phỏng vấn thu nhận phản hồi người dùng','Mời bạn học trải nghiệm bản mẫu, thực hành đặt câu hỏi mở và lắng nghe phản hồi cải tiến mà không phán xét.',90,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 05:09:11.000000'),('f0746c07-9b62-4547-86a1-63508dece761','77528e34-67c6-4271-bb5c-e7a4a9e48834',1,'Khảo sát và lập bảng đối chiếu trải nghiệm học tập số (Mốc 7 ngày)','Thực hiện khảo sát 5 bạn cùng lớp về trải nghiệm sử dụng cổng thông tin sinh viên, ghi nhận 3 điểm nghẽn và tổng hợp thành bảng báo cáo ngắn gọn (1 trang A4).',60,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-014\",\"evidence-015\"]','2026-09-02 08:08:52.000000'),('f076a09f-dbe9-5308-a73b-a9191862b33c','ed44bd5e-1a21-5d6c-ace5-db9c9dcb1c97',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"b11e33bd-a90b-5bb6-8fd3-37958b03358c\"]','2026-08-25 18:07:00.000000'),('f0e0ca62-64e7-4895-bc55-4b38e8b1046d','24b17946-5242-47c0-8827-063fdead4de3',3,'Xuất bản Portfolio cá nhân trên nền tảng trực tuyến','Đưa bài Case Study và các hình ảnh mockup trực quan lên trang cá nhân hoặc nền tảng lưu trữ sản phẩm thiết kế.',90,'self_task',NULL,NULL,'[\"evidence-013\",\"evidence-016\"]','2026-08-30 18:07:57.000000'),('f15f86fb-9ace-5898-aae7-70ff8166aa0d','ea5dab52-172f-5073-b8e4-67764afa44cb',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Chuyên viên chiến lược nội dung số.',75,'self_task',NULL,NULL,'[\"4a9e19f3-bd3a-538b-9bee-713ac6369e59\"]','2026-08-25 18:28:00.000000'),('f1faa390-0198-48e6-9720-d5b65ad1add6','a327fb28-29e7-4302-8ef2-f8422c64c8f0',2,'Phát thảo mô hình giải pháp dạng trực quan (Mốc 50 ngày)','Sử dụng công cụ thiết kế cơ bản để vẽ wireframe hoặc sơ đồ quy trình giải quyết vấn đề đã khảo sát.',110,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:23:47.000000'),('f297e95c-781b-4b78-80ce-da068d1879bd','e4f35577-dce5-44e7-bb81-00857cf20bfe',2,'Hệ thống hóa tài liệu môn học cơ sở','Phân loại và tóm tắt các khái niệm nền tảng của các môn kỹ thuật/logic đang theo học.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-28 06:08:16.000000'),('f34b10a5-e511-5f8f-a648-83de1089fcb4','0cd7474b-0a25-5568-91fe-5def493e832e',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"bcb6d9fe-4413-57fb-959c-211a2e17777a\"]','2026-08-25 19:10:00.000000'),('f38ae6e6-82ef-48c0-b925-e4ffb7502a1b','a6370bba-24f5-44f4-8f75-c1a12c9ea2e9',3,'Phân tích 3 bài toán ứng dụng số trong đời sống sinh viên','Tổng hợp tài liệu và ghi nhận các vấn đề sinh viên thường gặp trên campus để hình thành ý tưởng giải pháp số ban đầu.',90,'self_task',NULL,NULL,'[\"evidence-010\",\"evidence-015\"]','2026-09-05 03:19:52.000000'),('f399694d-56eb-4739-ac28-6b6b4456444b','c5ac9ad1-1356-44d7-b5e7-27fe90b70e2d',2,'Kiểm tra bảo mật và tối ưu hóa tốc độ tải trang','Thực hiện rà soát các lỗ hổng cơ bản (SQL Injection, XSS), cấu hình biến môi trường an toàn và đo lường điểm hiệu năng trang web qua công cụ phân tích.',75,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-037\",\"evidence-038\"]','2026-09-05 05:46:35.000000'),('f3a83eaa-d289-4caa-98ac-57a911ddee8c','d17d7a2a-d8e7-45a6-85bc-b6ca55eff2c9',3,'Hoàn thiện bản đồ kiến thức tổng hợp giai đoạn 1 (Mốc 30 ngày)','Tổng hợp toàn bộ nội dung đã học thành một trang infographic hoặc mindmap chi tiết, tự đánh giá mức độ hiểu bài đạt trên 80%.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:20:33.000000'),('f4d718c2-4c7b-4067-bf3b-def7fbcd3243','0528be3b-2412-436f-a8ae-4981d9c68ed4',2,'Thiết kế bộ slide thuyết trình dự án trực quan và súc tích (Mốc 75 ngày)','Xây dựng 10-12 slide trình chiếu tập trung vào điểm nhấn trực quan, số liệu khảo sát và giải pháp cốt lõi để chuẩn bị báo cáo.',75,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-004\"]','2026-08-30 07:59:22.000000'),('f552b182-7d27-46c3-b817-8b620fc48a66','c2cc7c54-7026-4c2d-b1a4-150f36f869b1',3,'Đăng ký tham gia hoạt động AI Hacklab để mở rộng góc nhìn công nghệ (Mốc 30 ngày)','Ghi danh tham gia hoạt động AI Hacklab tại Innovation Lab nhằm cọ xát kiến thức thực tế và kết nối cùng cộng đồng học thuật.',120,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-037\"]','2026-08-31 15:59:36.000000'),('f657d625-50b1-57c8-8290-c99859045bf5','b4edf7c5-b74f-5222-a16e-0c8e726396aa',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Nhà thiết kế trải nghiệm số và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"cdeac990-f872-5d28-921d-6904910ed8ed\"]','2026-08-25 18:14:00.000000'),('f699d296-15dd-55e3-9265-2afac5ef9b16','2955d13d-14e2-5300-b4fb-5b708e5499b3',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Chuyên viên chiến lược nội dung số và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"ee93d485-4487-5750-81e1-cd8093b0dde0\"]','2026-08-25 18:28:00.000000'),('f6b3c7d6-8473-4ecb-bda2-b0113b7c7446','99abd075-f415-4eb2-80c9-ba1a663700ce',1,'Thiết lập bảng kế hoạch học tập và quản lý thời gian 30 ngày (Mốc 7 ngày)','Lập thời khóa biểu chi tiết kết hợp lịch học và tự học trên công cụ số, phân bổ ít nhất 6 khung giờ học tập cố định trong tuần.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-09-02 14:15:57.000000'),('f6cb127b-1752-4a9e-8d87-8931edd7e55f','db099061-603f-420f-94ab-9ef2bff4a708',3,'Đánh giá mức độ ưu tiên giữa các nhiệm vụ','Lập danh sách các việc cần làm theo mức độ khẩn cấp và quan trọng để tối ưu hóa thời gian hàng ngày.',45,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 09:02:35.000000'),('f760cf25-0ca9-4565-a6fa-2bcaa9b1d404','792554d3-3b4e-4aea-9c52-45bae3b401df',2,'Mốc 75 ngày: Tự động hóa triển khai ứng dụng lên nền tảng đám mây','Cấu hình quy trình triển khai ứng dụng tự động (CI/CD cơ bản) hoặc đưa mã nguồn lên dịch vụ lưu trữ đám mây công cộng.',105,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-038\"]','2026-09-02 15:44:07.000000'),('f77a5abc-f4f5-4d5a-a939-1bdbc1bfcbbf','ed6446ed-1aa2-4583-b3f3-d337047e57cc',3,'Mốc Ngày 60: Đánh giá chéo mã nguồn và tối ưu hiệu năng','Thực hiện rà soát mã nguồn (code review) cùng bạn học, tối ưu thời gian phản hồi của truy vấn dữ liệu và chuẩn hóa tài liệu kỹ thuật. Tiêu chí hoàn thành: Giảm độ trễ xử lý dữ liệu và nhận ít nhất 2 phản hồi cải thiện chất lượng mã nguồn.',75,'self_task',NULL,NULL,'[\"evidence-003\",\"evidence-006\",\"evidence-012\"]','2026-09-05 05:33:43.000000'),('f819d2b4-eb5a-42c9-bcfc-8b7551e97293','24b17946-5242-47c0-8827-063fdead4de3',1,'Phân tích và đo lường số liệu chuyển đổi của bản thiết kế','Xây dựng bảng chỉ số đánh giá hiệu quả trải nghiệm (tỷ lệ hoàn thành tác vụ, thời gian tương tác) dựa trên dữ liệu thử nghiệm.',60,'self_task',NULL,NULL,'[\"evidence-018\",\"evidence-027\"]','2026-08-30 18:07:57.000000'),('f837a7a5-e405-4c21-80ca-ee54097201f7','6c120050-75da-4589-9a23-695ba8c2c87a',1,'Xây dựng khung giao diện wireframe chi tiết (Mốc 40 ngày)','Sử dụng công cụ thiết kế chuyên dụng để tạo dựng luồng người dùng từ trang chủ đến các tính năng chính của giải pháp đã chọn.',90,'self_task',NULL,NULL,'[\"evidence-008\",\"evidence-014\"]','2026-08-29 06:44:00.000000'),('f85c01b6-89be-45bc-a19e-fa5d23571ba1','e4f35577-dce5-44e7-bb81-00857cf20bfe',1,'Lập ma trận mục tiêu học tập theo tuần','Xây dựng bảng biểu phân bổ thời gian học tập, thực hành bài tập và tự nghiên cứu tài liệu chuyên ngành.',60,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-28 06:08:16.000000'),('f8cc11d9-f733-449f-9ae7-d500226db9c0','6388e0d2-9357-48e6-8934-beabd0dc99ee',2,'Thực thi và kiểm thử sản phẩm dự án nhỏ','Thực hiện các bước kỹ thuật/nội dung theo kế hoạch đã lập, tiến hành rà soát lỗi và tối ưu hóa tính năng của sản phẩm học tập. Đầu ra là sản phẩm hoàn thiện bản thử nghiệm.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-04 16:07:41.000000'),('f979af5c-c683-4548-8824-140aa743e83e','77528e34-67c6-4271-bb5c-e7a4a9e48834',2,'Phác thảo sơ đồ luồng người dùng và khung giao diện mẫu (Mốc 14 ngày)','Vẽ sơ đồ wireframe trên công cụ thiết kế trực tuyến cho tính năng đặt lịch học nhóm hoặc mượn tài liệu học tập, bao gồm tối thiểu 4 màn hình chính.',90,'self_task',NULL,NULL,'[\"evidence-007\",\"evidence-010\",\"evidence-014\"]','2026-09-02 08:08:52.000000'),('f98f1b5e-b7f0-45f1-93ab-ab737e0c53f9','4886d51a-3099-4264-9a54-bbb54b0012eb',1,'Biên tập hồ sơ nghiên cứu dự án (Case Study)','Tập hợp toàn bộ quá trình nghiên cứu, sơ đồ, bản mẫu và kết quả kiểm thử thành một bài viết mạch lạc.',180,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:09:11.000000'),('facbdd2a-13c9-42a7-8a54-c52953036624','bcac4fd9-9dc0-4ce3-84b4-567946972391',2,'Lập chiến lược ôn tập và nộp hồ sơ xét tuyển','Chi tiết hóa các mốc thời gian ôn thi, chỉ tiêu xét tuyển của các trường mục tiêu và yêu cầu đầu vào.',80,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-27 08:51:04.000000'),('fb378c0a-2d79-4260-ba6a-2a9143bef0ea','7f6856fe-b940-4f8e-9f4e-a906c3e0562b',3,'Viết báo cáo phân tích và đúc kết kinh nghiệm','Trình bày các phát hiện chính từ số liệu thành một báo cáo súc tích kèm theo các giải pháp tối ưu hóa thời gian biểu.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-27 09:46:18.000000'),('fc44041c-c26d-57e4-8715-180664faa7ec','2ecf4e0b-fece-5678-b5ba-a22384cd5633',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Kỹ sư phần mềm backend.',75,'self_task',NULL,NULL,'[\"66bff28d-df5e-5dd0-9706-2b4281e9263b\"]','2026-08-25 18:07:00.000000'),('fc554b90-1a9d-4c7e-baa6-c7b0d34992c4','33251f2f-216b-4dc8-9121-d3583a53d4bd',1,'Đăng ký tham gia thử nghiệm tại AI Hacklab FPT','Ghi danh tham gia hoạt động AI Hacklab tại Innovation Lab để tiếp cận các mô hình công nghệ mới và tích hợp vào ý tưởng sản phẩm.',60,'register_activity','activity','31000000-0000-4000-8000-000000000009','[\"evidence-002\",\"evidence-013\",\"evidence-037\"]','2026-09-02 08:08:52.000000'),('fc627543-8aa7-4c1d-b917-4bbf068df609','5ae07e3b-d682-4615-9454-6f38bfa33e63',2,'Luyện tập phác thảo mô hình trực quan trên giấy','Vẽ lại cấu trúc bố cục và sơ đồ tương tác của sản phẩm vừa nghiên cứu bằng hình vẽ trực quan.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-26 05:09:11.000000'),('fcc626b5-b52f-4373-a0c7-245f868975e2','d9f63493-3fb5-4a40-ab60-759adca151da',1,'Chọn phản hồi ưu tiên','Phân loại phản hồi và chọn một thay đổi quan trọng.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 03:26:09.000000'),('fcfd0106-d110-4349-9af4-3fc543ed5de7','ebc97266-1916-4647-8128-369d6883ca37',2,'Thiết kế và xuất bản Portfolio số (Mốc 85 ngày)','Tạo trang cá nhân trực tuyến giới thiệu kỹ năng, dự án đã làm và định hướng phát triển học thuật.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:15:57.000000'),('fcfec24e-f9b4-453e-97f6-06c3f9b2a71b','a5237557-bf50-4b12-834a-8851191222ba',3,'Mốc ngày 60: Thực hiện phiên thử nghiệm người dùng và lập báo cáo cải tiến','Tổ chức buổi thử nghiệm với 3 thành viên trong nhóm học tập, ghi nhận các lỗi tương tác và tổng hợp thành báo cáo cải tiến dài 2 trang.',90,'self_task',NULL,NULL,'[\"evidence-011\",\"evidence-017\",\"evidence-018\"]','2026-08-29 06:50:07.000000'),('fd1402fe-2ad8-4222-b3de-db8e06773eaf','51d2c08c-d654-4d7b-b77f-1ea3f868a481',4,'Tự động hóa kiểm thử đơn vị cho các hàm logic chính','Viết bộ kiểm thử unit test bao phủ ít nhất 5 hàm tính toán/xử lý dữ liệu trọng yếu; kiểm tra tỷ lệ kiểm thử thành công đạt 100% trước khi hoàn thiện giai đoạn.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\",\"evidence-025\"]','2026-09-05 05:46:35.000000'),('fd45e466-365d-5a77-b21a-cbc7a5208f21','e3a7d34a-7fa3-51ef-84f8-88380c976784',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"6fc19e75-06c9-5d2b-9740-7b8c7bf109c8\"]','2026-08-25 18:42:00.000000'),('fdead2e7-59f0-49e2-aa89-3ba2ba61a112','99abd075-f415-4eb2-80c9-ba1a663700ce',3,'Hoàn thiện bản đồ kiến thức tổng hợp giai đoạn 1 (Mốc 30 ngày)','Tổng hợp toàn bộ nội dung đã học thành một trang infographic hoặc mindmap chi tiết, tự đánh giá mức độ hiểu bài đạt trên 80%.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-09-02 14:15:57.000000'),('fef78dcc-a2ea-45a4-a10a-79f23ea56934','6388e0d2-9357-48e6-8934-beabd0dc99ee',1,'Xây dựng đề cương dự án học thuật cá nhân','Lựa chọn một chủ đề ứng dụng thực tế gắn với môn học, lập đề cương chi tiết gồm mục tiêu, phương pháp thực hiện và lịch trình 3 tuần. Đầu ra là bản đề cương dự án 2 trang.',60,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\"]','2026-09-04 16:07:41.000000'),('fef8f338-4690-457d-9e2e-2268024e7b87','8a1de756-43cd-45d5-8aac-5a270a7d748a',3,'Nhận đánh giá cuối kỳ','Xin nhận xét có cấu trúc và chọn mục tiêu tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 05:08:36.000000'),('ff7026bd-c8fa-4a00-bed9-7df085781486','f9b3d0ce-b031-4d26-b8f3-6f13ba9eb20f',1,'Phác thảo khung bố cục (wireframe) cho 5 màn hình chính của ứng dụng','Vẽ phác thảo chi tiết bố cục, phân cấp thông tin và luồng thao tác của người dùng trên giấy hoặc phần mềm thiết kế chuyên dụng.',90,'self_task',NULL,NULL,'[\"evidence-004\"]','2026-08-30 07:59:22.000000');
