CREATE TABLE `learner_ai_roadmaps` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `runId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `versionNumber` int unsigned NOT NULL,
  `contractVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `executiveSummary` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `primaryDirectionJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `alternativeDirectionsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `insightsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidenceBand` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidenceSummaryJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `providerRequestId` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `responseHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `generatedAt` datetime(6) NOT NULL,
  `supersededAt` datetime(6) DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `freshness_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `stale_since` datetime DEFAULT NULL,
  `last_refresh_error` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `next_retry_at` datetime DEFAULT NULL,
  `model_version` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `snapshot_hash` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `refresh_job_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_roadmaps_student_version` (`studentId`,`versionNumber`),
  UNIQUE KEY `uq_learner_ai_roadmaps_run` (`runId`),
  UNIQUE KEY `uq_learner_ai_roadmaps_id_student` (`id`,`studentId`),
  KEY `idx_learner_ai_roadmaps_student_status_generated` (`studentId`,`status`,`generatedAt`),
  CONSTRAINT `fk_learner_ai_roadmaps_run` FOREIGN KEY (`runId`) REFERENCES `learner_recommendation_runs` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_ai_roadmaps_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_roadmaps_alternatives_json` CHECK (json_valid(`alternativeDirectionsJson`)),
  CONSTRAINT `chk_learner_ai_roadmaps_confidence` CHECK ((`confidenceBand` in (_utf8mb4'low',_utf8mb4'medium',_utf8mb4'high'))),
  CONSTRAINT `chk_learner_ai_roadmaps_evidence_summary_json` CHECK (json_valid(`evidenceSummaryJson`)),
  CONSTRAINT `chk_learner_ai_roadmaps_insights_json` CHECK (json_valid(`insightsJson`)),
  CONSTRAINT `chk_learner_ai_roadmaps_primary_json` CHECK (json_valid(`primaryDirectionJson`)),
  CONSTRAINT `chk_learner_ai_roadmaps_response_hash` CHECK (((`responseHash` is null) or regexp_like(`responseHash`,_utf8mb4'^[a-f0-9]{64}$'))),
  CONSTRAINT `chk_learner_ai_roadmaps_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'superseded'))),
  CONSTRAINT `chk_learner_ai_roadmaps_superseded` CHECK ((((`status` = _utf8mb4'active') and (`supersededAt` is null)) or ((`status` = _utf8mb4'superseded') and (`supersededAt` is not null)))),
  CONSTRAINT `chk_learner_ai_roadmaps_version` CHECK ((`versionNumber` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
