INSERT INTO `learner_ai_roadmaps` VALUES ('02d1067b-08f8-49c6-8305-f76f73e6815a','22000000-53d8-4897-8d68-ab3f78db0ce9','943b2c16-23cb-40da-beb0-991e37ed9997',8,'learner-roadmap-1.0.0','superseded','Lộ trình phát triển 90 ngày được thiết kế riêng cho sinh viên năm nhất Đại học FPT nhằm tối ưu hóa thế mạnh tư duy logic, năng lực thiết kế sáng tạo và kỹ năng giao tiếp. Kế hoạch tập trung cân bằng giữa lịch học chính khóa và việc rèn luyện dự án thực chiến, giúp xây dựng sản phẩm số hoàn chỉnh và nâng cao kỹ năng phối hợp nhóm.','{\"code\":\"product_design_analytics\",\"label\":\"Thiết kế & Phân tích Sản phẩm Số (Product Design & Data Analytics)\",\"rationale\":\"Sự kết hợp nổi bật giữa tư duy hệ thống logic, khả năng thẩm mỹ trực quan và sự tỉ mỉ giúp bạn phát huy tối đa tiềm năng trong việc xây dựng trải nghiệm người dùng dựa trên dữ liệu thực tế.\"}','[{\"code\":\"digital_business_analysis\",\"label\":\"Phân tích Nghiệp vụ & Vận hành Số (Business Analysis & Operations)\",\"rationale\":\"Thế mạnh phân tích logic, sự chuẩn xác trong tài liệu kỹ thuật và kỹ năng giao tiếp hiệu quả tạo nền tảng vững chắc cho vai trò cầu nối giải pháp công nghệ và mô hình vận hành.\"},{\"code\":\"ai_applied_development\",\"label\":\"Phát triển Giải pháp Ứng dụng AI (Applied AI Solutions)\",\"rationale\":\"Khả năng nghiên cứu độc lập xuất sắc, thích ứng công nghệ nhanh và tư duy cấu trúc hỗ trợ đắc lực khi tiếp cận các công cụ trí tuệ nhân tạo thế hệ mới.\"}]','{\"items\":[{\"category\":\"strength\",\"title\":\"Tư duy logic cấu trúc và thẩm mỹ sáng tạo\",\"summary\":\"Bạn sở hữu năng lực phân tích vấn đề chặt chẽ, kết hợp hài hòa cùng tư duy hình ảnh và khiếu thiết kế giao diện trực quan, được thể hiện rõ qua các đánh giá đồ án học thuật xuất sắc.\",\"evidence_ref_ids\":[\"evidence-007\",\"evidence-008\",\"evidence-010\",\"evidence-013\",\"evidence-014\",\"evidence-018\"]},{\"category\":\"improvement\",\"title\":\"Nâng cao kỹ năng phối hợp và làm việc nhóm\",\"summary\":\"Dù kỹ năng giao tiếp cá nhân và năng lực lãnh đạo đạt mức cao, bạn cần mở rộng mức độ tương tác, chia sẻ tài nguyên và phân bổ công việc đồng đều hơn khi tham gia các dự án nhóm.\",\"evidence_ref_ids\":[\"evidence-009\",\"evidence-011\",\"evidence-012\",\"evidence-015\",\"evidence-016\",\"evidence-017\"]},{\"category\":\"potential\",\"title\":\"Năng lực phát triển giải pháp sản phẩm toàn diện\",\"summary\":\"Sự chủ động tích lũy trải nghiệm kỹ thuật và kinh doanh cùng khả năng hoàn thành mục tiêu học tập sớm mở ra tiềm năng lớn trong quản trị và phát triển sản phẩm công nghệ.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\",\"evidence-004\",\"evidence-006\",\"evidence-022\",\"evidence-026\",\"evidence-027\"]}],\"__ai_extended\":{\"talent_map\":[{\"field\":\"Tư duy Logic & Hệ thống\",\"score\":0.95,\"evidence_ref_ids\":[\"evidence-001\",\"evidence-008\",\"evidence-010\",\"evidence-018\",\"evidence-027\"]},{\"field\":\"Kỹ năng Thực hành & Thao tác\",\"score\":0.85,\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\",\"evidence-013\",\"evidence-014\",\"evidence-021\"]},{\"field\":\"Tổ chức & Điều phối\",\"score\":0.78,\"evidence_ref_ids\":[\"evidence-004\",\"evidence-006\",\"evidence-009\",\"evidence-015\",\"evidence-016\"]}],\"strengths\":[{\"text\":\"Khả năng phân tích hệ thống logic chặt chẽ và tiếp cận bài toán công nghệ bài bản.\",\"evidence_ref_ids\":[\"evidence-008\",\"evidence-010\",\"evidence-027\"]},{\"text\":\"Năng khiếu thẩm mỹ và tư duy thiết kế trải nghiệm người dùng trực quan, sáng tạo.\",\"evidence_ref_ids\":[\"evidence-007\",\"evidence-013\",\"evidence-014\"]}],\"improvements\":[],\"potential_paths\":[],\"trend_signals\":[{\"direction\":\"up\",\"label\":\"Tốc độ hoàn thiện năng lực tự học và phát triển sản phẩm thực tế\",\"evidence_ref_ids\":[\"evidence-022\",\"evidence-023\",\"evidence-024\",\"evidence-026\"]}],\"growth_hypotheses\":[],\"confidence\":0.9,\"evidence\":[\"evidence-001\",\"evidence-002\",\"evidence-003\",\"evidence-004\",\"evidence-005\",\"evidence-006\",\"evidence-007\",\"evidence-008\",\"evidence-009\",\"evidence-010\",\"evidence-011\",\"evidence-012\",\"evidence-013\",\"evidence-014\",\"evidence-015\",\"evidence-016\",\"evidence-017\",\"evidence-018\",\"evidence-020\",\"evidence-021\",\"evidence-022\",\"evidence-023\",\"evidence-024\",\"evidence-025\",\"evidence-026\",\"evidence-027\",\"evidence-036\",\"evidence-037\",\"evidence-043\",\"evidence-047\"]}}','high','{\"assessment_count\":4,\"skill_count\":5,\"activity_count\":2,\"evaluation_count\":6}',NULL,'88bd0556ae215c8043301a283b1078f797c255a6ee8562abde71a82884a6b437','2026-08-30 17:02:18.000000','2026-08-30 18:07:57.000000','2026-08-30 17:02:18.000000','pending',NULL,NULL,NULL,NULL,NULL,NULL),('05efe505-1157-4b30-abb8-86e1ec36dfef','54374192-fcad-4f1a-bd6d-ebdcd2bca7cc','2bfa6d08-b1f1-46ea-baa5-261add2f26b0',2,'learner-roadmap-1.0.0','active','Lộ trình phát triển được thiết kế cho học sinh lớp 12 nhằm tối ưu hóa sự kết hợp giữa tư duy nghiên cứu, kỹ năng tổ chức thực tiễn và giao tiếp xã hội trong năm học 2026-2027. Kế hoạch 90 ngày tập trung vào việc định hướng nghề nghiệp, rèn luyện kỹ năng tự học và hoàn thiện các dự án học tập thực tế.','{\"code\":\"dir_tech_mgmt\",\"label\":\"Quản lý Thông tin và Phân tích Dữ liệu Ứng dụng\",\"rationale\":\"Sự kết hợp giữa năng lực tư duy logic, tính quy chuẩn và khả năng kết nối cộng đồng giúp học viên phù hợp với các lĩnh vực giao thoa giữa công nghệ, dữ liệu và quản trị quy trình.\"}','[{\"code\":\"dir_soc_sci\",\"label\":\"Khoa học Xã hội và Nghiên cứu Ứng dụng\",\"rationale\":\"Xu hướng tương tác xã hội cao kết hợp với khả năng quan sát và điều tra tạo nền tảng thuận lợi cho các hoạt động nghiên cứu xã hội học, truyền thông hoặc khảo sát hành vi.\"},{\"code\":\"dir_edu_tech\",\"label\":\"Công nghệ Giáo dục và Điều phối Dự án\",\"rationale\":\"Thế mạnh về ngôn ngữ, tính trật tự và khả năng truyền cảm hứng hỗ trợ tốt cho việc thiết kế chương trình đào tạo và điều phối các hoạt động học tập.\"}]','{\"items\":[{\"category\":\"strength\",\"title\":\"Tư duy logic kết hợp tính kỷ luật cao\",\"summary\":\"Học viên có năng lực sắp xếp công việc khoa học, xử lý vấn đề dựa trên bằng chứng và duy trì sự nhất quán trong học tập.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\",\"evidence-004\"]},{\"category\":\"potential\",\"title\":\"Khả năng truyền đạt và kết nối thực tế\",\"summary\":\"Sự chủ động trong giao tiếp và diễn đạt ý tưởng tạo điều kiện thuận lợi để làm việc nhóm hiệu quả và dẫn dắt các sáng kiến cộng đồng.\",\"evidence_ref_ids\":[\"evidence-003\",\"evidence-004\"]},{\"category\":\"improvement\",\"title\":\"Cân bằng giữa cấu trúc chặt chẽ và sự linh hoạt\",\"summary\":\"Cần nâng cao khả năng thích ứng linh hoạt với các tình huống biến đổi nhanh và quản lý kỳ vọng cá nhân trong môi trường học tập áp lực.\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}],\"__ai_extended\":{\"talent_map\":[{\"field\":\"Tư duy phân tích và cấu trúc\",\"score\":0.85,\"evidence_ref_ids\":[\"evidence-001\",\"evidence-004\"]},{\"field\":\"Kỹ năng tổ chức và thực thi\",\"score\":0.8,\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}],\"strengths\":[{\"text\":\"Tư duy logic mạch lạc, khả năng lập kế hoạch có hệ thống và tinh thần trách nhiệm cao.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\",\"evidence-004\"]}],\"improvements\":[{\"text\":\"Phát triển khả năng thích ứng linh hoạt trước những thay đổi ngoài kế hoạch dự kiến.\",\"evidence_ref_ids\":[\"evidence-002\"]}],\"potential_paths\":[{\"label\":\"Chuyên viên Phân tích Hệ thống và Dữ liệu\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-004\"]},{\"label\":\"Điều phối viên Dự án và Quản lý Quy trình\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}],\"trend_signals\":[{\"direction\":\"up\",\"label\":\"Mức độ sẵn sàng tự định hướng học tập và nghiên cứu ứng dụng\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\"]}],\"growth_hypotheses\":[{\"text\":\"Nếu được rèn luyện thường xuyên trong môi trường làm việc theo nhóm có cấu trúc rõ ràng, học viên sẽ phát huy tối đa năng lực điều phối và phân tích.\",\"confidence\":0.85,\"evidence_ref_ids\":[\"evidence-001\",\"evidence-003\"]}],\"confidence\":0.85,\"evidence\":[\"evidence-001\",\"evidence-002\",\"evidence-003\",\"evidence-004\"]}}','high','{\"assessment_count\":4,\"skill_count\":0,\"activity_count\":0,\"evaluation_count\":0}',NULL,'ea77cadc5f6fffaced3f8f2258cbe449e81e51c5baeb759323cc6edf0f0d0ec4','2026-08-27 09:46:18.000000',NULL,'2026-08-27 09:46:18.000000','pending',NULL,NULL,NULL,NULL,NULL,NULL),('0be2b03b-0999-429e-b656-42d3cff60f07','58a43df4-0e80-4c45-84b4-1100a4521cfe','6ef820b2-e52f-4fb3-8830-8f1168f63b0a',2,'learner-roadmap-1.0.0','superseded','Lộ trình 90 ngày được thiết kế riêng cho sinh viên năm nhất nhằm phát huy thế mạnh về tư duy thực tế, khả năng tổ chức kỷ luật và năng lực hành động quyết đoán. Chương trình giúp bạn xây dựng phương pháp học tập đại học hiệu quả, rèn luyện kỹ năng giải quyết vấn đề kỹ thuật và phát triển khả năng quản lý dự án học tập một cách bài bản.','{\"code\":\"tech_project_management\",\"label\":\"Kỹ thuật ứng dụng và Quản lý dự án học tập\",\"rationale\":\"Bạn có sự kết hợp nổi bật giữa tư duy logic thực tiễn, năng lượng hành động hướng đến kết quả và phong cách làm việc ngăn nắp, rất phù hợp để điều phối các bài tập lớn kỹ thuật và dự án ứng dụng thực tế.\"}','[{\"code\":\"applied_operations\",\"label\":\"Tổ chức vận hành và Quy trình công việc\",\"rationale\":\"Năng lực sắp xếp có hệ thống cùng tinh thần trách nhiệm cao giúp bạn làm tốt vai trò thiết lập cấu trúc hoạt động trong các câu lạc bộ và nhóm học thuật.\"},{\"code\":\"commercial_execution\",\"label\":\"Phát triển dự án và Đổi mới sáng tạo\",\"rationale\":\"Sự chủ động, tính quyết đoán và khả năng truyền cảm hứng thực tế tạo tiền đề thuận lợi để phát triển các sáng kiến khởi nghiệp sinh viên.\"}]','{\"items\":[{\"category\":\"strength\",\"title\":\"Năng lực hành động và định hướng kết quả rõ ràng\",\"summary\":\"Bạn luôn chủ động, quyết đoán và tiếp cận vấn đề với tinh thần thực tế cao, giúp hoàn thành công việc đúng hạn và đạt hiệu quả tối ưu.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\",\"evidence-003\"]},{\"category\":\"improvement\",\"title\":\"Nâng cao khả năng lắng nghe và tính linh hoạt\",\"summary\":\"Cần bổ sung sự kiên nhẫn khi thu nhận các góc nhìn trái chiều trong làm việc nhóm để thích ứng linh hoạt hơn với các thay đổi bất ngờ.\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]},{\"category\":\"potential\",\"title\":\"Tư duy hệ thống và phân tích dữ liệu thực nghiệm\",\"summary\":\"Khả năng quan sát chi tiết cùng tư duy logic là nền tảng tốt để bạn nghiên cứu sâu các giải pháp công nghệ mang tính thực tiễn cao.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-004\"]}],\"__ai_extended\":{\"talent_map\":[{\"field\":\"Kỹ thuật ứng dụng & Thực thi\",\"score\":0.85,\"evidence_ref_ids\":[\"evidence-001\",\"evidence-004\"]},{\"field\":\"Tổ chức & Điều phối quy trình\",\"score\":0.8,\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}],\"strengths\":[{\"text\":\"Kỹ năng tổ chức công việc mạch lạc, tư duy thực tế và tinh thần chủ động đạt hiệu quả cao.\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\",\"evidence-003\"]}],\"improvements\":[{\"text\":\"Rèn luyện sự kiên nhẫn và linh hoạt khi đối mặt với các tình huống nhóm thay đổi kế hoạch đột xuất.\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}],\"potential_paths\":[{\"label\":\"Điều phối dự án công nghệ sinh viên\",\"evidence_ref_ids\":[\"evidence-001\",\"evidence-002\"]},{\"label\":\"Phân tích quy trình và vận hành kỹ thuật\",\"evidence_ref_ids\":[\"evidence-003\",\"evidence-004\"]}],\"trend_signals\":[{\"direction\":\"up\",\"label\":\"Mức độ tự giác và năng lực quản lý dự án học tập cá nhân\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]}],\"growth_hypotheses\":[{\"text\":\"Nếu duy trì thói quen lập kế hoạch chi tiết kết hợp với việc chủ 