--
-- Table structure for table `learner_assessment_attempt_metadata`
--

DROP TABLE IF EXISTS `learner_assessment_attempt_metadata`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_assessment_attempt_metadata` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `attemptId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `versionId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress',
  `expiresAt` datetime(6) DEFAULT NULL,
  `submittedAt` datetime(6) DEFAULT NULL,
  `inputHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_assessment_attempt_metadata_attempt` (`attemptId`),
  KEY `idx_learner_assessment_attempt_metadata_version_status` (`versionId`,`status`),
  CONSTRAINT `fk_learner_assessment_attempt_metadata_attempt` FOREIGN KEY (`attemptId`) REFERENCES `test_attempts` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_assessment_attempt_metadata_version` FOREIGN KEY (`versionId`) REFERENCES `learner_assessment_versions` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_assessment_attempt_metadata_status` CHECK ((`status` in (_utf8mb4'in_progress',_utf8mb4'submitted',_utf8mb4'expired'))),
  CONSTRAINT `chk_learner_assessment_attempt_metadata_submission` CHECK ((((`status` = _utf8mb4'submitted') and (`submittedAt` is not null) and (`inputHash` is not null)) or ((`status` <> _utf8mb4'submitted') and (`submittedAt` is null) and (`inputHash` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

