--
-- Table structure for table `learner_recommendation_audit_events`
--

DROP TABLE IF EXISTS `learner_recommendation_audit_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_recommendation_audit_events` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `runId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `requestId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `actorType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `engineMetadataJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_learner_recommendation_audit_events_student_created` (`studentId`,`createdAt`),
  KEY `idx_learner_recommendation_audit_events_run_created` (`runId`,`createdAt`),
  CONSTRAINT `fk_learner_recommendation_audit_events_run` FOREIGN KEY (`runId`) REFERENCES `learner_recommendation_runs` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_recommendation_audit_events_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_recommendation_audit_events_actor` CHECK ((`actorType` in (_utf8mb4'learner',_utf8mb4'system',_utf8mb4'service'))),
  CONSTRAINT `chk_learner_recommendation_audit_events_metadata_json` CHECK (json_valid(`engineMetadataJson`)),
  CONSTRAINT `chk_learner_recommendation_audit_events_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'completed',_utf8mb4'failed',_utf8mb4'fallback')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

