DROP TABLE IF EXISTS `learner_recommendation_evidence`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_recommendation_evidence` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `itemId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `snapshotEvidenceId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `observedAt` datetime(6) DEFAULT NULL,
  `contributionLabel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `safeValueJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_recommendation_evidence_item_source` (`itemId`,`sourceType`,`sourceId`),
  KEY `idx_learner_recommendation_evidence_source` (`sourceType`,`sourceId`),
  KEY `idx_learner_recommendation_evidence_snapshot_evidence` (`snapshotEvidenceId`),
  CONSTRAINT `fk_learner_recommendation_evidence_item` FOREIGN KEY (`itemId`) REFERENCES `learner_recommendation_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_recommendation_evidence_snapshot_evidence` FOREIGN KEY (`snapshotEvidenceId`) REFERENCES `learner_recommendation_snapshot_evidence` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_recommendation_evidence_safe_value_json` CHECK (json_valid(`safeValueJson`)),
  CONSTRAINT `chk_learner_recommendation_evidence_source_type` CHECK ((`sourceType` in (_utf8mb4'profile',_utf8mb4'skill',_utf8mb4'assessment',_utf8mb4'activity_experience',_utf8mb4'activity',_utf8mb4'evaluation',_utf8mb4'opportunity',_utf8mb4'catalog',_utf8mb4'certificate',_utf8mb4'project',_utf8mb4'achievement',_utf8mb4'badge',_utf8mb4'progress',_utf8mb4'checkin',_utf8mb4'mentor_evaluation',_utf8mb4'teacher_feedback',_utf8mb4'roadmap_feedback')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
