--
-- Table structure for table `learner_recommendation_items`
--

DROP TABLE IF EXISTS `learner_recommendation_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_recommendation_items` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `runId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `itemType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `priority` tinyint unsigned NOT NULL,
  `confidenceBand` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `actionJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `lifecycleStatus` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `catalogId` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rankPosition` int DEFAULT NULL,
  `structuredScore` int DEFAULT NULL,
  `geminiScore` int DEFAULT NULL,
  `matchScore` int DEFAULT NULL,
  `analysisJson` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `idx_learner_recommendation_items_run_lifecycle_priority` (`runId`,`lifecycleStatus`,`priority`),
  CONSTRAINT `fk_learner_recommendation_items_run` FOREIGN KEY (`runId`) REFERENCES `learner_recommendation_runs` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_recommendation_items_action_json` CHECK (json_valid(`actionJson`)),
  CONSTRAINT `chk_learner_recommendation_items_confidence` CHECK ((`confidenceBand` in (_utf8mb4'low',_utf8mb4'medium',_utf8mb4'high'))),
  CONSTRAINT `chk_learner_recommendation_items_lifecycle` CHECK ((`lifecycleStatus` in (_utf8mb4'active',_utf8mb4'superseded'))),
  CONSTRAINT `chk_learner_recommendation_items_priority` CHECK ((`priority` between 1 and 100)),
  CONSTRAINT `chk_learner_recommendation_items_type` CHECK ((`itemType` in (_utf8mb4'strength',_utf8mb4'improvement',_utf8mb4'development',_utf8mb4'activity',_utf8mb4'roadmap')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

