INSERT INTO `learner_recommendation_items` VALUES ('01e56d51-cfeb-488a-828b-c0c0ebb54c58','9b514d97-22c9-4723-bc36-48c4fd0f34c7','activity','Tham gia CLB Python & Robot Lab Nguyễn Trãi','Đăng ký tham gia hoạt động STEM lập trình Robot và Python để tiếp tục phát huy năng lực kỹ thuật.',95,'high','{\"type\":\"register_activity\",\"career_group\":\"technical\",\"activity_source_id\":\"31000000-0000-4000-8000-000000000005\",\"__ai_metadata\":{\"category\":\"career_technical\",\"catalog_id\":\"31000000-0000-4000-8000-000000000005\",\"reason\":\"Học sinh có điểm kỹ năng Python đạt 85/100 và hoạt động CLB kỹ thuật tại trường sắp đến hạn đăng ký.\",\"reason_codes\":[\"career_match\",\"deadline_soon\",\"skill_match\"]}}','active','2026-08-29 04:53:05.000000',NULL,NULL,NULL,NULL,NULL,NULL),('05beed66-2f63-43ed-8a9a-a3b4f976a202','66315ecb-28cb-4640-b8e5-b416a8d917d8','activity','Kỹ sư Kiểm thử Phần mềm Tự động (Automation QA Trainee)','Xây dựng và thực thi các kịch bản kiểm thử tự động (Automation Test) cho Web, API và Mobile bằng Selenium, Playwright, Cypress hoặc Appium; tham gia kiểm thử hiệu năng hệ thống.',1,'low','{\"catalog_id\":\"40000000-0000-4000-8000-000000000003\",\"url\":\"/app/learner/opportunity.php?type=internship&id=40000000-0000-4000-8000-000000000003\"}','superseded','2026-09-05 05:33:30.000000','40000000-0000-4000-8000-000000000003',1,29,NULL,29,'{\"analysis\":{\"catalog_id\":\"40000000-0000-4000-8000-000000000003\",\"analysis\":\"Vị trí Kỹ sư Kiểm thử Phần mềm Tự động tại FPT Software hiện chưa phù hợp với năng lực hiện tại của bạn do khoảng cách chuyên môn còn khá lớn so với benchmark tiêu chuẩn của chương trình đào tạo. So với yêu cầu đầu vào của doanh nghiệp về kiểm thử tự động, Python và Git, hồ sơ của bạn chưa ghi nhận các kỹ năng chuyên môn cũng như kinh nghiệm thực hành liên quan. Dù sở hữu nền tảng tư duy logic tốt từ bài đánh giá, bạn cần chủ động học hỏi quy trình kiểm thử phần mềm và thực hiện các dự án thực tế để cải thiện năng lực đáp ứng trong tương lai.\",\"strength_skill_codes\":[],\"gap_skill_codes\":[\"sql\",\"nodejs\",\"api_development\",\"database_design\",\"python\",\"software_testing\",\"git\",\"algorithms\"],\"gap_explanations\":[{\"skill_code\":\"sql\",\"explanation\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\"},{\"skill_code\":\"nodejs\",\"explanation\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\"},{\"skill_code\":\"api_development\",\"explanation\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\"},{\"skill_code\":\"database_design\",\"explanation\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\"},{\"skill_code\":\"python\",\"explanation\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\"},{\"skill_code\":\"software_testing\",\"explanation\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\"},{\"skill_code\":\"git\",\"explanation\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\"},{\"skill_code\":\"algorithms\",\"explanation\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\"}],\"evidence_ref_ids\":[\"opportunity:40000000-0000-4000-8000-000000000003\",\"catalog:40000000-0000-4000-8000-000000000003\"]},\"score_breakdown\":{\"skill_score\":0,\"assessment_score\":82,\"experience_score\":0,\"total_score\":29,\"tier\":\"low_fit\"},\"role\":{\"code\":\"backend_developer\",\"title\":\"Backend Developer\"},\"skill_gap\":{\"state\":\"ok\",\"role\":{\"code\":\"backend_developer\",\"title\":\"Backend Developer\"},\"match_score\":29,\"skill_readiness_score\":0,\"skills_met\":[],\"skills_missing\":[{\"code\":\"sql\",\"label\":\"SQL\",\"current_score\":0,\"target_score\":70,\"gap_score\":70,\"weight\":20,\"is_required\":true,\"impact\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\",\"evidence_refs\":[]},{\"code\":\"nodejs\",\"label\":\"Node.js\",\"current_score\":0,\"target_score\":65,\"gap_score\":65,\"weight\":20,\"is_required\":true,\"impact\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\",\"evidence_refs\":[]},{\"code\":\"api_development\",\"label\":\"Phát triển API\",\"current_score\":0,\"target_score\":70,\"gap_score\":70,\"weight\":20,\"is_required\":true,\"impact\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\",\"evidence_refs\":[]},{\"code\":\"database_design\",\"label\":\"Thiết kế cơ sở dữ liệu\",\"current_score\":0,\"target_score\":65,\"gap_score\":65,\"weight\":10,\"is_required\":true,\"impact\":\"Kỹ năng bắt buộc còn thiếu lớn, ảnh hưởng trực tiếp đến khả năng đảm nhận vị trí.\",\"evidence_refs\":[]},{\"code\":\"python\",\"label\":\"Lập trình Python\",\"current_score\":0,\"target_score\":65,\"gap_score\":65,\"weight\":15,\"is_required\":false,\"impact\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\",\"evidence_refs\":[]},{\"code\":\"software_testing\",\"label\":\"Kiểm thử phần mềm\",\"current_score\":0,\"target_score\":55,\"gap_score\":55,\"weight\":5,\"is_required\":false,\"impact\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\",\"evidence_refs\":[]},{\"code\":\"git\",\"label\":\"Git\",\"current_score\":0,\"target_score\":60,\"gap_score\":60,\"weight\":5,\"is_required\":false,\"impact\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\",\"evidence_refs\":[]},{\"code\":\"algorithms\",\"label\":\"Cấu trúc dữ liệu và giải thuật\",\"current_score\":0,\"target_score\":60,\"gap_score\":60,\"weight\":5,\"is_required\":false,\"impact\":\"Khoảng thiếu lớn ảnh hưởng rõ rệt đến mức độ phù hợp.\",\"evidence_refs\":[]}],\"unbenchmarked_skills\":[]},\"recommended_activities\":[{\"catalog_id\":\"53000000-0000-4000-8000-000000000004\",\"item_type\":\"project\",\"title\":\"CyberLab Starter — Phòng Thực hành An toàn Ứng dụng Web\",\"provider_name\":\"Cao đẳng Quốc tế BTEC FPT\",\"url\":\"/app/learner/project.php?id=53000000-0000-4000-8000-0