INSERT INTO `project_sponsorships` VALUES ('51000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003','50000000-0000-4000-8000-000000000001',20000000.00,'VND','paid','FPT Software tài trợ kinh phí nghiên cứu mô hình AI phân loại rác và thiết bị IoT.',NULL,'2026-08-26 14:08:48.344841','2026-08-31 09:44:09.907826'),('51000000-0000-4000-8000-000000000002','32000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000002',35000000.00,'VND','paid','VNG Corporation tài trợ trọn gói kinh phí đồ họa 3D và cố vấn sản phẩm game.',NULL,'2026-08-26 14:08:48.344841','2026-08-31 09:44:09.907826'),('51000000-0000-4000-8000-000000000003','32000000-0000-4000-8000-000000000003','50000000-0000-4000-8000-000000000003',15000000.00,'VND','paid','Công ty Cổ phần Sữa Việt Nam (Vinamilk) tài trợ học bổng Ươm mầm Tài năng Dinh dưỡng và Chuỗi cung ứng bền vững.',NULL,'2026-08-26 14:08:48.344841','2026-08-31 09:44:09.907826'),('51000000-0000-4000-8000-000000000004','32000000-0000-4000-8000-000000000005','50000000-0000-4000-8000-000000000004',20000000.00,'VND','paid','Viettel Cyber Security tài trợ giải pháp máy chủ kiểm thử an toàn mạng và thiết bị bảo vệ đầu cuối.',NULL,'2026-08-26 14:08:48.344841','2026-08-26 07:10:33.085580');
