--
-- Table structure for table `projects`
--

DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `projects` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `schoolId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mentorTeacherId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `fundingGoal` decimal(12,2) DEFAULT NULL,
  `fundingStatus` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `fundingReachedAt` datetime(6) DEFAULT NULL,
  `projectUrl` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `startAt` datetime(6) DEFAULT NULL,
  `endAt` datetime(6) DEFAULT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_projects_school_status` (`schoolId`,`status`),
  KEY `idx_projects_mentor` (`mentorTeacherId`),
  KEY `idx_projects_sponsorable` (`status`,`fundingGoal`),
  KEY `idx_projects_school_funding_status` (`schoolId`,`fundingStatus`),
  CONSTRAINT `fk_projects_mentor` FOREIGN KEY (`mentorTeacherId`) REFERENCES `teacher_profiles` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_projects_school` FOREIGN KEY (`schoolId`) REFERENCES `schools` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_projects_dates` CHECK (((`endAt` is null) or (`startAt` is null) or (`endAt` >= `startAt`))),
  CONSTRAINT `chk_projects_funding_goal` CHECK (((`fundingGoal` is null) or (`fundingGoal` > 0))),
  CONSTRAINT `chk_projects_funding_status` CHECK ((`fundingStatus` in (_utf8mb4'not_required',_utf8mb4'open',_utf8mb4'goal_reached'))),
  CONSTRAINT `chk_projects_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'in_progress',_utf8mb4'completed',_utf8mb4'archived')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `projects`
--

LOCK TABLES `projects` WRITE;
/*!40000 ALTER TABLE `projects` DISABLE KEYS */;
INSERT INTO `projects` VALUES ('50000000-0000-4000-8000-000000000001','da811c4f-2f74-4fdd-80b0-dd6f26109783','22000000-a084-4652-8a62-805d1613cf38','Ứng dụng AI phân loại rác & Tái chế thông minh','AI & Phần mềm','Hệ thống Computer Vision và AI Edge tích hợp thùng rác thông minh tự động nhận diện và phân loại rác hữu cơ, rác tái chế và rác vô cơ với độ chính xác trên 95%.',25000000.00,'open',NULL,'https://github.com/talenthub-demo/ai-smart-recycle','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-26 14:08:48.338256','2026-08-31 09:44:09.907440'),('50000000-0000-4000-8000-000000000002','22000000-b512-4ede-852b-f4a508f3e837','22000000-7a01-474d-8565-b769341ee9d2','Game Giáo dục 3D: Hành trình Khám phá Di sản Lịch sử','Đồ họa 3D & Đa phương tiện','Trò chơi nhập vai 3D tái hiện các di tích lịch sử và văn hóa Việt Nam trên nền tảng Unity/Unreal Engine, giúp học sinh trải nghiệm học sử trực quan, hấp dẫn.',35000000.00,'goal_reached','2026-09-02 13:26:28.821426','https://github.com/talenthub-demo/heritage-quest-3d','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-26 14:08:48.338256','2026-09-02 13:26:28.821426'),('50000000-0000-4000-8000-000000000003','23000000-0000-4000-8000-000000000001','22000000-dc34-49ed-81d4-78446b313553','Nền tảng Sàn kết nối Nông sản số & Truy xuất nguồn gốc','Kinh tế số & Thương mại điện tử','Sàn thương mại điện tử kết nối nông sản OCOP Đồng bằng Sông Cửu Long, tích hợp tem QR truy xuất nguồn gốc nông trại và thanh toán trực tuyến an toàn.',30000000.00,'open',NULL,'https://github.com/talenthub-demo/agri-bridge-ecom','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-26 14:08:48.338256','2026-08-31 09:44:09.907440'),('50000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','Hệ thống Cảnh báo Sớm An toàn Mạng & Phòng chống Bắt nạt Học đường (EduShield)','career_technical','Vấn đề: Các dấu hiệu bắt nạt và lừa đảo trực tuyến thường được phát hiện quá muộn trong môi trường học đường. Người dùng: học sinh, giáo viên chủ nhiệm và bộ phận tư vấn học đường của THPT Nguyễn Trãi. Hạng mục chính: khảo sát tình huống rủi ro, xây dựng bộ quy tắc cảnh báo, thử nghiệm quy trình tiếp nhận an toàn Sản phẩm bàn giao: một nguyên mẫu cảnh báo sớm kèm cẩm nang phản hồi và báo cáo thử nghiệm bảo vệ quyền riêng tư.',20000000.00,'goal_reached','2026-09-02 13:26:28.821426','https://github.com/talenthub-demo/edushield-safety','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-26 14:08:48.338256','2026-09-02 13:26:28.821426'),('51000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','Trợ lý AI Ôn tập Cá nhân hóa cho Học sinh THPT','career_technical','Vấn đề: Học sinh chưa có một công cụ giúp nhận biết phần kiến thức yếu và sắp xếp nội dung ôn tập theo tiến độ cá nhân. Người dùng: học sinh lớp 10 đến lớp 12 và giáo viên bộ môn tại THPT Nguyễn Trãi. Hạng mục chính: phân tích nhu cầu học tập, xây dựng logic gợi ý bằng Python, đánh giá lời giải thích với người dùng Sản phẩm bàn giao: một trợ lý ôn tập có bảng tiến độ, gợi ý bài học và báo cáo kiểm thử tính hữu ích, minh bạch.',18000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-ai-study-assistant','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('51000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','Bảng Điều khiển Dữ liệu Học tập và Chuyên cần','career_technical','Vấn đề: Dữ liệu điểm số và chuyên cần đang phân tán nên giáo viên khó nhận biết sớm học sinh cần được hỗ trợ. Người dùng: ban học tập, giáo viên chủ nhiệm và học sinh THPT Nguyễn Trãi. Hạng mục chính: chuẩn hóa dữ liệu mẫu, xây dựng chỉ số học tập, thiết kế dashboard và kiểm tra khả năng đọc hiểu Sản phẩm bàn giao: một dashboard bảo vệ dữ liệu cá nhân, có bộ lọc lớp, cảnh báo xu hướng và tài liệu giải thích chỉ số.',16000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-learning-dashboard','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('51000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','GreenSchool Map — Bản đồ Sống xanh trong Khuôn viên','career_sports_academic','Vấn đề: Nhà trường chưa có bản đồ trực quan ghi nhận điểm xanh, nơi phân loại rác và khu vực cần cải thiện môi trường. Người dùng: toàn thể học sinh, câu lạc bộ môi trường và tổ quản trị cơ sở vật chất. Hạng mục chính: khảo sát thực địa theo nhóm, chuẩn hóa vị trí và ảnh minh chứng, thiết kế bản đồ cùng đề xuất cải thiện Sản phẩm bàn giao: một bản đồ số tương tác, bộ dữ liệu đã kiểm chứng và kế hoạch hành động xanh theo từng khu vực.',12000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-green-school-map','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('51000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','SafeNet Student — Cẩm nang Nhận diện Lừa đảo Trực tuyến','career_technical','Vấn đề: Học sinh tiếp xúc với nhiều thông điệp lừa đảo nhưng thiếu tình huống thực hành để nhận diện và phản ứng an toàn. Người dùng: học sinh THPT, phụ huynh và giáo viên phụ trách kỹ năng số. Hạng mục chính: thu thập mẫu tình huống đã ẩn danh, phân loại dấu hiệu lừa đảo, thiết kế nội dung hướng dẫn dễ hiểu Sản phẩm bàn giao: một cẩm nang số có câu hỏi tình huống, cây quyết định phản ứng và bộ tài liệu truyền thông học đường.',10000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-safenet-student','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('51000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','Ký ức Nguyễn Trãi — Bảo tàng Số Lịch sử Nhà trường','career_arts','Vấn đề: Tư liệu lịch sử của nhà trường chưa được kể lại theo một trải nghiệm số hấp dẫn và dễ tiếp cận với học sinh mới. Người dùng: học sinh, cựu học sinh, giáo viên và khách tham quan THPT Nguyễn Trãi. Hạng mục chính: nghiên cứu và xác minh tư liệu, xây dựng câu chuyện theo mốc thời gian, thiết kế triển lãm số có chú thích Sản phẩm bàn giao: một bảo tàng số responsive gồm bộ sưu tập đã cấp quyền, dòng thời gian và hướng dẫn đóng góp tư liệu.',15000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-digital-museum','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('51000000-0000-4000-8000-000000000006','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','SmartClass IoT — Giám sát Chất lượng Không khí Lớp học','career_technical','Vấn đề: Lớp học chưa có dữ liệu liên tục về nhiệt độ, độ ẩm và chất lượng không khí để điều chỉnh thông gió hợp lý. Người dùng: học sinh, giáo viên và tổ quản trị phòng học của THPT Nguyễn Trãi. Hạng mục chính: lắp cảm biến mẫu an toàn, thu thập và làm sạch dữ liệu, xây dựng cảnh báo cùng dashboard theo thời gian Sản phẩm bàn giao: một trạm đo thử nghiệm, dashboard Python và báo cáo khuyến nghị vận hành lớp học dựa trên dữ liệu.',22000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-smartclass-iot','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('51000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000053','Youth Startup Fair — Gian hàng Khởi nghiệp Học sinh','career_business','Vấn đề: Nhiều ý tưởng học sinh chưa được kiểm chứng với người dùng hoặc trình bày bằng mô hình tài chính cơ bản. Người dùng: các nhóm học sinh, giáo viên cố vấn và khách tham quan ngày hội khởi nghiệp. Hạng mục chính: khảo sát nhu cầu, xây dựng mô hình giá trị và ngân sách, chuẩn bị gian hàng cùng bài thuyết trình Sản phẩm bàn giao: một gian hàng thử nghiệm, hồ sơ mô hình kinh doanh và báo cáo phản hồi khách hàng có số liệu.',14000000.00,'open',NULL,'https://github.com/talenthub-demo/nguyen-trai-youth-startup-fair','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('52000000-0000-4000-8000-000000000001','22000000-b512-4ede-852b-f4a508f3e837','22000000-a084-4652-8a62-805d1613cf38','FPT Smart Campus — Tối ưu Năng lượng bằng IoT và Dữ liệu','career_technical','Vấn đề: Mức tiêu thụ điện tại các khu học tập chưa được phân tích theo khung giờ để phát hiện điểm lãng phí và cơ hội tối ưu. Người dùng: ban vận hành, sinh viên và các nhóm nghiên cứu phát triển bền vững Đại học FPT. Hạng mục chính: xây dựng mô hình dữ liệu cảm biến, phân tích tải tiêu thụ, thử nghiệm cảnh báo và kịch bản tiết kiệm Sản phẩm bàn giao: một dashboard năng lượng, mô hình cảnh báo bất thường và báo cáo tác động với giả định được công khai.',30000000.00,'open',NULL,'https://github.com/talenthub-demo/fpt-smart-campus','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('52000000-0000-4000-8000-000000000002','22000000-b512-4ede-852b-f4a508f3e837','22000000-a084-4652-8a62-805d1613cf38','AI Career Mentor — Trợ lý Định hướng Nghề nghiệp Sinh viên','career_technical','Vấn đề: Sinh viên cần một trải nghiệm hướng nghiệp giải thích được gợi ý thay vì chỉ đưa ra danh sách nghề nghiệp chung chung. Người dùng: sinh viên các năm học và chuyên viên dịch vụ nghề nghiệp Đại học FPT. Hạng mục chính: nghiên cứu nhu cầu và nguyên tắc an toàn, thiết kế hội thoại cùng cách giải thích bằng chứng, kiểm thử trải nghiệm với nhiều hồ sơ Sản phẩm bàn giao: một trợ lý hướng nghiệp mẫu, bộ tiêu chí minh bạch và báo cáo kiểm thử thiên lệch, tính hữu ích.',24000000.00,'open',NULL,'https://github.com/talenthub-demo/fpt-ai-career-mentor','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('52000000-0000-4000-8000-000000000003','22000000-b512-4ede-852b-f4a508f3e837','22000000-a084-4652-8a62-805d1613cf38','FinGuard Lab — Phát hiện Giao dịch Bất thường','career_technical','Vấn đề: Các mẫu giao dịch bất thường khó nhận biết bằng quy tắc đơn giản và cần được giải thích rõ để người phân tích kiểm tra. Người dùng: sinh viên fintech, giảng viên hướng dẫn và nhóm phân tích rủi ro mô phỏng. Hạng mục chính: tạo dữ liệu giao dịch ẩn danh, xây dựng đặc trưng và mô hình phát hiện, thiết kế màn hình giải thích cảnh báo Sản phẩm bàn giao: một phòng lab dữ liệu, mô hình baseline có chỉ số đánh giá và dashboard giải thích từng cảnh báo.',32000000.00,'open',NULL,'https://github.com/talenthub-demo/fpt-finguard-lab','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('52000000-0000-4000-8000-000000000004','22000000-b512-4ede-852b-f4a508f3e837','22000000-a084-4652-8a62-805d1613cf38','Inclusive Campus UX — Thiết kế Trải nghiệm Số Tiếp cận','career_arts','Vấn đề: Một số luồng dịch vụ số trong trường còn khó sử dụng với người có nhu cầu tiếp cận khác nhau hoặc thiết bị hạn chế. Người dùng: sinh viên, cán bộ hỗ trợ và người dùng có nhu cầu tiếp cận tại Đại học FPT. Hạng mục chính: phỏng vấn người dùng có đồng thuận, đánh giá rào cản theo tiêu chí tiếp cận, thiết kế và kiểm thử nguyên mẫu Sản phẩm bàn giao: một prototype truy cập được, thư viện thành phần cơ bản và báo cáo nghiên cứu nêu rõ phát hiện, giới hạn.',20000000.00,'open',NULL,'https://github.com/talenthub-demo/fpt-inclusive-campus-ux','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('52000000-0000-4000-8000-000000000005','22000000-b512-4ede-852b-f4a508f3e837','22000000-a084-4652-8a62-805d1613cf38','Mekong Travel Intelligence — Phân tích Dữ liệu Du lịch','career_business','Vấn đề: Dữ liệu du lịch vùng Mekong đến từ nhiều nguồn và chưa được chuyển thành insight dễ hành động cho đơn vị địa phương. Người dùng: doanh nghiệp du lịch nhỏ, nhà quản lý điểm đến và sinh viên nghiên cứu thị trường. Hạng mục chính: thu thập dữ liệu mở có nguồn, phân tích xu hướng và phân khúc, thiết kế câu chuyện dữ liệu cho đối tác Sản phẩm bàn giao: một dashboard du lịch, sổ tay chất lượng dữ liệu và bộ khuyến nghị được gắn với bằng chứng định lượng.',28000000.00,'open',NULL,'https://github.com/talenthub-demo/mekong-travel-intelligence','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('52000000-0000-4000-8000-000000000006','22000000-b512-4ede-852b-f4a508f3e837','22000000-a084-4652-8a62-805d1613cf38','Social Commerce Analytics — Đo lường Hiệu quả Kinh doanh Số','career_business','Vấn đề: Nhóm bán hàng xã hội thường theo dõi lượt tương tác nhưng thiếu cách liên kết nội dung với chuyển đổi và lợi nhuận. Người dùng: nhóm sinh viên khởi nghiệp, cửa hàng nhỏ và cố vấn kinh doanh số. Hạng mục chính: xác định phễu đo lường, chuẩn hóa dữ liệu chiến dịch, phân tích thử nghiệm nội dung và trình bày insight Sản phẩm bàn giao: một dashboard hiệu quả thương mại, từ điển chỉ số và báo cáo đề xuất chiến dịch dựa trên dữ liệu.',26000000.00,'open',NULL,'https://github.com/talenthub-demo/fpt-social-commerce-analytics','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000001','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','Campus Event Hub — Nền tảng Quản lý Sự kiện Sinh viên','career_technical','Vấn đề: Thông tin sự kiện và đăng ký tham gia đang phân tán khiến sinh viên khó theo dõi lịch, trạng thái và minh chứng tham dự. Người dùng: sinh viên, câu lạc bộ và cán bộ phụ trách hoạt động tại BTEC FPT. Hạng mục chính: khảo sát quy trình hiện tại, thiết kế backend đăng ký và phân quyền, xây dựng giao diện cùng kiểm thử luồng chính Sản phẩm bàn giao: một ứng dụng full-stack quản lý sự kiện, tài liệu API, bộ kiểm thử và báo cáo phản hồi người dùng.',22000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-campus-event-hub','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000002','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','BTEC Commerce Studio — Thiết kế lại Trải nghiệm Mua sắm','career_business','Vấn đề: Một cửa hàng trực tuyến mẫu có luồng tìm kiếm và thanh toán chưa rõ ràng, gây khó khăn cho người mua trên di động. Người dùng: người mua trẻ, chủ cửa hàng nhỏ và sinh viên học thiết kế sản phẩm. Hạng mục chính: đánh giá hành trình hiện tại, phỏng vấn và xây dựng persona, thiết kế prototype rồi kiểm thử khả dụng Sản phẩm bàn giao: một prototype thương mại responsive, design rationale và báo cáo kiểm thử với đề xuất ưu tiên cải tiến.',18000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-commerce-studio','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000003','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','Data Storytelling Dashboard — Kể chuyện bằng Dữ liệu','career_technical','Vấn đề: Bảng số liệu hoạt động sinh viên chưa truyền đạt được xu hướng, nguyên nhân và thông điệp chính cho người ra quyết định. Người dùng: sinh viên phân tích dữ liệu, giảng viên và cán bộ quản lý chương trình BTEC. Hạng mục chính: làm sạch bộ dữ liệu mẫu, chọn biểu đồ và xây dựng narrative, kiểm thử khả năng đọc hiểu với người dùng Sản phẩm bàn giao: một dashboard kể chuyện bằng dữ liệu, data dictionary và bản thuyết trình giải thích insight có nguồn.',19000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-data-storytelling','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000004','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','CyberLab Starter — Phòng Thực hành An toàn Ứng dụng Web','career_technical','Vấn đề: Sinh viên cần môi trường an toàn để thực hành nhận diện lỗi ứng dụng web mà không tác động đến hệ thống thật. Người dùng: sinh viên phát triển phần mềm và giảng viên hướng dẫn an toàn thông tin BTEC. Hạng mục chính: xây dựng ứng dụng lab cô lập, soạn bài thực hành theo mức độ, thiết kế cơ chế reset và ghi nhận kết quả Sản phẩm bàn giao: một cyberlab cục bộ, bốn kịch bản thực hành có hướng dẫn và báo cáo biện pháp phòng vệ tương ứng.',23000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-cyberlab-starter','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000005','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','HabitFlow Mobile — Ứng dụng Theo dõi Thói quen Học tập','career_technical','Vấn đề: Sinh viên khó duy trì thói quen học đều khi mục tiêu, nhắc việc và phản hồi tiến độ nằm ở nhiều công cụ khác nhau. Người dùng: sinh viên BTEC muốn xây dựng nhịp học tập bền vững và cố vấn học tập. Hạng mục chính: nghiên cứu hành vi và quyền riêng tư, thiết kế luồng mobile, xây dựng theo dõi tiến độ và kiểm thử thông báo Sản phẩm bàn giao: một ứng dụng mobile mẫu, prototype tương tác, bộ dữ liệu thử nghiệm và báo cáo đánh giá trải nghiệm.',17000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-habitflow-mobile','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000006','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','Brand Launch 360 — Chiến dịch Ra mắt Thương hiệu Số','career_business','Vấn đề: Một thương hiệu sinh viên mới chưa có định vị, hệ thống nội dung và chỉ số để đánh giá hoạt động ra mắt trên kênh số. Người dùng: nhóm sinh viên kinh doanh, khách hàng mục tiêu và cố vấn truyền thông BTEC. Hạng mục chính: nghiên cứu phân khúc, xây dựng nhận diện và thông điệp, lập lịch nội dung cùng bộ chỉ số chiến dịch Sản phẩm bàn giao: một bộ nhận diện số, kế hoạch ra mắt đa kênh và báo cáo đo lường thử nghiệm có bài học rút ra.',16000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-brand-launch-360','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000'),('53000000-0000-4000-8000-000000000007','da811c4f-2f74-4fdd-80b0-dd6f26109783','24000000-0000-4000-8000-000000000011','CloudShip — Tự động hóa Triển khai Ứng dụng Sinh viên','career_technical','Vấn đề: Các dự án sinh viên thường triển khai thủ công nên khó lặp lại, dễ sai cấu hình và thiếu bằng chứng chất lượng trước khi phát hành. Người dùng: nhóm phát triển phần mềm, giảng viên chấm dự án và người vận hành môi trường lab BTEC. Hạng mục chính: khảo sát quy trình triển khai, xây dựng pipeline kiểm thử và đóng gói, thiết kế môi trường staging cùng giám sát cơ bản Sản phẩm bàn giao: một pipeline CI/CD chạy được, cấu hình hạ tầng mẫu, runbook phục hồi và báo cáo kiểm chứng từng bước.',25000000.00,'open',NULL,'https://github.com/talenthub-demo/btec-cloudship','2026-09-01 08:00:00.000000','2027-12-31 17:00:00.000000','in_progress','2026-08-30 00:00:00.000000','2026-08-30 00:00:00.000000');
