--
-- Table structure for table `student_enterprise_school_approvals`
--

DROP TABLE IF EXISTS `student_enterprise_school_approvals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_enterprise_school_approvals` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enterpriseId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `approvedByUserId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `approvedAt` datetime(6) NOT NULL,
  `expiresAt` datetime(6) NOT NULL,
  `revokedAt` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_school_approval_scope` (`studentId`,`enterpriseId`,`revokedAt`,`expiresAt`),
  KEY `fk_school_approval_enterprise` (`enterpriseId`),
  KEY `fk_school_approval_actor` (`approvedByUserId`),
  CONSTRAINT `fk_school_approval_actor` FOREIGN KEY (`approvedByUserId`) REFERENCES `users` (`id`),
