--
-- Table structure for table `student_skills`
--

DROP TABLE IF EXISTS `student_skills`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_skills` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `skillId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `levelScore` decimal(5,2) NOT NULL,
  `sourceType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `verificationStatus` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'self_declared',
  `verifiedAt` datetime(6) DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_student_skills_student_skill_source` (`studentId`,`skillId`,`sourceType`),
  KEY `idx_student_skills_skill` (`skillId`),
  KEY `idx_student_skills_student_verification` (`studentId`,`verificationStatus`),
  CONSTRAINT `fk_student_skills_skill` FOREIGN KEY (`skillId`) REFERENCES `skills` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_student_skills_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_student_skills_level_score` CHECK (((`levelScore` >= 0) and (`levelScore` <= 100))),
  CONSTRAINT `chk_student_skills_source_type` CHECK ((`sourceType` in (_utf8mb4'self_declared',_utf8mb4'assessment',_utf8mb4'teacher',_utf8mb4'activity',_utf8mb4'import'))),
  CONSTRAINT `chk_student_skills_verification` CHECK ((`verificationStatus` in (_utf8mb4'self_declared',_utf8mb4'pending',_utf8mb4'verified',_utf8mb4'rejected'))),
  CONSTRAINT `chk_student_skills_verified_at` CHECK ((((`verificationStatus` = _utf8mb4'verified') and (`verifiedAt` is not null)) or ((`verificationStatus` <> _utf8mb4'verified') and (`verifiedAt` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

