--
-- Table structure for table `test_attempts`
--

DROP TABLE IF EXISTS `test_attempts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `test_attempts` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `testId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress',
  `startedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `submittedAt` datetime(6) DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_test_attempts_test` (`testId`),
  KEY `idx_test_attempts_student_status` (`studentId`,`status`),
  KEY `idx_test_attempts_student_test` (`studentId`,`testId`,`status`),
  CONSTRAINT `fk_test_attempts_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_test_attempts_test` FOREIGN KEY (`testId`) REFERENCES `talent_tests` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_test_attempts_status` CHECK ((`status` in (_utf8mb4'in_progress',_utf8mb4'submitted',_utf8mb4'expired',_utf8mb4'abandoned'))),
  CONSTRAINT `chk_test_attempts_submitted_at` CHECK ((((`status` = _utf8mb4'submitted') and (`submittedAt` is not null)) or ((`status` <> _utf8mb4'submitted') and (`submittedAt` is null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

